window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0084", [{"word":"transpire","ipa_uk":"/trænˈspaɪə(r)/","ipa_us":"/trænˈspaɪər/","definition_zh":"泄露；发生；蒸发（植物蒸腾）","definition_en":"(of information) to become known; (of an event) to happen; (of a plant) to pass out water as vapor","core_image":"一间密闭屋子的水汽从墙缝慢慢渗出，外面的人这才知道屋里发生了什么","scene":"会议结束后没有人对外说明，可几周后细节还是慢慢传了出来。 Few expected the secret to transpire so quickly.","sceneCN":"这里该词指「原本隐秘的信息逐渐被人知道」（第 1 个义项：秘密外泄）；句意为几乎没人料到这个秘密会这么快传开。","pos":[{"tag":"vi.","zh":"（秘密、消息）泄露；为人所知"},{"tag":"vi.","zh":"（事件）发生；进行"},{"tag":"vi.","zh":"（植物）蒸腾，散失水汽"},{"tag":"vt.","zh":"（古）使水汽排出；发汗"}],"collocations":[{"phrase":"it transpired that","zh":"后来才知道；据说"},{"phrase":"transpire through the leaves","zh":"通过叶片蒸腾"},{"phrase":"transpire from the skin","zh":"从皮肤排出水汽"},{"phrase":"a secret transpires","zh":"秘密泄露"},{"phrase":"what transpired at the meeting","zh":"会上发生的事"},{"phrase":"nothing transpired","zh":"什么事也没有发生"}],"forms":[{"label":"三单（第三人称单数）","form":"transpires"},{"label":"过去式","form":"transpired"},{"label":"过去分词","form":"transpired"},{"label":"现在分词","form":"transpiring"},{"label":"名词（蒸腾作用）","form":"transpiration"},{"label":"形容词（蒸腾的）","form":"transpiratory"}],"derivatives":[{"word":"transpiration","pos":"n.","zh":"蒸腾作用；水汽散失"},{"word":"transpiratory","pos":"adj.","zh":"蒸腾的；与蒸腾有关的"},{"word":"transpirable","pos":"adj.","zh":"可蒸腾的；可透出的（少用）"},{"word":"perspire","pos":"v.","zh":"出汗（同词根，前缀不同）"},{"word":"inspire","pos":"v.","zh":"吸气；鼓舞（同词根，前缀不同）"}],"senses":[{"no":"01","title":"Become known","titleCN":"秘密泄露，被人知道","definition":"to become known, especially when something has been kept secret","definitionCN":"被人知道；（秘密）泄露","example":"It later transpired that the manager had known about the fault for months.","exampleCN":"后来才知道，经理几个月前就已经知道这个故障。","why":"The image is vapor escaping through a crack: information that was sealed inside finds a way out.","whyCN":"意象是水汽从裂缝里逃出去：被封在里面的信息找到了出口。"},{"no":"02","title":"Happen or take place","titleCN":"发生；进行","definition":"to happen or take place, especially when the event is not widely observed","definitionCN":"发生；进行（多指未被广泛看到的事件）","example":"Nobody could say what had transpired during the closed meeting.","exampleCN":"没人说得清那次闭门会议期间究竟发生了什么。","why":"Once an event has happened it enters the record, so the word treats the event as something that comes out into the open.","whyCN":"事件一旦发生就进入记录，因此这个词把事件看作「走到明处」的东西。"},{"no":"03","title":"Lose water through a plant","titleCN":"植物蒸腾，散失水汽","definition":"to lose water as vapor through the surface of a plant","definitionCN":"（植物）通过体表散失水汽；蒸腾","example":"Most of the water taken up by the tree transpires through its leaves.","exampleCN":"这棵树吸收的水大部分通过叶片蒸腾掉了。","why":"This is the original physical sense: moisture passes through the leaf and escapes into the air.","whyCN":"这是最早的物理义：水分穿过叶片，逸散到空气里。"},{"no":"04","title":"Emit vapor through the skin","titleCN":"皮肤排出水汽（旧医学用法）","definition":"to pass moisture out through the skin as vapor","definitionCN":"（旧医学）皮肤排出不可见的水汽","example":"In old medical texts, the skin was said to transpire at night.","exampleCN":"在旧医学文献里，据说皮肤在夜间会排出水汽。","why":"Physicians once described invisible perspiration as vapor leaving the body.","whyCN":"旧时医生把看不见的出汗描述成水汽离开身体。"},{"no":"05","title":"Pass through a barrier as vapor","titleCN":"以水汽形式穿过隔层","definition":"to pass through a porous material in the form of vapor","definitionCN":"以水汽形式穿过多孔材料","example":"Water can transpire through the thin membrane in the experiment.","exampleCN":"在实验中，水能以水汽形式穿过那层薄膜。","why":"The prefix means through and the root means breathe, giving the sense of vapor travelling through a barrier.","whyCN":"前缀意为「穿过」，词根意为「呼吸」，合起来就是水汽穿过隔层。"},{"no":"06","title":"Surface gradually","titleCN":"逐步显露；渐次传开","definition":"to be revealed gradually rather than all at once","definitionCN":"不是一次全部公开，而是一点点显露出来","example":"The full story transpired over several weeks of interviews.","exampleCN":"完整的故事是在数周访谈中一点点显露出来的。","why":"The leak metaphor is stretched over time: one fact after another comes to the surface.","whyCN":"「渗漏」的比喻被拉长到时间轴上：一个事实接一个事实浮出水面。"},{"no":"07","title":"Nothing happened","titleCN":"（否定式）什么事也没发生","definition":"used with nothing or little to say that no event of interest occurred","definitionCN":"与否定词连用，表示没有值得注意的事发生","example":"Nothing transpired that required the committee to meet again.","exampleCN":"没有发生任何需要委员会再次开会的事。","why":"This is the happening sense inside a negative frame: the record of events stays empty.","whyCN":"这是「发生」义放在否定框架里：事件记录始终空着。"},{"no":"08","title":"Turn out to be","titleCN":"结果是；原来是","definition":"to turn out to be the case","definitionCN":"结果是；原来是（正式书面语）","example":"The rumored merger transpired to be a routine contract review.","exampleCN":"传闻中的合并原来只是一次例行的合同审查。","why":"What comes out at the end is the truth of the matter, so the verb comes to mean prove to be.","whyCN":"最后「走出来的」是事情的真相，于是这个词也有了「证明是」的意思。"}],"etymology":{"intro":{"en":"The elements are Latin. Dates for the later senses are approximate, and the link between the physical and the disclosing senses is an inference rather than a documented fact.","cn":"词源为拉丁语，各引申义的具体年代为大致估计；物理义与「泄露」义之间的联系属于推断，而非有文献直接证明。"},"items":[{"era":"LATIN (1st c. BC)","en":"The elements are trans- 'across, through' and spirare 'to breathe, blow' (spiro, spiravi, spiratum). A Late Latin verb transpirare is sometimes cited for the physical sense, but its attestation is not secure.","cn":"构词成分是拉丁语 trans-「穿过、越过」与 spirare「呼吸、吹气」（spiro、spiravi、spiratum）。有时会引用晚期拉丁语动词 transpirare 来解释物理义，但该词的出现证据并不确实。"},{"era":"OLD FRENCH (16th c.)","en":"Middle French transpirer meant 'to evaporate, to pass out through the pores'. English borrowed the verb in the 1590s, first in the bodily and physical sense.","cn":"中古法语 transpirer 意为「蒸发、从毛孔透出」。英语在十六世纪九十年代借入该动词，最初用于身体与物理意义。"},{"era":"ENGLISH (17th c.)","en":"Seventeenth-century medical writing used transpire for invisible moisture leaving the body, a sense now archaic but still found in older texts.","cn":"十七世纪的医学写作使用 transpire 指看不见的湿气离开身体；这一义项现已古旧，但仍见于旧文献。"},{"era":"ENGLISH (18th c.)","en":"The sense 'to become known' is recorded in 1748. It is generally thought to be a metaphor of vapor escaping through pores, but the exact motivation is uncertain.","cn":"「被人知道」这一义项记录于 1748 年。一般认为它是「水汽从孔隙逸出」的比喻，但确切理据存疑。"},{"era":"ENGLISH (18th-19th c.)","en":"The sense 'to happen, occur' appears in the mid-eighteenth century, and the weaker sense 'to turn out to be' develops in the nineteenth.","cn":"「发生、进行」义出现在十八世纪中期；较弱的「结果是」义在十九世纪发展出来。"},{"era":"MODERN ENGLISH","en":"Modern usage is formal and often journalistic. In speech, come out, turn out and leak out are more common than transpire.","cn":"现代用法偏正式，常见于新闻文体。口语里比 transpire 更常用的是 come out、turn out 与 leak out。"}]},"similar":{"note":{"en":"The words below are close to transpire in sound or meaning. The first group shares the Latin root but not the prefix; the second group overlaps in meaning without sharing the root.","cn":"下面这些词在读音或意思上接近 transpire。第一组共享拉丁词根但前缀不同；第二组意思相近但不同源。"},"groups":[{"heading":"SAME ROOT, DIFFERENT PREFIX","entries":[{"word":"inspire","ipa":"/ɪnˈspaɪə(r)/","tag":"same root","definition":"to breathe in; to fill someone with a strong feeling. The prefix in- means in, so the image is air or spirit entering.","definitionCN":"吸气；使受到鼓舞。前缀 in- 意为「进入」，意象是气息或精神进入体内。"},{"word":"perspire","ipa":"/pəˈspaɪə(r)/","tag":"same root, closest meaning","definition":"to sweat. The prefix per- means through, so moisture passes through the skin; this is the everyday bodily counterpart of transpire.","definitionCN":"出汗。前缀 per- 意为「穿过」，水汽穿过皮肤排出；这是 transpire 在日常身体语境中的对应词。"},{"word":"expire","ipa":"/ɪkˈspaɪə(r)/","tag":"same root","definition":"to breathe out; to come to an end. The prefix ex- means out, and the 'end' sense comes from the last breath.","definitionCN":"呼气；到期、终止。前缀 ex- 意为「向外」，「结束」义来自最后一口气。"},{"word":"aspire","ipa":"/əˈspaɪə(r)/","tag":"same root","definition":"to aim at something high. The prefix ad- suggests movement toward a goal, literally 'breathe toward'.","definitionCN":"渴望达到；立志。前缀 ad- 表示朝目标移动，字面是「朝某处呼吸」。"}]},{"heading":"NEAR-MEANING","entries":[{"word":"happen","ipa":"/ˈhæpən/","tag":"general verb","definition":"the neutral everyday verb for an event taking place; it carries no suggestion of secrecy or formality.","definitionCN":"发生。最中性的日常动词，不暗示秘密，也不带正式语体色彩。"},{"word":"occur","ipa":"/əˈkɜː(r)/","tag":"formal synonym","definition":"a more formal verb for an event taking place, common in reports and academic writing.","definitionCN":"发生。较正式的动词，常见于报告与学术写作。"},{"word":"leak","ipa":"/liːk/","tag":"deliberate disclosure","definition":"to disclose information, often unofficially or against the wishes of those in control; the focus is on the channel, not the event.","definitionCN":"泄露。常指非官方、违背掌权者意愿地透露信息；重点在渠道，而非事件本身。"},{"word":"come to light","ipa":"/kʌm tə laɪt/","tag":"idiomatic phrase","definition":"a plain phrase meaning to become known, with no implication about how the information escaped.","definitionCN":"为人所知。平实的短语，不暗示信息是如何走漏的。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"trans- 'through' plus the root for 'breathe': breath passing through a surface.","cn":"trans-「穿过」加上「呼吸」词根：气息穿过一层表面。"},{"en":"The same root builds inspire, perspire, expire and aspire, each with a different prefix.","cn":"同一词根还构成 inspire、perspire、expire 与 aspire，各自前缀不同。"},{"en":"The fixed frame it transpired that introduces news that was previously hidden.","cn":"固定框架 it transpired that 引出此前被隐藏的消息。"},{"en":"Botany pairs transpire with stomata and transpiration.","cn":"植物学里 transpire 与气孔、蒸腾作用配套使用。"},{"en":"The verb is formal; speech prefers turn out, come out or leak out.","cn":"这个词偏正式；口语更常说 turn out、come out 或 leak out。"}],"abstract":[{"en":"Picture a sealed envelope that lets a thin mist out through its fold.","cn":"想象一只封住的信封，从折缝里透出一缕薄雾。"},{"en":"Picture a stage curtain opening a little at a time, the story behind it showing in slices.","cn":"想象舞台幕布一点点拉开，后面的故事一段段显形。"},{"en":"Picture a kettle left unwatched until only a white ring remains on the base.","cn":"想象一只没人看管的水壶，最后只剩壶底一圈白痕。"}]},"examples":[{"en":"The ministry later confirmed what had transpired behind closed doors.","cn":"该部后来证实了闭门会议背后发生的事。"},{"en":"Water transpires from the leaves and returns to the atmosphere.","cn":"水从叶片蒸腾，回到大气中。"},{"en":"Nothing transpired until a junior clerk mentioned the file by accident.","cn":"直到一名低级职员偶然提到那份档案，事情才露了出来。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「穿过 + 呼吸」——气息穿过叶面跑掉 → 蒸发；消息穿过墙缝跑出来 → 泄露","word":"transpire"},"root":"拉丁 spirare「呼吸、吹气」加 trans-「穿过」，经法语 transpirer 进入英语。物理义为「水汽穿出」，而「泄露」义一般认为是这一意象的比喻延伸，具体理据与年代存疑。","sensesIntro":{"en":"Eight senses follow one movement: something sealed passes through a barrier and becomes visible. The movement is physical in the plant and skin senses, informational in the disclosure senses, and finally temporal in the event and outcome senses.","cn":"八个义项沿同一个动作展开：被封闭的东西穿过一层屏障而显形。在植物与皮肤义里这是物理移动，在披露义里是信息移动，最后在事件与结果义里变成时间上的浮现。"},"semanticMap":{"core":{"en":"CORE IMAGE: mist slipping out of a sealed room through a narrow crack.","cn":"核心意象：雾气从密闭房间的窄缝里逸出。"},"chain":["BREATHE THROUGH","ESCAPE AS VAPOR","LEAVE THE BODY","BECOME KNOWN","HAPPEN","PROVE TO BE"],"branches":[{"senses":"01 · 06","en":"LEAK AND SURFACE: the secret and the gradually told story are the same escape seen at two speeds.","cn":"泄露与浮现：秘密与逐步讲出的故事，是同一场逃逸的快慢两个版本。"},{"senses":"02 · 07","en":"EVENT RECORD: the happening sense, including its negative use, asks what entered the record.","cn":"事件记录：发生义连同否定用法，问的都是记录里多了什么。"},{"senses":"03 · 04","en":"PHYSICAL EMISSION: leaf and skin both let moisture pass out of the body.","cn":"物理排放：叶片与皮肤都让湿气离开本体。"},{"senses":"05","en":"THROUGH A BARRIER: the technical sense keeps only the crossing, with no observer.","cn":"穿过屏障：技术义只保留穿越本身，不涉及观察者。"},{"senses":"08","en":"PROVE TO BE: what finally comes out is not an event but its true character.","cn":"证明是：最后走出来的不是事件，而是事件的真实性质。"}]},"affixes":{"intro":{"en":"Transpire is a Latin-built verb whose prefix and root also build a large family of English words, so the whole set can be read morpheme by morpheme.","cn":"transpire 是由拉丁成分构成的动词，前缀与词根还构成一大串英语词，因此整组词可以按语素逐个读出。"},"latinIntro":{"en":"Latin spirare gives spirit, inspire, expire, perspire and aspire; trans- adds the idea of crossing or passing through.","cn":"拉丁 spirare 衍生 spirit、inspire、expire、perspire 与 aspire；trans- 增添「越过、穿过」的意思。"},"latinEntries":[{"word":"spirare","structure":"spirare, spiravi, spiratum (verb, first conjugation)","meaning":"to breathe, to blow","meaningCN":"呼吸；吹气"},{"word":"spiritus","structure":"spiritus, spiritus (m., fourth declension)","meaning":"breath, spirit","meaningCN":"气息；精神"},{"word":"transpirare","structure":"transpirare (Late Latin verb, attestation uncertain)","meaning":"to breathe through, to pass out as vapor","meaningCN":"透出气息；以水汽形式散出"},{"word":"trans","structure":"trans- (Latin prefix)","meaning":"across, through, beyond","meaningCN":"穿过；越过；在……之外"}],"items":[{"word":"trans-","structure":"trans- (Latin prefix, 'across, through')","meaning":"across; through","meaningCN":"穿过；越过","example":"The prefix supplies the crossing in every member of the family.","exampleCN":"这个前缀为整个词族提供「穿越」的意思。"},{"word":"spirare","structure":"spirare (Latin verb, 'to breathe')","meaning":"to breathe; to blow","meaningCN":"呼吸；吹气","example":"The root gives the image of air in motion.","exampleCN":"这个词根给出「空气在动」的意象。"},{"word":"transpire","structure":"trans- + spirare","meaning":"to pass out as vapor; to become known","meaningCN":"以水汽散出；泄露","example":"Few expected the secret to transpire.","exampleCN":"几乎没人料到秘密会泄露。"},{"word":"transpiration","structure":"transpire + -ation (action or result)","meaning":"the loss of water vapor from a plant","meaningCN":"植物蒸腾（作用）","example":"Transpiration cools the leaf in strong sun.","exampleCN":"强烈日照下蒸腾为叶片降温。"},{"word":"transpired","structure":"transpire + -ed (past participle)","meaning":"having come out or happened","meaningCN":"已泄露的；已发生的","example":"The transpired facts changed the inquiry.","exampleCN":"已披露的事实改变了调查方向。"},{"word":"transpiring","structure":"transpire + -ing (present participle)","meaning":"in the process of becoming known","meaningCN":"正在泄露的；正在发生的","example":"Reports transpiring this week point to a wider dispute.","exampleCN":"本周陆续传出的报道指向一场更大的争端。"},{"word":"perspire","structure":"per- + spirare","meaning":"to sweat through the skin","meaningCN":"出汗；排汗","example":"He perspired heavily in the unventilated room.","exampleCN":"他在不通风的房间里大量出汗。"},{"word":"inspiration","structure":"in- + spirare + -ation","meaning":"a breath of air; a creative impulse","meaningCN":"吸气；灵感","example":"The design took its inspiration from a leaf.","exampleCN":"这个设计从一片叶子获得灵感。"},{"word":"expiration","structure":"ex- + spirare + -ation","meaning":"breathing out; the end of a period","meaningCN":"呼气；到期","example":"The expiration date is printed on the lid.","exampleCN":"到期日印在盖子上。"}]}},{"word":"evaporation","ipa_uk":"/ɪˌvæpəˈreɪʃn/","ipa_us":"/ɪˌvæpəˈreɪʃn/","definition_zh":"蒸发；蒸发量；蒸干浓缩","definition_en":"the process by which a liquid changes into vapor at its surface, or the loss of moisture caused by this process","core_image":"一只浅盘里的水在阳光下越来越薄，盘底慢慢露出一圈白色的盐痕","scene":"雨后的水洼在午后阳光下缩小，傍晚只剩一圈浅浅的湿痕。 A shallow puddle shrinks under the afternoon sun, and by evening only a damp ring remains: that steady loss of water is evaporation.","sceneCN":"这里该词指「液体在表面缓慢变成水汽而减少」（第 1 个义项：液面汽化）；句意为水洼在阳光下缩小，到傍晚只剩湿痕，这种持续失水就是蒸发。","pos":[{"tag":"n.","zh":"蒸发（作用）；汽化"},{"tag":"n.","zh":"蒸发量；水分损失量"},{"tag":"n.","zh":"蒸干；通过蒸发使溶液浓缩"},{"tag":"n.","zh":"（比喻）逐渐消失；消散"}],"collocations":[{"phrase":"rate of evaporation","zh":"蒸发速率"},{"phrase":"evaporation from the soil","zh":"土壤蒸发"},{"phrase":"evaporation of water","zh":"水的蒸发"},{"phrase":"evaporation basin","zh":"蒸发池"},{"phrase":"evaporation residue","zh":"蒸发残渣"},{"phrase":"reduce by evaporation","zh":"通过蒸发浓缩"}],"forms":[{"label":"复数（多种蒸发过程或多次测定）","form":"evaporations"},{"label":"动词（蒸发）","form":"evaporate"},{"label":"形容词（蒸发的）","form":"evaporative"},{"label":"相关名词（蒸发器）","form":"evaporator"},{"label":"相关名词（蒸腾）","form":"transpiration"}],"derivatives":[{"word":"evaporate","pos":"v.","zh":"蒸发；使蒸发；消失"},{"word":"evaporative","pos":"adj.","zh":"蒸发的；蒸发式的"},{"word":"evaporator","pos":"n.","zh":"蒸发器"},{"word":"evapotranspiration","pos":"n.","zh":"蒸散（蒸发与蒸腾之和）"},{"word":"vapor","pos":"n.","zh":"水汽；蒸汽"}],"senses":[{"no":"01","title":"Liquid turning into vapor","titleCN":"液体在表面变成水汽","definition":"the process in which molecules at the surface of a liquid escape into the air as vapor","definitionCN":"液体表面分子逸入空气、变成水汽的过程","example":"Evaporation from the open tank continues even when the water is cool.","exampleCN":"即使水是凉的，敞口罐里的水仍在持续蒸发。","why":"Only surface molecules can leave; the liquid does not need to boil. This is the physical core of the word.","whyCN":"只有表面分子能逃出去，液体不必沸腾。这是这个词的物理核心。"},{"no":"02","title":"Loss of moisture from a surface","titleCN":"表面失水变干","definition":"the drying of soil, skin, laundry or pavement as moisture leaves it","definitionCN":"土壤、皮肤、衣物或路面因水分离开而变干","example":"Covering the seedbed slows evaporation and keeps the soil moist.","exampleCN":"覆盖苗床能减缓蒸发，让土壤保持湿润。","why":"The same physical process seen from the side of the material: what matters is how much water it loses.","whyCN":"同一个物理过程从材料一侧看：重点是它失去了多少水。"},{"no":"03","title":"Concentration by boiling off water","titleCN":"通过蒸干水分而浓缩","definition":"the removal of water by heating so that a solution becomes more concentrated","definitionCN":"加热除去水分，使溶液变得更浓","example":"Salt is obtained from seawater by evaporation in shallow pans.","exampleCN":"盐是通过在浅盘中蒸发海水得到的。","why":"Here evaporation is used as a tool: the water is unwanted, and what stays behind is the product.","whyCN":"这里蒸发是工具：水是不要的部分，留下来的才是产物。"},{"no":"04","title":"Water-cycle flux","titleCN":"水循环中的蒸发通量","definition":"the movement of water from land and water bodies into the atmosphere, treated as a measurable part of the water cycle","definitionCN":"水从陆地和有水表面进入大气，作为水循环中可测量的一环","example":"Satellites estimate evaporation over the ocean by tracking water vapor.","exampleCN":"卫星通过追踪水汽来估算海面上的蒸发量。","why":"In earth science the process is treated as a flux: water leaves a surface at a measurable rate.","whyCN":"在地球科学里，这一过程被当作通量：水以可测的速度离开某个表面。"},{"no":"05","title":"Amount evaporated","titleCN":"蒸发量","definition":"the quantity of water lost by evaporation, usually measured over a period","definitionCN":"一段时间内因蒸发失去的水量","example":"The pan recorded an evaporation of four millimeters overnight.","exampleCN":"蒸发皿记录到一夜之间蒸发了四毫米。","why":"The process name is transferred to its measured result, a common pattern in scientific vocabulary.","whyCN":"过程名称被转用到测量结果上，这是科学词汇常见的转义方式。"},{"no":"06","title":"Vaporization below boiling","titleCN":"低于沸点的汽化","definition":"vaporization that occurs below the boiling point, especially in physics and engineering","definitionCN":"在沸点以下发生的汽化，尤用于物理与工程","example":"Evaporation differs from boiling because it needs no bubbles.","exampleCN":"蒸发与沸腾不同，因为它不需要气泡。","why":"Physics separates evaporation from boiling by mechanism, not by speed.","whyCN":"物理学按机制而非速度把蒸发与沸腾区分开。"},{"no":"07","title":"Figurative disappearance","titleCN":"比喻义：逐渐消失","definition":"the gradual disappearance of money, support, confidence or another abstract quantity","definitionCN":"钱、支持、信心等抽象之物的逐渐消失","example":"The evaporation of public trust followed the repeated delays.","exampleCN":"反复拖延之后，公众信任逐渐消失。","why":"The metaphor treats an abstract quantity as a liquid that silently thins out.","whyCN":"这个比喻把抽象之物当成一种无声变薄的液体。"},{"no":"08","title":"Evaporative cooling","titleCN":"蒸发降温","definition":"cooling produced when a liquid evaporates and takes heat away with it","definitionCN":"液体蒸发带走热量而产生的降温","example":"Sweating relies on evaporation to lower body temperature.","exampleCN":"出汗依靠蒸发来降低体温。","why":"The word names the process that removes heat, so it also names the cooling effect used by organisms and machines.","whyCN":"这个词命名的是带走热量的过程，因此也指生物与机器利用的降温效果。"}],"etymology":{"intro":{"en":"The Latin elements are clear, but the deeper origin of vapor is disputed, and the dates of the technical senses are approximate.","cn":"拉丁成分清楚，但 vapor 更深来源存在争议；技术义的出现年代为大致估计。"},"items":[{"era":"LATIN","en":"The base is vapor 'steam, vapor' with the verb vaporare 'to steam, to be hot'. The prefix e- (before a consonant, from ex-) means 'out of'.","cn":"基础词是 vapor「蒸汽、水汽」与动词 vaporare「冒汽、发热」。前缀 e-（辅音前由 ex- 变来）意为「向外」。"},{"era":"LATE LATIN","en":"Late Latin evaporatio, evaporationis (f., third declension) meant 'a steaming away'. The noun is built from evaporare plus the action suffix -atio.","cn":"晚期拉丁语 evaporatio（属格 evaporationis，阴性第三变格）意为「蒸散」。该名词由 evaporare 加动作后缀 -atio 构成。"},{"era":"ENGLISH (17th c.)","en":"English adopted evaporation in the seventeenth century through scientific French and Latin. Early examples describe the drying of liquids.","cn":"英语在十七世纪经科学法语与拉丁语吸收 evaporation，早期例子描述液体的变干。"},{"era":"ENGLISH (18th-19th c.)","en":"With the growth of chemistry and meteorology, the noun acquired measured and technical uses such as evaporation rate and evaporation residue.","cn":"随着化学与气象学的发展，该名词获得「蒸发速率」「蒸发残渣」等测量与技术用法。"},{"era":"MODERN ENGLISH","en":"The figurative sense for money, trust or hope is a nineteenth- and twentieth-century extension. The underlying image is a liquid thinning until nothing is left.","cn":"用于金钱、信任或希望的比喻义是十九至二十世纪的延伸。底层意象是一种液体不断变薄，直到什么都不剩。"}]},"similar":{"note":{"en":"The first group is close in sound but not in root; the second group shares the physical process or its opposite.","cn":"第一组读音相近但不同源；第二组共享同一物理过程或其反面。"},"groups":[{"heading":"SOUND-ALIKE","entries":[{"word":"evacuation","ipa":"/ˌiːvækjuˈeɪʃn/","tag":"near sound, different root","definition":"the act of moving people out of a dangerous place. It comes from Latin vacuus 'empty', not from vapor.","definitionCN":"撤离；疏散。来自拉丁语 vacuus「空的」，与 vapor 无关。"},{"word":"evaluation","ipa":"/ˌiːvæljuˈeɪʃn/","tag":"near sound, different root","definition":"the act of judging the value or quality of something, from Latin valere 'to be worth'.","definitionCN":"评估；评价。来自拉丁语 valere「有价值」，与蒸发无关。"},{"word":"evapotranspiration","ipa":"/ɪˌvæpəʊtrænspəˈreɪʃn/","tag":"longer technical term","definition":"the combined loss of water by evaporation from the soil and transpiration from plants; it contains evaporation but adds the plant pathway.","definitionCN":"蒸散。土壤蒸发与植物蒸腾之和；词里含 evaporation，但增加了植物这条路径。"}]},{"heading":"NEAR-MEANING","entries":[{"word":"vaporization","ipa":"/ˌveɪpəraɪˈzeɪʃn/","tag":"broader process term","definition":"the general change from liquid to vapor, including boiling; evaporation is the surface-only case.","definitionCN":"汽化。液变气的一般过程，包括沸腾；蒸发只是仅发生在表面的那一种。"},{"word":"condensation","ipa":"/ˌkɒndenˈseɪʃn/","tag":"opposite process","definition":"the change from vapor back to liquid; it is the reverse arrow of the water cycle.","definitionCN":"凝结。水汽变回液体，是水循环里方向相反的一支。"},{"word":"transpiration","ipa":"/ˌtrænspəˈreɪʃn/","tag":"living-plant pathway","definition":"the loss of water vapor through plant surfaces; it is evaporation routed through a living organism.","definitionCN":"蒸腾。水汽经植物表面散失；可以理解为经过活体生物的蒸发。"},{"word":"drying","ipa":"/ˈdraɪɪŋ/","tag":"everyday result word","definition":"the everyday word for becoming dry; it names the result rather than the physical mechanism.","definitionCN":"变干；干燥。日常词，说的是结果，而不是物理机制。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The prefix means 'out' and the base means 'steam': steam going out of a liquid.","cn":"前缀意为「向外」，基础词意为「蒸汽」：蒸汽从液体里出去。"},{"en":"The family runs evaporate, evaporative, evaporator and evapotranspiration.","cn":"同族词包括 evaporate、evaporative、evaporator 与 evapotranspiration。"},{"en":"Science fixes the collocations: evaporation rate, evaporation residue, evaporation pan.","cn":"科学语境固定搭配：蒸发速率、蒸发残渣、蒸发皿。"},{"en":"Evaporation is the surface process; boiling is the bulk process with bubbles.","cn":"蒸发是表面过程；沸腾是整体过程并产生气泡。"},{"en":"The water cycle pairs evaporation with condensation and precipitation.","cn":"水循环把蒸发与凝结、降水配成一组。"}],"abstract":[{"en":"Picture a shallow plate of water slowly turning into a white ring of salt.","cn":"想象一盘浅水慢慢变成一圈白色的盐痕。"},{"en":"Picture a bank balance shrinking without any withdrawal being recorded.","cn":"想象一笔存款没有任何取款记录却不断变少。"},{"en":"Picture a puddle that leaves only a dark outline on the pavement.","cn":"想象一洼水最后只在路面上留下一个深色轮廓。"}]},"examples":[{"en":"Evaporation from the lake leaves a crust of salt along the shore.","cn":"湖水的蒸发在岸边留下一层盐壳。"},{"en":"Mulch reduces evaporation and helps seedlings survive a dry spell.","cn":"覆盖物减少蒸发，帮助幼苗熬过干旱期。"},{"en":"The evaporation of the reserve fund was never explained to members.","cn":"储备金的逐渐消失从未向成员解释过。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「一娃泼水」——泼出去的水在太阳下慢慢变少 → 蒸发","word":"evaporation"},"root":"拉丁语 e-「向外」+ vaporare「冒汽」，源自 vapor「蒸汽、水汽」；经晚期拉丁语 evaporatio 与科学法语进入英语。vapor 的更深来源不确定。","sensesIntro":{"en":"Eight senses start from one physical event and fan out into measurement, technique and metaphor. The event is surface escape; measurement turns it into a number, technique turns it into a tool, and metaphor turns it into silent loss.","cn":"八个义项从一个物理事件出发，再分向测量、技术与比喻。事件本身是表面逸出；测量把它变成数字，技术把它变成工具，比喻把它变成无声的流失。"},"semanticMap":{"core":{"en":"CORE IMAGE: a thin layer of liquid losing itself into the air, leaving a mark behind.","cn":"核心意象：一层薄液不断进入空气，最后留下痕迹。"},"chain":["SURFACE MOLECULES ESCAPE","LIQUID THINS","MOISTURE LEAVES","WATER ENTERS THE AIR","AMOUNT IS MEASURED","ABSTRACT THING DISAPPEARS"],"branches":[{"senses":"01 · 02","en":"ESCAPE AND DRYING: the same event seen from the air side and from the material side.","cn":"逸出与变干：同一事件从空气一侧和材料一侧分别看。"},{"senses":"03 · 06","en":"CONCENTRATION: removing water is a tool, and physics names its mechanism.","cn":"浓缩：除去水分是一种工具，物理学为其机制命名。"},{"senses":"04 · 05","en":"MEASUREMENT: the water cycle turns the event into a flux and then into a number.","cn":"测量：水循环把事件变成通量，再变成数字。"},{"senses":"08","en":"COOLING: the escaping molecules carry heat, so evaporation becomes a service.","cn":"降温：逃出的分子带走热量，蒸发于是成为一种功能。"},{"senses":"07","en":"METAPHOR: an abstract quantity is treated as a liquid that thins away.","cn":"比喻：抽象之物被当作一种会变薄的液体。"}]},"affixes":{"intro":{"en":"Evaporation is built from Latin pieces that also build a compact English family, so the word can be read morpheme by morpheme.","cn":"evaporation 由拉丁成分构成，这些成分还构成一组紧凑的英语词族，因此可以按语素逐个读出。"},"latinIntro":{"en":"Latin vapor gives vapor, vaporous and evaporate; the prefix e- marks movement out, and -atio marks an action or its result.","cn":"拉丁 vapor 衍生 vapor、vaporous 与 evaporate；前缀 e- 标记「向外」，后缀 -atio 标记动作或其结果。"},"latinEntries":[{"word":"vapor","structure":"vapor, vaporis (m., third declension)","meaning":"steam, vapor, exhalation","meaningCN":"蒸汽；水汽；呼出的气"},{"word":"vaporare","structure":"vaporare, vaporavi, vaporatum (verb, first conjugation)","meaning":"to steam, to emit vapor","meaningCN":"冒汽；散发水汽"},{"word":"evaporare","structure":"evaporare, evaporavi, evaporatum (Late Latin verb)","meaning":"to steam away, to pass off as vapor","meaningCN":"蒸散；以水汽形式散出"},{"word":"evaporatio","structure":"evaporatio, evaporationis (f., third declension)","meaning":"a steaming away","meaningCN":"蒸散；蒸发"}],"items":[{"word":"e-","structure":"e- / ex- (Latin prefix, 'out of')","meaning":"out; away from","meaningCN":"向外；离开","example":"The prefix marks water leaving the liquid.","exampleCN":"这个前缀标记水离开液体。"},{"word":"vapor","structure":"vapor (Latin noun, 'steam')","meaning":"steam; vapor","meaningCN":"蒸汽；水汽","example":"The base names the thing that the liquid becomes.","exampleCN":"基础词命名液体变成的东西。"},{"word":"evaporation","structure":"e- + vapor + -ation (action or result)","meaning":"the action or result of steaming away","meaningCN":"蒸发的动作或结果","example":"Evaporation cools the remaining liquid.","exampleCN":"蒸发使剩余的液体降温。"},{"word":"evaporate","structure":"e- + vapor + -ate (verb ending)","meaning":"to turn into vapor","meaningCN":"蒸发；使蒸发","example":"The puddle will evaporate by noon.","exampleCN":"水洼到中午就会蒸发。"},{"word":"evaporative","structure":"evaporate + -ive (tending to)","meaning":"relating to or causing evaporation","meaningCN":"蒸发的；蒸发式的","example":"Evaporative cooling works in dry air.","exampleCN":"蒸发降温在干燥空气中有效。"},{"word":"evaporator","structure":"evaporate + -or (device or agent)","meaning":"a device that evaporates a liquid","meaningCN":"蒸发器","example":"The evaporator removes water from the juice.","exampleCN":"蒸发器除去果汁中的水。"},{"word":"evapotranspiration","structure":"evaporation + transpiration","meaning":"combined water loss from soil and plants","meaningCN":"蒸散","example":"Evapotranspiration is measured over whole catchments.","exampleCN":"蒸散在整个流域尺度上测量。"},{"word":"vaporous","structure":"vapor + -ous (full of)","meaning":"full of vapor; misty","meaningCN":"充满水汽的；雾状的","example":"A vaporous haze hung over the warm marsh.","exampleCN":"温暖沼泽上方悬着一层雾状水汽。"},{"word":"vaporize","structure":"vapor + -ize (to make)","meaning":"to convert into vapor","meaningCN":"汽化；使蒸发","example":"The laser can vaporize a thin metal film.","exampleCN":"激光能使薄金属膜汽化。"}]}},{"word":"evaporate","ipa_uk":"/ɪˈvæpəreɪt/","ipa_us":"/ɪˈvæpəreɪt/","definition_zh":"蒸发；使蒸发；消失；使浓缩","definition_en":"to change from a liquid into vapor, or to cause a liquid to do so; also to disappear gradually","core_image":"太阳照在湿石板上，水膜先变薄，随后整片湿痕无声地退去","scene":"太阳升高后，草叶上的露水一点点变少。 By mid-morning the dew has begun to evaporate from the warm grass.","sceneCN":"这里该词指「液体受热后变成水汽而减少」（第 1 个义项：液体汽化）；句意为到了半上午，露水已在温暖的草地上开始蒸发。","pos":[{"tag":"vi.","zh":"蒸发；挥发"},{"tag":"vt.","zh":"使蒸发；把水分蒸掉"},{"tag":"vi.","zh":"（液体）干涸；消失"},{"tag":"vi.","zh":"（比喻）逐渐消失；破灭"}],"collocations":[{"phrase":"evaporate rapidly","zh":"迅速蒸发"},{"phrase":"evaporate from the surface","zh":"从表面蒸发"},{"phrase":"evaporate the solvent","zh":"蒸去溶剂"},{"phrase":"evaporate into thin air","zh":"化为乌有"},{"phrase":"evaporate under the sun","zh":"在阳光下蒸发"},{"phrase":"evaporate all the water","zh":"把水全部蒸干"}],"forms":[{"label":"三单（第三人称单数）","form":"evaporates"},{"label":"过去式","form":"evaporated"},{"label":"过去分词","form":"evaporated"},{"label":"现在分词","form":"evaporating"},{"label":"名词（蒸发）","form":"evaporation"},{"label":"形容词（蒸发的）","form":"evaporative"},{"label":"名词（蒸发器）","form":"evaporator"}],"derivatives":[{"word":"evaporation","pos":"n.","zh":"蒸发；蒸发量"},{"word":"evaporative","pos":"adj.","zh":"蒸发的；蒸发式的"},{"word":"evaporator","pos":"n.","zh":"蒸发器"},{"word":"evaporated","pos":"adj.","zh":"蒸干的；制成炼乳的"},{"word":"vapor","pos":"n.","zh":"水汽；蒸汽"}],"senses":[{"no":"01","title":"Turn from liquid to vapor","titleCN":"液体变为水汽","definition":"to change from a liquid into vapor, usually at the surface and below boiling point","definitionCN":"液体在表面、低于沸点时变成水汽","example":"Rainwater evaporates from the roof soon after the shower passes.","exampleCN":"阵雨过后，屋面上的雨水很快就蒸发。","why":"The verb profiles the change of state itself, not the resulting loss or the tool used.","whyCN":"这个动词凸出状态变化本身，而不是由此造成的损失或所借助的工具。"},{"no":"02","title":"Dry up completely","titleCN":"液体干涸","definition":"of a liquid, to disappear entirely by evaporation","definitionCN":"（液体）因蒸发而完全消失","example":"The pool evaporates in summer, leaving cracked mud.","exampleCN":"这水塘在夏天干涸，留下龟裂的泥。","why":"When the last liquid is gone, the verb shifts from the process to its end point.","whyCN":"当最后的液体消失，词义就从过程转到终点。"},{"no":"03","title":"Remove moisture by heating","titleCN":"加热除去水分","definition":"to drive water or another solvent off by heating","definitionCN":"加热把水或溶剂蒸掉","example":"The laboratory evaporates the solution to recover the salt.","exampleCN":"实验室把溶液蒸干以回收盐。","why":"The transitive use makes evaporation an action performed on a material by someone.","whyCN":"及物用法把蒸发变成某人施加于材料的动作。"},{"no":"04","title":"Concentrate a solution","titleCN":"使溶液浓缩","definition":"to make a solution more concentrated by removing part of its solvent","definitionCN":"除去部分溶剂，使溶液变浓","example":"Slow heating evaporates the broth until it thickens.","exampleCN":"缓慢加热让汤汁蒸发，直到变稠。","why":"The purpose shifts from removing water to keeping what remains, which is the culinary and chemical use.","whyCN":"目的从「除去水」转到「留下其余成分」，这是烹饪与化学的用法。"},{"no":"05","title":"Vanish figuratively","titleCN":"比喻义：消失、破灭","definition":"to disappear gradually, especially money, hopes or support","definitionCN":"（钱、希望、支持）逐渐消失","example":"The grant evaporated after the second review.","exampleCN":"第二次评审之后，这笔资助就化为乌有。","why":"An abstract quantity is imagined as a volatile liquid that leaves no residue.","whyCN":"抽象之物被想象成一种挥发后不留残渣的液体。"},{"no":"06","title":"Fade in intensity","titleCN":"强度减弱","definition":"to become weaker or less intense, as if dissipating","definitionCN":"（情绪、紧张等）逐渐减弱","example":"The crowd's anger evaporated once the referee explained.","exampleCN":"裁判一解释，人群的怒气就消散了。","why":"Intensity is treated as a quantity that can be lost to the air, like heat or moisture.","whyCN":"强度被当作像热量或水分那样会散失到空气中的量。"},{"no":"07","title":"Be lost from soil or plants","titleCN":"从土壤或植物散失","definition":"of water, to be lost from soil, leaves or other surfaces into the atmosphere","definitionCN":"（水）从土壤、叶片等表面散失到大气","example":"Moisture evaporates quickly from bare, compacted soil.","exampleCN":"裸露板结的土壤里，水分蒸发得很快。","why":"This is the passive side of the water cycle: the water is not acting, it is simply leaving.","whyCN":"这是水循环的被动一面：水并没有主动做什么，只是离开了。"},{"no":"08","title":"Emit vapor (archaic)","titleCN":"（古）散发水汽","definition":"of a substance, to give off vapor or steam","definitionCN":"（物质）散发出水汽或蒸汽","example":"Early chemistry texts say that heated salts evaporate a sharp vapor.","exampleCN":"早期化学文献说，受热的盐会散出刺鼻的水汽。","why":"The old sense focuses on what comes out of the substance rather than on the substance changing state.","whyCN":"旧义关注从物质里出来的东西，而不是物质本身的状态变化。"}],"etymology":{"intro":{"en":"The Latin and French stages are well documented, while the deeper origin of vapor and the exact date of the figurative sense are less certain.","cn":"拉丁与法语阶段有较清楚的文献记录；vapor 的更深来源、以及比喻义的确切首见年代则不够确定。"},"items":[{"era":"LATIN","en":"Evaporare is built from e- 'out of' and vaporare 'to steam', itself from vapor 'steam, vapor'. The image is steam leaving a liquid.","cn":"evaporare 由 e-「向外」与 vaporare「冒汽」构成，后者又来自 vapor「蒸汽、水汽」。意象是蒸汽离开液体。"},{"era":"LATE LATIN","en":"The verb is attested in Late Latin technical writing. Its noun evaporatio supplies the action noun used in modern science.","cn":"该动词见于晚期拉丁语的技术文献。其名词 evaporatio 提供了现代科学使用的动作名词。"},{"era":"FRENCH (16th c.)","en":"Middle French évaporer passed the verb to English. The earliest English examples concern moisture leaving a body or a liquid.","cn":"中古法语 évaporer 把该动词传入英语。最早的英语例子讲的是湿气离开物体或液体。"},{"era":"ENGLISH (17th-18th c.)","en":"Chemistry gave the transitive use 'to drive off a solvent by heat', which remains the laboratory sense today.","cn":"化学带来了「加热驱除溶剂」的及物用法，这一直是今天的实验室义。"},{"era":"MODERN ENGLISH","en":"The figurative sense for hopes, funds or anger is relatively recent. It is generally treated as an extension of the physical image, but the exact first date is uncertain.","cn":"用于希望、资金或怒气的比喻义出现较晚。一般认为它是物理意象的延伸，但确切首见年代存疑。"}]},"similar":{"note":{"en":"The first group looks and sounds like evaporate but comes from other roots; the second group describes the same change, its result, or its reverse.","cn":"第一组在形音上像 evaporate，但词源不同；第二组描述同一变化、其结果或相反过程。"},"groups":[{"heading":"SOUND-ALIKE","entries":[{"word":"evacuate","ipa":"/ɪˈvækjueɪt/","tag":"near sound, different root","definition":"to move people out of a place. It comes from Latin vacuus 'empty', so the image is emptying a space, not vaporizing a liquid.","definitionCN":"疏散；撤离。来自拉丁语 vacuus「空的」，意象是把空间腾空，而不是液体汽化。"},{"word":"evaluate","ipa":"/ɪˈvæljueɪt/","tag":"near sound, different root","definition":"to judge value or quality, from Latin valere 'to be worth'. The similarity is only in the opening syllables.","definitionCN":"评估；评价。来自拉丁语 valere「有价值」，相似只在前几个音节。"},{"word":"evince","ipa":"/ɪˈvɪns/","tag":"near sound, different root","definition":"to show clearly, from Latin vincere 'to conquer'. It has nothing to do with vapor.","definitionCN":"表明；显示。来自拉丁语 vincere「征服」，与水汽无关。"}]},{"heading":"NEAR-MEANING","entries":[{"word":"vaporize","ipa":"/ˈveɪpəraɪz/","tag":"broader term","definition":"to turn into vapor by any means, including boiling; evaporate is the slower surface process.","definitionCN":"汽化。以任何方式变成水汽，包括沸腾；evaporate 指较慢的表面过程。"},{"word":"dry up","ipa":"/draɪ ʌp/","tag":"result phrase","definition":"to become completely dry, focusing on the end state rather than the mechanism.","definitionCN":"干涸；枯竭。强调最终状态，而不是机制。"},{"word":"disappear","ipa":"/ˌdɪsəˈpɪə(r)/","tag":"general verb","definition":"the neutral word for going out of sight; the figurative use of evaporate adds the image of volatile loss.","definitionCN":"消失。中性的「看不见了」；evaporate 的比喻义多出「挥发式损失」的意象。"},{"word":"fade","ipa":"/feɪd/","tag":"gradual weakening","definition":"to become weaker or less vivid, often of color, sound or feeling; it stresses diminishing intensity rather than loss of substance.","definitionCN":"褪去；减弱。多指颜色、声音或情绪变淡，强调强度下降而不是物质消失。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The prefix means 'out' and the base means 'steam', so the verb is 'steam out'.","cn":"前缀意为「向外」，基础词意为「蒸汽」，动词就是「向外冒汽」。"},{"en":"The family runs evaporation, evaporative, evaporator and evaporated milk.","cn":"同族词包括 evaporation、evaporative、evaporator 以及 evaporated milk（炼乳）。"},{"en":"Laboratory collocations: evaporate the solvent, evaporate to dryness.","cn":"实验室搭配：蒸去溶剂、蒸至干。"},{"en":"The transitive form takes an object; the intransitive form takes from or into.","cn":"及物形式带宾语；不及物形式常接 from 或 into。"},{"en":"The figurative sense usually pairs with money, hope, support or anger.","cn":"比喻义常与金钱、希望、支持或怒气搭配。"}],"abstract":[{"en":"Picture a wet footprint on hot stone shrinking until only a pale shape is left.","cn":"想象炎热石板上一个湿脚印不断缩小，最后只剩浅色轮廓。"},{"en":"Picture a pot of soup simmering down while the kitchen window fogs up.","cn":"想象一锅汤慢慢收浓，厨房窗户同时蒙上水汽。"},{"en":"Picture a promise written in chalk and erased by rain.","cn":"想象一句用粉笔写下的承诺，被雨冲掉。"}]},"examples":[{"en":"The sun evaporates the last pools along the riverbed.","cn":"太阳把河床上最后几处水洼蒸干。"},{"en":"Heat evaporates the solvent, leaving a thin film of crystals.","cn":"加热蒸去溶剂，留下一层薄薄的晶体。"},{"en":"Public confidence evaporated after the third delay.","cn":"第三次拖延之后，公众信心消散了。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「一娃泼水，越泼越少」——水在太阳下变少、消失 → 蒸发","word":"evaporate"},"root":"拉丁语 e-「向外」+ vaporare「冒汽」，源自 vapor「蒸汽、水汽」；经法语 évaporer 进入英语。vapor 更深来源不确定，比喻义首见年代存疑。","sensesIntro":{"en":"Eight senses follow the same change of state but vary the viewpoint: the process, its end point, the person doing it, the purpose, the abstract extension, the loss of intensity, the passive water cycle and the old emission reading.","cn":"八个义项沿同一次状态变化展开，只是视角不同：过程本身、终点、施动者、目的、抽象延伸、强度衰减、水循环中的被动失去，以及古老的「散发」读法。"},"semanticMap":{"core":{"en":"CORE IMAGE: a film of moisture thinning under the sun until it is gone.","cn":"核心意象：一层湿气在阳光下不断变薄，直到消失。"},"chain":["LIQUID PRESENT","SURFACE MOLECULES LEAVE","LIQUID THINS","LAST DROP GONE","SOLVENT REMOVED","ABSTRACT THING FADES"],"branches":[{"senses":"01 · 02","en":"PROCESS AND END: the change itself and the moment when no liquid remains.","cn":"过程与终点：变化本身，以及液体不剩的时刻。"},{"senses":"03 · 04","en":"TRANSITIVE PURPOSE: heating removes a solvent either to clean a material or to concentrate it.","cn":"及物目的：加热除去溶剂，或为净化材料，或为浓缩。"},{"senses":"05 · 06","en":"METAPHOR: money and anger behave like volatile liquids, one vanishing, one cooling.","cn":"比喻：金钱与怒气都像挥发性液体，一个消失，一个降温。"},{"senses":"07","en":"PASSIVE WATER CYCLE: water leaves soil and leaves without an agent.","cn":"被动水循环：水从土壤和叶片离开，没有施动者。"},{"senses":"08","en":"OLD EMISSION: the substance is seen as giving off vapor rather than changing into it.","cn":"古老散发义：物质被看作放出水汽，而不是变成水汽。"}]},"affixes":{"intro":{"en":"Evaporate is the verb in a Latin-derived family whose members divide the work of naming the process, the device and the result.","cn":"evaporate 是一个拉丁来源词族里的动词，族内成员分担命名过程、装置与结果。"},"latinIntro":{"en":"Latin vapor and vaporare supply the base; e- marks movement out, and -ate marks the verb, while -ation and -or name the action and the device.","cn":"拉丁 vapor 与 vaporare 提供基础；e- 标记向外，-ate 标记动词，而 -ation 与 -or 分别命名动作与装置。"},"latinEntries":[{"word":"vapor","structure":"vapor, vaporis (m., third declension)","meaning":"steam, vapor","meaningCN":"蒸汽；水汽"},{"word":"vaporare","structure":"vaporare, vaporavi, vaporatum (verb, first conjugation)","meaning":"to steam, to emit vapor","meaningCN":"冒汽；散发水汽"},{"word":"evaporare","structure":"evaporare, evaporavi, evaporatum (Late Latin verb)","meaning":"to steam away","meaningCN":"蒸散；蒸发"},{"word":"evaporatio","structure":"evaporatio, evaporationis (f., third declension)","meaning":"a steaming away","meaningCN":"蒸发"}],"items":[{"word":"e-","structure":"e- / ex- (Latin prefix, 'out of')","meaning":"out; away","meaningCN":"向外；离开","example":"The prefix sends the vapor outward.","exampleCN":"这个前缀把水汽送向外。"},{"word":"vapor","structure":"vapor (Latin noun, 'steam')","meaning":"steam; vapor","meaningCN":"蒸汽；水汽","example":"The base names what the liquid becomes.","exampleCN":"基础词命名液体变成之物。"},{"word":"evaporate","structure":"e- + vapor + -ate (verb ending)","meaning":"to change into vapor","meaningCN":"蒸发；使蒸发","example":"The dew evaporates by mid-morning.","exampleCN":"露水到半上午就蒸发。"},{"word":"evaporation","structure":"evaporate + -ation (action or result)","meaning":"the process or amount of evaporating","meaningCN":"蒸发；蒸发量","example":"Evaporation removes water from the brine.","exampleCN":"蒸发从盐卤中除去水。"},{"word":"evaporative","structure":"evaporate + -ive (tending to)","meaning":"causing or relating to evaporation","meaningCN":"蒸发的；蒸发式的","example":"Evaporative cooling is effective in dry heat.","exampleCN":"干热环境下蒸发降温有效。"},{"word":"evaporator","structure":"evaporate + -or (device)","meaning":"a device that evaporates liquid","meaningCN":"蒸发器","example":"The evaporator coil chills the air.","exampleCN":"蒸发器盘管使空气变冷。"},{"word":"evaporated","structure":"evaporate + -ed (past participle)","meaning":"having been evaporated; thickened by evaporation","meaningCN":"已蒸发的；蒸浓的","example":"Evaporated milk keeps longer than fresh milk.","exampleCN":"炼乳比鲜奶保存更久。"},{"word":"vaporous","structure":"vapor + -ous (full of)","meaning":"full of vapor","meaningCN":"充满水汽的","example":"A vaporous mist covered the fields.","exampleCN":"一层雾状水汽覆盖田野。"},{"word":"vaporize","structure":"vapor + -ize (to make)","meaning":"to turn into vapor","meaningCN":"汽化；使蒸发","example":"The heat vaporizes the fuel before ignition.","exampleCN":"热量在点火前使燃料汽化。"}]}},{"word":"root","ipa_uk":"/ruːt/","ipa_us":"/ruːt/","definition_zh":"根；根源；词根；数根；扎根","definition_en":"the underground part of a plant; the base or origin of something; a linguistic or mathematical root","core_image":"一棵大树被风掀倒，地面下那张比树冠更宽的根网露了出来","scene":"这棵老树被风吹倒后，人们才发现它的根在地表下铺得比树冠还宽。 After the old tree blew down, people saw that its root mass spread wider underground than its crown.","sceneCN":"这里该词指「植物扎在土里的根」（第 1 个义项：植物的地下器官）；句意为老树被风吹倒后，人们才看到它的根在土里铺得比树冠还宽。","pos":[{"tag":"n.","zh":"根；根系"},{"tag":"n.","zh":"根部；底端（头发、牙齿、指甲等）"},{"tag":"n.","zh":"根源；起因"},{"tag":"n.","zh":"（语言学）词根"},{"tag":"n.","zh":"（数学）根；方根"},{"tag":"n.","zh":"（复数）祖籍；家族来源"},{"tag":"n.","zh":"（计算机）根目录；超级用户"},{"tag":"n.","zh":"（音乐）和弦的根音"},{"tag":"v.","zh":"生根；扎根；固定"},{"tag":"v.","zh":"（短语动词）支持；为……加油"}],"collocations":[{"phrase":"take root","zh":"生根；扎根"},{"phrase":"the root of the problem","zh":"问题的根源"},{"phrase":"root cause","zh":"根本原因"},{"phrase":"root hair","zh":"根毛"},{"phrase":"square root","zh":"平方根"},{"phrase":"root directory","zh":"根目录"},{"phrase":"root for the team","zh":"为球队加油"}],"forms":[{"label":"复数（根；根源）","form":"roots"},{"label":"三单（生根；支持）","form":"roots"},{"label":"过去式","form":"rooted"},{"label":"过去分词","form":"rooted"},{"label":"现在分词","form":"rooting"},{"label":"形容词（有根的；根深蒂固的）","form":"rooted"},{"label":"名词（生根；扎根）","form":"rooting"}],"derivatives":[{"word":"rooted","pos":"adj.","zh":"有根的；根深蒂固的"},{"word":"rootless","pos":"adj.","zh":"无根的；没有归属的"},{"word":"rooting","pos":"n.","zh":"生根；扎根"},{"word":"rootlet","pos":"n.","zh":"小根；细根"},{"word":"rootstock","pos":"n.","zh":"根砧；根茎"},{"word":"uproot","pos":"v.","zh":"连根拔起；使离开家园"}],"senses":[{"no":"01","title":"Underground plant organ","titleCN":"植物的地下根","definition":"the part of a plant that usually grows underground and absorbs water and nutrients","definitionCN":"植物通常在地下生长、吸收水分和养分的器官","example":"The desert shrub sends a long taproot deep into the sand.","exampleCN":"这种沙漠灌木把一条长主根深深扎进沙里。","why":"This is the concrete body sense: a downward organ that holds the plant and feeds it.","whyCN":"这是具体的实体义：向下生长的器官，既固定植株，也供给养分。"},{"no":"02","title":"Embedded base of a part","titleCN":"物件深嵌的根部","definition":"the part of a hair, tooth, nail or similar structure that is fixed in the body","definitionCN":"头发、牙齿、指甲等结构固定在身体里的那一端","example":"The dentist cleaned below the root of the damaged tooth.","exampleCN":"牙医清理了那颗坏牙牙根的下面。","why":"The plant image is mapped onto any part that anchors itself in a larger body.","whyCN":"植物意象被映射到任何固定在更大本体里的部件。"},{"no":"03","title":"Origin or cause","titleCN":"根源；起因","definition":"the basic cause or origin of a problem, feeling or situation","definitionCN":"问题、情绪或状况的根本原因或起点","example":"Economists trace the crisis to its root in the housing market.","exampleCN":"经济学家把这场危机追溯到住房市场这一根源。","why":"A cause is pictured as something buried below the visible surface, from which the visible effect grows.","whyCN":"原因被想象成埋在可见表面之下、可见结果由它长出来的东西。"},{"no":"04","title":"Linguistic root","titleCN":"语言学词根","definition":"the smallest meaningful base of a word from which related words are formed","definitionCN":"词的最小意义基础，相关词由它构成","example":"The Latin root of this word also appears in three other languages.","exampleCN":"这个词的拉丁词根还出现在另外三种语言里。","why":"Historical linguistics borrowed the plant metaphor: words branch out from a common base.","whyCN":"历史语言学借用植物比喻：词从共同基础分叉长出。"},{"no":"05","title":"Mathematical root","titleCN":"数学的根","definition":"a number that, when multiplied by itself a given number of times, produces a stated number; also a solution of an equation","definitionCN":"自乘若干次后得到某数的数；也指方程的解","example":"The square root of ninety-one lies between nine and ten.","exampleCN":"九十一的平方根在九与十之间。","why":"This sense comes through Latin radix 'root', used for the base number from which a power grows.","whyCN":"这一义经拉丁语中表示「根」的词而来，用来指幂所由生长的基数。"},{"no":"06","title":"Family or place of origin","titleCN":"祖籍；家族来源","definition":"the place, family or culture a person comes from, usually in the plural","definitionCN":"一个人来自的地方、家族或文化，通常用复数","example":"She returned to her roots in a fishing village on the coast.","exampleCN":"她回到海边渔村的祖籍之地。","why":"The plant image becomes social: a person is anchored in a place as a plant is anchored in soil.","whyCN":"植物意象转向社会：人像植物扎在土里那样，被固定在一个地方。"},{"no":"07","title":"Computing root","titleCN":"计算机的根目录或超级用户","definition":"the top-level directory of a file system, or the account with full administrative power","definitionCN":"文件系统的最上层目录，或拥有全部管理权限的账户","example":"Only the root account can change that setting.","exampleCN":"只有超级用户账户能改动那个设置。","why":"The directory tree is drawn as a root with branches below, so the top node inherited the plant name.","whyCN":"目录树被画成一棵根在上、枝在下的树，最上层节点于是继承了植物的名字。"},{"no":"08","title":"Root of a chord","titleCN":"和弦的根音","definition":"the note on which a chord is built and from which its name is taken","definitionCN":"和弦赖以构成、并据以命名的那个音","example":"The chord changes when its root moves to another note.","exampleCN":"当根音移到另一个音，整个和弦就随之改变。","why":"A chord is heard as a structure growing from one base note, so the base is called its root.","whyCN":"和弦被听成从一个基础音长出的结构，因此基础音被称作根音。"},{"no":"09","title":"Establish roots","titleCN":"生根；扎根","definition":"to grow roots, or to become firmly established in a place","definitionCN":"长出根；在某地牢固立足","example":"The cuttings root quickly in damp sand.","exampleCN":"插条在湿沙里很快生根。","why":"The verb turns the noun into an event: the plant or person acquires a root and holds fast.","whyCN":"动词把名词变成事件：植物或人获得根并牢牢固定。"}],"etymology":{"intro":{"en":"The Germanic origin is secure at the level of Old English and Old Norse, but the Indo-European reconstruction and the exact route of the mathematical sense are less certain.","cn":"日耳曼语来源在古英语与古诺斯语层面较可靠；印欧语重构形式、以及数学义的确切引入路径仍不够确定。"},"items":[{"era":"OLD ENGLISH AND OLD NORSE","en":"Old English had rōt, and the form was reinforced by Old Norse rót 'root'. Both point to a Germanic noun for the underground part of a plant.","cn":"古英语有 rōt，该形式又受古诺斯语 rót「根」强化。两者都指向日耳曼语中表示植物地下部分的名称。"},{"era":"PROTO-GERMANIC","en":"The reconstructed ancestor is *wrōts or *wrot-, with cognates in Dutch wortel and German Wurzel. The initial w- was lost in English.","cn":"重构的祖词是 *wrōts 或 *wrot-，同族词见于荷兰语 wortel 与德语 Wurzel。英语中开头的 w- 脱落。"},{"era":"PROTO-INDO-EUROPEAN","en":"The usual reconstruction is *wrād- 'branch, root'. Latin radix and Greek rhiza are cognates, not sources of the English word; the exact ablaut pattern is debated.","cn":"通行重构是 *wrād-「枝、根」。拉丁语 radix 与希腊语 rhiza 是同源词，并非英语词的来源；元音交替的具体形式仍有争论。"},{"era":"MIDDLE AND EARLY MODERN ENGLISH","en":"From the physical plant sense, the word extended to any base or origin, and to the base of a word in grammar. The plural roots for ancestry appears in the nineteenth century.","cn":"从植物的实体义出发，该词扩展到任何基部或起源，也指语法中词的基础。表示祖籍的复数 roots 出现于十九世纪。"},{"era":"MATHEMATICS (16th-17th c.)","en":"Mathematical writers used Latin radix for the base number, and English root was used to translate it. The sense is therefore a calque rather than a direct semantic growth.","cn":"数学作者用拉丁语 radix 指基数，英语 root 被用来翻译它。因此这一义是仿译，而不是词义的自然生长。"},{"era":"COMPUTING (20th c.)","en":"Root directory and root user are twentieth-century computing terms, modelled on the image of a tree whose topmost point is its root.","cn":"根目录与超级用户是二十世纪的计算机术语，借用了「树的最上端是根」这一意象。"}]},"similar":{"note":{"en":"The first group sounds like root but has a different history; the second group shares part of the meaning but not the whole range.","cn":"第一组读音像 root，但来历不同；第二组只共享部分意思，并不覆盖全部义域。"},"groups":[{"heading":"SOUND-ALIKE","entries":[{"word":"route","ipa":"/ruːt/","tag":"same sound, different origin","definition":"a way from one place to another, from French route and Latin rupta via a broken road. It is not related to the plant word.","definitionCN":"路线；途径。经法语 route 与拉丁语 rupta（被开辟的路）而来，与植物词无关。"},{"word":"rout","ipa":"/raʊt/","tag":"near spelling, different vowel","definition":"a disorderly retreat or a decisive defeat; the vowel is long and diphthongal, unlike the short vowel of root.","definitionCN":"溃败；溃退。元音是双元音，与 root 的短元音不同。"},{"word":"rut","ipa":"/rʌt/","tag":"near spelling, different vowel","definition":"a groove worn in the ground by wheels; the vowel is short and central, not the long vowel of root.","definitionCN":"车辙；凹槽。元音是短促的央元音，不是 root 的长元音。"}]},{"heading":"NEAR-MEANING","entries":[{"word":"base","ipa":"/beɪs/","tag":"general base word","definition":"the bottom or supporting part of anything; it lacks the botanical and genealogical imagery of root.","definitionCN":"底部；基础。缺少 root 的植物与家族意象。"},{"word":"origin","ipa":"/ˈɒrɪdʒɪn/","tag":"cause or starting point","definition":"the point where something begins; it is neutral about depth or attachment, whereas root suggests something buried and holding fast.","definitionCN":"起源；起点。不强调深度与附着，而 root 暗示埋在下层并牢牢固定。"},{"word":"source","ipa":"/sɔːs/","tag":"supply or starting point","definition":"the place something comes from, often a supply; it does not carry the image of an underground organ.","definitionCN":"来源；源头。常指供给之处，不带地下器官的意象。"},{"word":"stem","ipa":"/stem/","tag":"plant part, different organ","definition":"the main stalk above ground; it is the upward counterpart of root, not a synonym.","definitionCN":"茎；主干。地上部分的主要轴，是 root 向上的对应器官，并非同义词。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The Germanic word was reinforced by Old Norse, and the initial w- of the older form was lost.","cn":"这个日耳曼词受到古诺斯语强化，更早形式开头的 w- 后来脱落。"},{"en":"The family runs rooted, rootless, rootlet, rootstock and uproot.","cn":"同族词包括 rooted、rootless、rootlet、rootstock 与 uproot。"},{"en":"Fixed phrases: take root, root cause, square root, root directory.","cn":"固定搭配：扎根、根本原因、平方根、根目录。"},{"en":"Latin radix is a cognate, and it supplies the mathematical and linguistic terminology.","cn":"拉丁语 radix 是同源词，并提供了数学与语言学的术语。"},{"en":"The plural roots usually means ancestry or a home region.","cn":"复数 roots 通常指祖籍或故乡。"}],"abstract":[{"en":"Picture a tree turned upside down, its crown mirrored by a wider root mass below.","cn":"想象一棵倒过来的树，树冠在下方由更宽的根网镜像对应。"},{"en":"Picture a word family drawn as a trunk with branches, the oldest form at the base.","cn":"想象一个词族画成主干与分枝，最古老的形式在底部。"},{"en":"Picture a person standing on a small patch of soil carried from a distant village.","cn":"想象一个人站在一小块从远方村庄带来的土上。"}]},"examples":[{"en":"The flood exposed the roots of the old hedge along the bank.","cn":"洪水冲出了河岸边老树篱的根。"},{"en":"Researchers still argue about the root of the sudden decline.","cn":"研究者仍在争论这次骤降的根源。"},{"en":"The square root of the area gives the length of one side.","cn":"面积的平方根给出边长的长度。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「入土」——植物钻进土里的部分 → 根；事情的「入土之处」→ 根源","word":"root"},"root":"古英语 rōt 加古诺斯语 rót，重构的日耳曼祖词为 *wrōts；更早的印欧重构 *wrād-「枝、根」与拉丁 radix、希腊 rhiza 同源。数学义经拉丁 radix 仿译而来，计算机义为二十世纪新用。","sensesIntro":{"en":"Ten senses spread from one concrete organ to every kind of base. The plant root anchors and feeds; the same shape then appears in teeth, causes, words, numbers, families, file systems, chords and finally in the act of taking hold.","cn":"十个义项从一个具体器官扩散到各种「基部」。植物的根固定并供给；同一形状随后出现在牙齿、原因、词语、数字、家族、文件系统、和弦，最后出现在「扎下根」这个动作里。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hidden net under the ground, wider than the visible crown and holding it up.","cn":"核心意象：地面下有一张看不见的网，比可见的树冠更宽，把树冠托住。"},"chain":["UNDERGROUND ORGAN","HIDDEN BASE","CAUSE BELOW","WORD BASE","NUMBER BASE","TAKE HOLD"],"branches":[{"senses":"01 · 02","en":"BODY BASE: plant root and embedded part both fix something in a larger body.","cn":"实体基部：植物根与深嵌的部件都把某物固定在更大的本体里。"},{"senses":"03 · 06","en":"HIDDEN ORIGIN: a cause and a homeland are both pictured as buried ground.","cn":"隐藏的起点：原因与故乡都被想象成埋在地下的土。"},{"senses":"04 · 05","en":"ABSTRACT BASE: word and number both take a base from which forms grow.","cn":"抽象基础：词与数都取一个基部，形式由它长出。"},{"senses":"07 · 08","en":"TOP AS BASE: computing and music invert the tree, but keep a single starting point.","cn":"顶端作基：计算机与音乐把树倒过来，却仍保留唯一起点。"},{"senses":"09","en":"TAKE HOLD: the verb turns the whole image into the act of becoming fixed.","cn":"扎住：动词把整个意象变成「变得固定」的动作。"}]},"affixes":{"intro":{"en":"Root is a short Germanic word whose family is built by suffixes and prefixes rather than by Latin derivation, so the affix section reads English and Germanic layers together.","cn":"root 是一个简短日耳曼词，其词族靠前后缀而非拉丁派生构成，因此词缀部分把英语与日耳曼层次放在一起读。"},"latinIntro":{"en":"There is no Latin source for English root. Latin radix is a cognate, and it supplies the mathematical term; the entries below are therefore marked as cognate or as later learned borrowings.","cn":"英语 root 没有拉丁来源。拉丁语 radix 是同源词，并提供了数学术语；因此下列条目标注为同源词或后世学术借词。"},"latinEntries":[{"word":"radix","structure":"radix, radicis (f., third declension)","meaning":"root; base number","meaningCN":"根；基数（这一拉丁词与英语词同族，并非其直接来源）"},{"word":"rhiza","structure":"rhiza (Greek noun, 'root')","meaning":"root","meaningCN":"根（希腊语同源词）"},{"word":"radicari","structure":"radicari, radicatus sum (Latin deponent verb)","meaning":"to take root","meaningCN":"生根；扎根"}],"items":[{"word":"root","structure":"root (Old English rōt, reinforced by Old Norse rót)","meaning":"the underground organ; a base","meaningCN":"根；基部","example":"The root anchors the tree in the soil.","exampleCN":"根把树固定在土壤里。"},{"word":"rooted","structure":"root + -ed (having)","meaning":"having roots; firmly established","meaningCN":"有根的；根深蒂固的","example":"The practice is rooted in local custom.","exampleCN":"这一做法根植于当地习俗。"},{"word":"rootless","structure":"root + -less (without)","meaning":"without roots or a sense of belonging","meaningCN":"无根的；没有归属的","example":"The displaced family felt rootless in the city.","exampleCN":"这个流离失所的家庭在城市里感到没有归属。"},{"word":"rootlet","structure":"root + -let (small)","meaning":"a small root","meaningCN":"小根；细根","example":"Rootlets absorb water from the finest soil pores.","exampleCN":"细根从最细的土壤孔隙中吸水。"},{"word":"rootstock","structure":"root + stock (base stem)","meaning":"the root and lower stem of a plant, often used in grafting","meaningCN":"根砧；根茎","example":"The apple variety is grafted onto a hardy rootstock.","exampleCN":"这个苹果品种嫁接在耐寒的根砧上。"},{"word":"uproot","structure":"un- + root (verb)","meaning":"to pull up by the roots; to displace","meaningCN":"连根拔起；使离开家园","example":"The storm uprooted dozens of trees.","exampleCN":"风暴把几十棵树连根拔起。"},{"word":"radical","structure":"radix + -al (relating to)","meaning":"relating to a root; extreme","meaningCN":"根的；激进的","example":"The reform was called radical because it went to the root.","exampleCN":"这项改革被称为激进，因为它触及根源。"},{"word":"eradicate","structure":"e- + radix + -ate","meaning":"to tear out by the roots","meaningCN":"根除","example":"The campaign aims to eradicate the invasive weed.","exampleCN":"这场行动旨在根除这种入侵杂草。"},{"word":"radish","structure":"radix via Latin and French","meaning":"a root vegetable","meaningCN":"萝卜（一种根菜）","example":"Radish is grown for its edible root.","exampleCN":"萝卜是为可食用的根而种植的。"}]}},{"word":"root system","ipa_uk":"/ˈruːt ˌsɪstəm/","ipa_us":"/ˈruːt ˌsɪstəm/","definition_zh":"根系；根系统；根的网络结构","definition_en":"the entire network of roots belonging to a plant, including its main roots and all lateral branches","core_image":"草皮被切开后，草茎下方露出一张向四周均匀铺开的细密根网","scene":"研究人员挖开表土后发现，草地下方的根系像一张细密的网，向四周均匀铺开。 After the researchers removed the topsoil, they found a fine, even mesh of roots beneath the grass: a classic fibrous root system.","sceneCN":"这里该词指「须根系」（第 3 个义项：由大量细根构成的根系类型）；句意为研究者挖开表土后，发现草地下方是一张细密均匀的根网，即典型的须根系。","pos":[{"tag":"n.","zh":"根系；一株植物的全部根"},{"tag":"n.","zh":"（植物学）直根系"},{"tag":"n.","zh":"（植物学）须根系"},{"tag":"n.","zh":"（数学）根系统（李代数分类用的根向量集合）"}],"collocations":[{"phrase":"deep root system","zh":"深根系"},{"phrase":"shallow root system","zh":"浅根系"},{"phrase":"fibrous root system","zh":"须根系"},{"phrase":"taproot system","zh":"直根系"},{"phrase":"root system architecture","zh":"根系构型"},{"phrase":"extensive root system","zh":"发达的根系"}],"forms":[{"label":"复数（多株植物的根系）","form":"root systems"},{"label":"相关名词（主根）","form":"taproot"},{"label":"相关类型（须根系）","form":"fibrous root system"},{"label":"相关名词（侧根）","form":"lateral root"},{"label":"相关名词（根构型）","form":"root architecture"}],"derivatives":[{"word":"root","pos":"n./v.","zh":"根；根源；生根"},{"word":"system","pos":"n.","zh":"系统；体系"},{"word":"taproot","pos":"n.","zh":"主根；直根"},{"word":"rootlet","pos":"n.","zh":"细根；小根"},{"word":"rootstock","pos":"n.","zh":"根砧；根茎"}],"senses":[{"no":"01","title":"Whole root network","titleCN":"一株植物的全部根","definition":"all the roots of a plant considered together as one network","definitionCN":"把一株植物的所有根当作一个网络来看","example":"A mature oak may have a root system wider than its crown.","exampleCN":"一棵成年橡树的根系可能比它的树冠还宽。","why":"The compound names the whole rather than any single root: the object is the network, not the organ.","whyCN":"这个复合词命名的是整体而非单条根：对象是网，而不是某个器官。"},{"no":"02","title":"Taproot system","titleCN":"直根系","definition":"a root system dominated by one main root that grows straight down, with smaller lateral roots branching from it","definitionCN":"由一条向下直长的主根主导、侧根从其上分出的根系","example":"Carrots and dandelions develop a taproot system with one dominant root.","exampleCN":"胡萝卜和蒲公英形成一条主根占主导的直根系。","why":"The type is defined by the dominance of the first root, which stays central while later roots stay subordinate.","whyCN":"这一类型由第一条根的主导地位定义：主根居中，后来的根处于从属位置。"},{"no":"03","title":"Fibrous root system","titleCN":"须根系","definition":"a root system made of many roots of similar size, with no single dominant root","definitionCN":"由许多粗细相近的根构成、没有单条主导根的根系","example":"Grasses spread a dense fibrous root system that binds the soil.","exampleCN":"禾草铺开密集的须根系，把土壤固定住。","why":"Here the network is flat and even: no root wins, and the mass of fine roots does the work.","whyCN":"这里网络扁平而均匀：没有哪条根占优，靠大量细根发挥作用。"},{"no":"04","title":"Lateral root spread","titleCN":"侧根形成的横向网络","definition":"the outward spread of lateral roots that gives a root system its width","definitionCN":"侧根向外伸展，使根系获得宽度","example":"Lateral roots extend outward and give the root system its spread.","exampleCN":"侧根向外伸展，使根系铺展开来。","why":"Width comes from branching, so the same system can be read as a branching structure rather than a list of organs.","whyCN":"宽度来自分枝，因此同一系统也可以读成一个分枝结构，而不是一串器官。"},{"no":"05","title":"Anchorage function","titleCN":"固着功能","definition":"the function by which a root system holds a plant upright and resists being pulled out","definitionCN":"根系把植物固定直立、抵抗拔出的功能","example":"The root system holds the tree upright during storms.","exampleCN":"根系在风暴中把树固定住，使其保持直立。","why":"This sense names what the network does rather than what it is: the system is treated as an anchoring device.","whyCN":"这一义命名网络的作用而非其构造：系统被当作一种锚固装置。"},{"no":"06","title":"Absorption and transport","titleCN":"吸收与运输","definition":"the function by which a root system takes up water and dissolved nutrients and passes them to the shoot","definitionCN":"根系吸收水分与溶解养分并向上输送的功能","example":"A shallow root system limits how much water the plant can reach.","exampleCN":"浅根系限制了植株能够获取的水量。","why":"The network is now a plumbing and intake surface, which is why depth and fineness matter.","whyCN":"这时网络是取水与输水的表面，因此深度与细度都很重要。"},{"no":"07","title":"Root system in mathematics","titleCN":"数学中的根系统","definition":"a finite set of vectors in Euclidean space, closed under reflection, used to classify semisimple Lie algebras","definitionCN":"欧氏空间中在反射下封闭的有限向量集合，用于分类半单李代数","example":"The classification of Lie algebras depends on the root system attached to each one.","exampleCN":"李代数的分类取决于附属于每一个李代数的根系统。","why":"This is a separate technical coinage: the vectors are called roots because they generate the structure, not because they resemble plant roots.","whyCN":"这是独立的技术造词：这些向量被称为根，是因为它们生成整个结构，而不是因为像植物根。"},{"no":"08","title":"Foundational network (figurative)","titleCN":"比喻义：基础网络","definition":"the underlying network of groups or institutions that supports a larger movement","definitionCN":"支撑一个更大运动的基层组织或机构网络","example":"The reform movement grew out of a root system of local clubs and unions.","exampleCN":"这场改革运动从地方俱乐部与工会构成的基层网络中生长出来。","why":"The plant image is applied to society: many small units feed one visible structure above ground.","whyCN":"植物意象被用于社会：许多小单元向上供养一个可见结构。"}],"etymology":{"intro":{"en":"The compound is transparent: a Germanic root word plus a Greek-derived system word. The botanical types are nineteenth-century, and the mathematical term has a separate history.","cn":"复合词的构成清楚：前一词为日耳曼来源，后一词经拉丁语上溯希腊语。植物学两类型术语定型于十九世纪；数学义另有独立来源。"},"items":[{"era":"OLD ENGLISH AND OLD NORSE","en":"The first element is Old English rōt, reinforced by Old Norse rót, from Proto-Germanic *wrōts. It names the underground organ of a plant.","cn":"第一个成分是古英语 rōt，受古诺斯语 rót 强化，来自原始日耳曼语 *wrōts，指植物的地下器官。"},{"era":"LATIN AND GREEK","en":"The second element goes back to Greek systema 'an organized whole', through Late Latin systema. It contributes the idea of parts arranged as one working body.","cn":"第二个成分经晚期拉丁语 systema 上溯希腊语 systema「有组织的整体」，带来「各部分排成一个运作整体」的意思。"},{"era":"ENGLISH (18th-19th c.)","en":"The compound root system is recorded in botanical writing, where it named all the roots of one plant taken together.","cn":"复合词 root system 见于植物学写作，用来指一株植物全部根的总和。"},{"era":"BOTANY (19th c.)","en":"The taproot and fibrous types were distinguished as the two basic architectures of flowering plants, and the terms entered textbooks.","cn":"直根型与须根型被区分为被子植物的两种基本构型，相关术语进入教科书。"},{"era":"MATHEMATICS (19th-20th c.)","en":"The mathematical root system arose independently in the theory of Lie algebras. Its 'roots' are generating vectors, not plant organs.","cn":"数学上的根系统在李代数理论中独立产生。其中的「根」是生成向量，不是植物器官。"},{"era":"MODERN ENGLISH","en":"The figurative use for organizational networks is a twentieth-century extension, common in writing about social movements.","cn":"用于组织网络的比喻义是二十世纪延伸，常见于社会运动写作。"}]},"similar":{"note":{"en":"Two groups follow: the first is close in sound or form and easy to mix up; the second shares part of the meaning but is not interchangeable.","cn":"分两组：第一组在读音或形式上接近、容易混淆；第二组只共享部分意思，不能互换。"},"groups":[{"heading":"SOUND-ALIKE / FORM-ALIKE","entries":[{"word":"root hair","ipa":"/ruːt heə(r)/","tag":"different structure","definition":"a single tiny tubular outgrowth of a root, not the whole network; it is one thread, not a system.","definitionCN":"根毛。根表面单条微小的管状突起，不是整个网络；它是一根丝，不是一个系统。"},{"word":"shoot system","ipa":"/ʃuːt ˈsɪstəm/","tag":"opposite organ system","definition":"the stem, leaves and flowers above ground; it is the upward counterpart of the root system.","definitionCN":"茎叶系统。地上的茎、叶与花，是根系向上的对应系统。"},{"word":"rootstock","ipa":"/ˈruːtstɒk/","tag":"single organ","definition":"the root and lower stem of a plant, often used for grafting; it is one part, not the full network.","definitionCN":"根砧；根茎。植物的根与下部茎，常用于嫁接；是单个部位，不是完整网络。"}]},{"heading":"NEAR-MEANING","entries":[{"word":"root network","ipa":"/ruːt ˈnetwɜːk/","tag":"descriptive phrase","definition":"a plain descriptive phrase for connected roots; it stresses connection but does not name a botanical type.","definitionCN":"根网络。平实的描述性短语，强调连接，但不命名植物学类型。"},{"word":"root architecture","ipa":"/ruːt ˈɑːkɪtektʃə(r)/","tag":"structural term","definition":"the spatial arrangement of a root system, including depth, spread and branching; it describes the shape rather than the whole.","definitionCN":"根系构型。根系的空间排列，包括深度、展幅与分枝；描述形状而非整体。"},{"word":"taproot","ipa":"/ˈtæpruːt/","tag":"single organ","definition":"the one dominant root of a taproot system; the system contains it, but it is not the system.","definitionCN":"主根；直根。直根系中那条占主导的根；系统包含它，但它不等于系统。"},{"word":"fibrous roots","ipa":"/ˈfaɪbrəs ruːts/","tag":"root type","definition":"the many fine roots of a fibrous system; the phrase names the roots, while root system names their arrangement.","definitionCN":"须根。须根系中大量细根；该短语命名根本身，而 root system 命名它们的排列。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The compound is literal: the roots of one plant plus the system they form.","cn":"这个复合词是字面组合：一株植物的根，加上它们构成的系统。"},{"en":"Botany contrasts two basic types: taproot system and fibrous root system.","cn":"植物学对比两种基本类型：直根系与须根系。"},{"en":"The functional words are anchorage and absorption, which is why depth matters.","cn":"功能关键词是固着与吸收，这正是深度重要的原因。"},{"en":"Root architecture and lateral root are the usual companions in research writing.","cn":"根系构型与侧根是研究写作中的常见配套词。"},{"en":"The mathematical sense belongs to Lie algebra, not to botany.","cn":"数学义属于李代数，与植物学无关。"}],"abstract":[{"en":"Picture a grass sod lifted like a carpet, the underside a dense even mat.","cn":"想象一块草皮像地毯一样被掀起，背面是一张密集均匀的垫子。"},{"en":"Picture a carrot pulled from the soil, one long root with small side threads.","cn":"想象一根胡萝卜被拔出，一条长主根带着细小的侧根。"},{"en":"Picture an organization chart drawn as roots feeding a single trunk above ground.","cn":"想象一张组织图被画成根在地下供养地上的一根主干。"}]},"examples":[{"en":"The seedlings were planted with their root systems kept moist.","cn":"幼苗栽下时，根系保持湿润。"},{"en":"A deep root system lets the shrub survive a long dry season.","cn":"深根系让这种灌木熬过漫长的旱季。"},{"en":"Engineers study root system architecture to stabilize slopes.","cn":"工程人员研究根系构型，用来稳固坡面。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「根 + 系统」——一株植物所有根连成的一整套网络 → 根系","word":"root system"},"root":"前一词为古英语 rōt / 古诺斯语 rót，来自原始日耳曼语 *wrōts；后一词经晚期拉丁语 systema 上溯希腊语 systema「有组织的整体」。植物学两类型术语定型于十九世纪，数学义为独立造词。","sensesIntro":{"en":"Eight senses move between whole and type, structure and function, and finally between botany, mathematics and society. The same compound can name a plant's entire underground body, one of its two basic architectures, a spatial pattern, a job, a set of vectors or a social base.","cn":"八个义项在整体与类型、结构与功能之间移动，最后跨越植物学、数学与社会。同一个复合词可以指一株植物的全部地下身体、两种基本构型之一、一种空间格局、一项功能、一组向量或一个社会基础。"},"semanticMap":{"core":{"en":"CORE IMAGE: an underground mat wider than the plant above it, every thread connected.","cn":"核心意象：地下一张比地上植株更宽的网络，每一根丝都相连。"},"chain":["ROOTS CONNECT","ONE PLANT","LATERALS SPREAD","ANCHOR THE PLANT","ABSORB WATER","GENERATE A STRUCTURE"],"branches":[{"senses":"01 · 04","en":"WHOLE AND SPREAD: the network as a whole, and the laterals that give it width.","cn":"整体与展幅：作为整体的网络，以及赋予它宽度的侧根。"},{"senses":"02 · 03","en":"TWO ARCHITECTURES: one dominant root or many equal roots.","cn":"两种构型：一条主导根，或许多等大的根。"},{"senses":"05 · 06","en":"FUNCTIONS: the same network either anchors or feeds.","cn":"功能：同一网络，或用于固定，或用于供养。"},{"senses":"07","en":"MATHEMATICAL GENERATION: vectors that generate a structure are called roots by analogy.","cn":"数学生成：生成结构的向量被类比称为根。"},{"senses":"08","en":"SOCIAL BASE: many small units support one visible structure.","cn":"社会基础：许多小单元支撑一个可见结构。"}]},"affixes":{"intro":{"en":"The compound joins a Germanic root word to a Greek-derived system word, so its two halves come from different layers of English vocabulary.","cn":"这个复合词把日耳曼来源的根词与希腊来源的系统词接在一起，两半来自英语词汇的不同层次。"},"latinIntro":{"en":"Latin radix is a cognate of root and supplies the technical term; Greek systema reached English through Late Latin systema. Neither half is a direct Latin derivative of the compound.","cn":"拉丁语 radix 是 root 的同源词并提供技术术语；希腊语 systema 经晚期拉丁语 systema 进入英语。两半都不是这个复合词的直接拉丁派生。"},"latinEntries":[{"word":"radix","structure":"radix, radicis (f., third declension)","meaning":"root; base","meaningCN":"根；基数（这一拉丁词与英语词同族）"},{"word":"systema","structure":"systema, systematis (n., third declension, from Greek)","meaning":"an organized whole","meaningCN":"有组织的整体"},{"word":"rhiza","structure":"rhiza (Greek noun, 'root')","meaning":"root","meaningCN":"根（希腊语同源词）"}],"items":[{"word":"root","structure":"root (Old English rōt, Old Norse rót)","meaning":"the underground organ","meaningCN":"根","example":"Each root ends in a growing tip.","exampleCN":"每条根末端都有生长尖。"},{"word":"system","structure":"systema (Greek via Latin)","meaning":"an organized set of parts","meaningCN":"系统；体系","example":"The system works as a whole.","exampleCN":"这个系统作为整体运作。"},{"word":"root system","structure":"root + system","meaning":"all the roots of a plant as one network","meaningCN":"根系","example":"The root system binds the slope.","exampleCN":"根系固定坡面。"},{"word":"root hair","structure":"root + hair","meaning":"a tiny tubular outgrowth of a root","meaningCN":"根毛","example":"Root hairs increase the absorbing surface.","exampleCN":"根毛增加吸收表面。"},{"word":"taproot","structure":"tap + root","meaning":"the single dominant root","meaningCN":"主根；直根","example":"The taproot stores sugar through the winter.","exampleCN":"主根在整个冬天储存糖分。"},{"word":"fibrous root","structure":"fibre + -ous + root","meaning":"a fine root of similar size to its neighbours","meaningCN":"须根","example":"Fibrous roots form a dense mat.","exampleCN":"须根形成密集的垫层。"},{"word":"rootstock","structure":"root + stock","meaning":"root and lower stem used in grafting","meaningCN":"根砧；根茎","example":"The scion was joined to a vigorous rootstock.","exampleCN":"接穗被接到强壮的根砧上。"},{"word":"lateral root","structure":"lateral + root","meaning":"a root growing sideways from another root","meaningCN":"侧根","example":"Lateral roots explore new soil.","exampleCN":"侧根探索新的土壤。"},{"word":"root architecture","structure":"root + architecture","meaning":"the spatial arrangement of roots","meaningCN":"根系构型","example":"Root architecture affects drought tolerance.","exampleCN":"根系构型影响耐旱性。"}]}},{"word":"stem","ipa_uk":"/stem/","ipa_us":"/stem/","definition_zh":"茎；茎状柄；词干；阻止；起源于","definition_en":"the main stalk of a plant; a stalk supporting a leaf, flower or fruit; the base form of a word; to stop or originate","core_image":"一株植物从土里抽出单一的直立轴，叶片和花都从这条轴上分出","scene":"园丁剪下花枝时，特意在茎的中间斜切一刀，好让切口吸水。 When cutting the flower, the gardener makes a slanting cut halfway through the stem so that the cut end can take up water.","sceneCN":"这里该词指「花的主茎」（第 1 个义项：植物的主要直立轴）；句意为园丁剪花时在茎的中部斜切一刀，让切口能够吸水。","pos":[{"tag":"n.","zh":"茎；主干；茎状物"},{"tag":"n.","zh":"（叶、花、果的）柄"},{"tag":"n.","zh":"（语言学）词干"},{"tag":"v.","zh":"阻止；遏制（水流、趋势）"},{"tag":"v.","zh":"起源于；由……而来"},{"tag":"n.","zh":"（手表）柄轴；表冠"},{"tag":"n.","zh":"（烟斗、管乐器）柄；管"},{"tag":"n.","zh":"（音乐）符干"}],"collocations":[{"phrase":"stem from","zh":"起源于；由……造成"},{"phrase":"stem the tide","zh":"遏止潮流；扭转趋势"},{"phrase":"stem the flow","zh":"堵住水流"},{"phrase":"plant stem","zh":"植物茎"},{"phrase":"long stem","zh":"长茎"},{"phrase":"stem cell","zh":"干细胞"},{"phrase":"stem the decline","zh":"遏止下滑"}],"forms":[{"label":"复数（茎）","form":"stems"},{"label":"三单（阻止；起源）","form":"stems"},{"label":"过去式","form":"stemmed"},{"label":"过去分词","form":"stemmed"},{"label":"现在分词","form":"stemming"},{"label":"形容词（去柄的）","form":"stemmed"}],"derivatives":[{"word":"stemming","pos":"n.","zh":"词干提取；去柄"},{"word":"stemmed","pos":"adj.","zh":"去柄的；有柄的"},{"word":"stemless","pos":"adj.","zh":"无茎的"},{"word":"stemware","pos":"n.","zh":"高脚玻璃器皿"},{"word":"stem cell","pos":"n.","zh":"干细胞"}],"senses":[{"no":"01","title":"Main stalk of a plant","titleCN":"植物的主茎","definition":"the main upright stalk of a plant that supports leaves, flowers and fruit","definitionCN":"支撑叶、花与果实的植物主要直立轴","example":"A single stem rises from the bulb and carries six white flowers.","exampleCN":"一条茎从球茎中升起，顶着六朵白花。","why":"This is the central plant sense: one axis from which other parts leave.","whyCN":"这是核心植物义：一条轴，其他部分从它上面离开。"},{"no":"02","title":"Stalk of a leaf or flower","titleCN":"叶柄或花柄","definition":"the small stalk that attaches a leaf, flower or fruit to a larger stem","definitionCN":"把叶、花或果实连接到更大茎上的小柄","example":"The leaf stem is short, so the blades crowd the branch.","exampleCN":"叶柄很短，所以叶片挤在枝条上。","why":"The word is applied to a supporting stalk at any scale, not only the main axis.","whyCN":"这个词可用于任何尺度的支撑柄，不只主茎。"},{"no":"03","title":"Linguistic stem","titleCN":"语言学词干","definition":"the part of a word to which inflectional endings are added","definitionCN":"词中加上屈折词尾的那一部分","example":"The plural ending is attached to the stem, not to the whole word.","exampleCN":"复数词尾加在词干上，而不是整个词上。","why":"Grammar borrows the plant image: endings grow out of a base that stays constant.","whyCN":"语法借用植物意象：词尾从一个保持不变的基础长出来。"},{"no":"04","title":"Stop the flow","titleCN":"阻止流动","definition":"to stop or restrict the movement of water, blood or a trend","definitionCN":"阻止或限制水、血液或趋势的流动","example":"Sandbags were piled up to stem the floodwater.","exampleCN":"人们堆起沙袋来堵住洪水。","why":"The verb image is a hand pressed against a current, stopping it at the stem or source.","whyCN":"动词意象是一只手压住水流，在源头或干流处把它截住。"},{"no":"05","title":"Originate from","titleCN":"起源于","definition":"to come from or be caused by something","definitionCN":"来自某物；由某物造成","example":"Most of the complaints stem from a single scheduling error.","exampleCN":"大多数投诉都源于一次排期失误。","why":"Here the image reverses: instead of stopping a flow, the word traces a flow back to its source.","whyCN":"这里意象反转：不是截住流动，而是把流动追溯回它的源头。"},{"no":"06","title":"Watch winding stem","titleCN":"手表的柄轴","definition":"the small shaft that carries the crown of a watch and connects it to the movement","definitionCN":"承载表冠并连接机芯的小轴","example":"He turned the stem until the watch began to tick.","exampleCN":"他转动柄轴，直到手表开始走动。","why":"A mechanical stem is a small upright shaft, so the plant word was borrowed for its shape.","whyCN":"机械柄轴是一根小直立轴，因此借用了植物词的形状。"},{"no":"07","title":"Pipe stem","titleCN":"烟斗或管乐器的柄","definition":"the tubular part of a pipe or wind instrument held in the mouth or hand","definitionCN":"烟斗或管乐器中供口含或手握的管状部分","example":"The old pipe had a cracked stem and leaked smoke.","exampleCN":"那只旧烟斗的柄裂了，漏烟。","why":"The shape is again a narrow shaft, this time hollow and serving as a channel.","whyCN":"形状仍是细长轴，这次是中空并充当通道。"},{"no":"08","title":"Musical note stem","titleCN":"音乐符干","definition":"the vertical line attached to the head of a written musical note","definitionCN":"书写音符时连接音符头的竖线","example":"The composer lengthened the note by adding a second stem.","exampleCN":"作曲者加了第二条符干，把那个音符延长。","why":"The visual mark is a thin upright line, named by resemblance to a stalk.","whyCN":"这个视觉符号是一条细竖线，因形似茎而得名。"},{"no":"09","title":"Remove stems","titleCN":"去掉茎或柄","definition":"to take the stems off fruit, vegetables or leaves","definitionCN":"去掉果实、蔬菜或叶子的茎柄","example":"She stemmed the cherries before making the jam.","exampleCN":"做果酱前，她先把樱桃去柄。","why":"The verb turns the noun into a removal action: the stem is the part taken away.","whyCN":"动词把名词变成去除动作：茎柄就是被拿掉的那部分。"}],"etymology":{"intro":{"en":"The plant noun is Old English and Germanic; the verb senses are later developments whose exact motivations are partly uncertain.","cn":"植物名词为古英语与日耳曼来源；动词义的理据部分存疑，印欧语重构也不确定。"},"items":[{"era":"OLD ENGLISH","en":"Old English had stefn and stemn meaning 'trunk, stem, prow of a ship'. The form with -m- eventually won in the plant sense.","cn":"古英语有 stefn 与 stemn，意为「树干、茎、船首」。带 -m- 的形式最终在植物义中胜出。"},{"era":"PROTO-GERMANIC","en":"The reconstructed ancestor is *stamniz, with cognates in German Stamm 'stem, tribe' and Dutch stam 'trunk'. The family also gives English staff and understand in related branches.","cn":"重构的祖词是 *stamniz，同族词见于德语 Stamm「茎、部族」与荷兰语 stam「树干」。这一词族在相关分支里还给出英语 staff 与 understand。"},{"era":"PROTO-INDO-European","en":"A link to *stebh- 'post, stem' is often proposed, but the reconstruction is uncertain and the set of cognates is disputed.","cn":"常有人提出与 *stebh-「柱、茎」有关，但这一重构不确定，同源词范围也有争议。"},{"era":"MIDDLE AND EARLY MODERN ENGLISH","en":"The noun extended from the main stalk to the stalk of a leaf or flower, and then to narrow shafts such as a watch stem or pipe stem by shape.","cn":"名词从主茎扩展到叶柄、花柄，再按形状扩展到表轴、烟斗柄等细长轴。"},{"era":"ENGLISH VERB (16th-19th c.)","en":"The verb 'to stop a flow' is recorded in the sixteenth century; its motivation is uncertain, perhaps from the image of checking water at its source. The sense 'to originate from' is nineteenth-century.","cn":"动词「阻止流动」记录于十六世纪，理据存疑，可能来自在源头截水的意象。「起源于」义则是十九世纪的事。"},{"era":"MODERN ENGLISH","en":"Twentieth-century biology added stem cell, where stem means the unspecialized base from which other cell types develop.","cn":"二十世纪生物学增加了干细胞一语，其中 stem 指未分化、其他细胞类型由之发育的基础。"}]},"similar":{"note":{"en":"The first group is close in spelling or sound but unrelated or only partly related; the second group shares the plant or flow image without being interchangeable.","cn":"第一组在拼写或读音上接近，但无关或仅部分相关；第二组共享植物或流动意象，但不能互换。"},"groups":[{"heading":"SOUND-ALIKE","entries":[{"word":"steam","ipa":"/stiːm/","tag":"near sound, different word","definition":"water vapor, from Old English stēam. The vowel is long and the final consonant is not m, so the two words are not variants.","definitionCN":"蒸汽；水汽。来自古英语 stēam。元音更长，结尾音也不同，两词并非变体。"},{"word":"step","ipa":"/step/","tag":"near sound, different word","definition":"a movement of the foot or a stage in a process, from Old English stæpe.","definitionCN":"脚步；步骤。来自古英语 stæpe，与茎无关。"},{"word":"stern","ipa":"/stɜːn/","tag":"near sound, different word","definition":"the back part of a ship; also severe. It comes from a different Germanic source.","definitionCN":"船尾；严厉的。来自另一支日耳曼语来源。"}]},{"heading":"NEAR-MEANING","entries":[{"word":"stalk","ipa":"/stɔːk/","tag":"plant support","definition":"the main support of a plant or a single supporting stem; it overlaps with stem but often suggests a taller, more slender support.","definitionCN":"茎；秆。植物的主要支撑或单条支撑茎；与 stem 重叠，但常暗示更高更细的支撑。"},{"word":"trunk","ipa":"/trʌŋk/","tag":"woody main axis","definition":"the thick woody main axis of a tree; a stem can be soft or thin, while a trunk is always woody and substantial.","definitionCN":"树干。树木粗大的木质主轴；stem 可以是柔软细小的，而 trunk 必然是木质且粗大的。"},{"word":"shoot","ipa":"/ʃuːt/","tag":"new growth","definition":"a young stem plus its leaves; it is new growth, whereas stem names the axis itself.","definitionCN":"枝条；新芽。幼茎连同叶片，是新生部分；stem 命名的是轴本身。"},{"word":"branch","ipa":"/brɑːntʃ/","tag":"side limb","definition":"a limb growing from the main stem or trunk; it is a side division, not the central axis.","definitionCN":"枝条；分枝。从主茎或树干长出的侧枝，是侧向分叉，不是中央轴。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Old English stefn and stemn both meant trunk or stem, and the -m- form survived.","cn":"古英语 stefn 与 stemn 都表示树干或茎，最终带 -m- 的形式留存下来。"},{"en":"German Stamm and Dutch stam are close relatives, and both also mean a tribe or stock.","cn":"德语 Stamm 与荷兰语 stam 是近亲，两者也都可指部族或世系。"},{"en":"The verb pairs with tide, flow and decline: stem the tide, stem the flow, stem the decline.","cn":"动词常与 tide、flow、decline 搭配：遏止潮流、堵住水流、遏止下滑。"},{"en":"The prepositional pattern is stem from, not stem of.","cn":"介词搭配是 stem from，而不是 stem of。"},{"en":"Biology fixed the compound stem cell for an unspecialized base cell.","cn":"生物学固定了复合词 stem cell，指未分化的基础细胞。"}],"abstract":[{"en":"Picture a single reed rising from wet ground, leaves peeling away from it.","cn":"想象一根芦苇从湿地升起，叶片从它上面剥开。"},{"en":"Picture a hand pressed against a leaking pipe, stopping the jet at its source.","cn":"想象一只手按在漏水的管子上，在源头堵住水柱。"},{"en":"Picture a word ending snapping onto a base like a leaf onto a stem.","cn":"想象词尾像叶子长在茎上那样扣到词干上。"}]},"examples":[{"en":"The gardener cut the stem just below the lowest leaf.","cn":"园丁在最下面一片叶子的下方剪断了茎。"},{"en":"The new policy is meant to stem the loss of farmland.","cn":"新政策意在遏止农田流失。"},{"en":"Many of these problems stem from a lack of clear records.","cn":"这些问题许多都源于记录不清。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「死呆木」——一根直直不动的杆子 → 茎；把水「定住」→ 阻止","word":"stem"},"root":"古英语 stefn / stemn「树干、茎、船首」，重构的原始日耳曼语为 *stamniz，与德语 Stamm、荷兰语 stam 同族。与印欧语 *stebh-「柱、茎」的联系不确定；动词「阻止」义的理据也存疑。","sensesIntro":{"en":"Nine senses follow one shape: a single upright axis. The axis is a plant organ, then a supporting stalk, then a grammatical base, then a mechanical shaft, a pipe, a note mark; the verb senses either stop a current at its source or trace a current back to it.","cn":"九个义项沿同一个形状展开：一条直立轴。这条轴先是植物器官，再是支撑柄、语法基础、机械轴、烟管、音符记号；动词义则要么在源头截住流动，要么把流动追溯回源头。"},"semanticMap":{"core":{"en":"CORE IMAGE: one straight axis with other parts leaving it at intervals.","cn":"核心意象：一条直轴，其他部分每隔一段从它上面离开。"},"chain":["UPRIGHT AXIS","SUPPORTS LEAVES","GRAMMATICAL BASE","MECHANICAL SHAFT","HOLLOW CHANNEL","STOP A FLOW"],"branches":[{"senses":"01 · 02","en":"PLANT SUPPORT: the main axis and the smaller stalks that leave it.","cn":"植物支撑：主轴，以及从它分出的较小柄。"},{"senses":"03","en":"LINGUISTIC BASE: endings are added to a constant stem.","cn":"语法基础：词尾加在不变的词干上。"},{"senses":"04 · 05","en":"FLOW IN TWO DIRECTIONS: the verb either blocks a current or follows it back.","cn":"流动的两个方向：动词或截住水流，或把水流追溯回去。"},{"senses":"06 · 07 · 08","en":"NARROW SHAFTS: watch, pipe and musical mark are all named by shape.","cn":"细长轴：表轴、烟管与音符记号都按形状命名。"},{"senses":"09","en":"REMOVAL: the noun becomes the part taken off.","cn":"去除：名词变成被拿掉的部分。"}]},"affixes":{"intro":{"en":"Stem is a short Germanic word; its family is mostly built by English compounds rather than Latin derivation, with a few learned compounds added in modern science.","cn":"stem 是一个简短日耳曼词，其词族主要靠英语复合而非拉丁派生构成，现代科学又加入少数仿造复合词。"},"latinIntro":{"en":"There is no Latin source for stem and no Latin cognate, so the Latin table is left empty; the affixes below are all English or Germanic-formative.","cn":"英语 stem 既没有拉丁来源，也没有拉丁同族词，因此拉丁词表留空；下面的词缀条目全部是英语或日耳曼构词成分。"},"latinEntries":[],"items":[{"word":"stem","structure":"stem (Old English stefn / stemn)","meaning":"the main stalk; a shaft","meaningCN":"茎；主轴；柄","example":"The stem carries the whole flower head.","exampleCN":"茎承载整个花头。"},{"word":"stemmed","structure":"stem + -ed (having or provided with)","meaning":"having had the stem removed","meaningCN":"去柄的","example":"Stemmed cherries are ready for the pot.","exampleCN":"去柄的樱桃可以下锅了。"},{"word":"stemming","structure":"stem + -ing (action)","meaning":"the act of removing stems; also reducing words to stems","meaningCN":"去柄；词干提取","example":"Stemming groups related word forms.","exampleCN":"词干提取把相关词形归为一组。"},{"word":"stemless","structure":"stem + -less (without)","meaning":"having no stem","meaningCN":"无茎的","example":"The stemless plant grows flat against the rock.","exampleCN":"这种无茎植物贴着岩石生长。"},{"word":"stemware","structure":"stem + ware (glassware)","meaning":"glasses with a stem","meaningCN":"高脚玻璃器皿","example":"The cabinet holds a set of delicate stemware.","exampleCN":"柜子里有一套精致的高脚杯。"},{"word":"stem cell","structure":"stem + cell","meaning":"an unspecialized cell that can develop into other types","meaningCN":"干细胞","example":"Stem cells can repair some tissues.","exampleCN":"干细胞能修复某些组织。"},{"word":"taproot","structure":"tap + root","meaning":"a single dominant root, by contrast with a stem","meaningCN":"主根（与茎对照）","example":"The taproot stores water below ground.","exampleCN":"主根在地下储水。"},{"word":"rootstock","structure":"root + stock","meaning":"root and lower stem used in grafting","meaningCN":"根砧","example":"The stem above the graft is the scion.","exampleCN":"嫁接口以上的茎是接穗。"},{"word":"understand","structure":"under + stand (related Germanic family)","meaning":"to grasp the meaning of something","meaningCN":"理解","example":"The related verb shows how far the Germanic family spreads.","exampleCN":"这个相关动词显示该日耳曼词族分布之广。"}]}},{"word":"trunk","ipa_uk":"/trʌŋk/","ipa_us":"/trʌŋk/","definition_zh":"树干；象鼻；躯干；大箱子；汽车后备箱","definition_en":"the thick main stem of a tree; an elephant's long nose; a person's torso; a large chest or luggage compartment","core_image":"一棵老树从地面到第一根分枝之间那段粗壮、没有枝叶的圆柱","scene":"这棵橡树的树干要三个人才能合抱，树皮上满是深深的纵裂。 Three people would need to join hands to encircle the oak's massive trunk, whose bark is scored with deep vertical cracks.","sceneCN":"这里该词指「树木的主干」（第 1 个义项：树木粗壮的主要木质轴）；句意为这棵橡树的树干粗到要三个人合抱，树皮上布满深深的纵裂。","pos":[{"tag":"n.","zh":"树干；树木的主干"},{"tag":"n.","zh":"象鼻"},{"tag":"n.","zh":"躯干（不含头与四肢）"},{"tag":"n.","zh":"大箱子；旅行箱"},{"tag":"n.","zh":"（美式）汽车后备箱"},{"tag":"n.","zh":"（解剖）大血管或神经干"},{"tag":"n.","zh":"（铁路、电信）干线"},{"tag":"n.","zh":"（复数）游泳裤"}],"collocations":[{"phrase":"tree trunk","zh":"树干"},{"phrase":"elephant trunk","zh":"象鼻"},{"phrase":"trunk road","zh":"干线公路"},{"phrase":"trunk line","zh":"干线；中继线"},{"phrase":"swimming trunks","zh":"游泳裤"},{"phrase":"car trunk","zh":"汽车后备箱"},{"phrase":"trunk of the body","zh":"躯干"}],"forms":[{"label":"复数（树干；箱子）","form":"trunks"},{"label":"形容词（树干的；躯干的）","form":"trunked"},{"label":"相关名词（树干部分）","form":"bole"},{"label":"相关名词（汽车后备箱，英式）","form":"boot"},{"label":"相关名词（行李箱）","form":"suitcase"}],"derivatives":[{"word":"trunkless","pos":"adj.","zh":"无树干的"},{"word":"trunkful","pos":"n.","zh":"一箱之量（少用）"},{"word":"trunked","pos":"adj.","zh":"有树干的；干线的"},{"word":"trunking","pos":"n.","zh":"干线系统；线槽"},{"word":"trunk line","pos":"n.","zh":"干线；中继线"}],"senses":[{"no":"01","title":"Main stem of a tree","titleCN":"树干","definition":"the thick main stem of a tree, from the ground to the first major branches","definitionCN":"树木从地面到第一根大枝之间粗壮的主茎","example":"The trunk of the ancient beech is hollow with age.","exampleCN":"这棵老山毛榉的树干因年岁而中空。","why":"This is the core body sense: one thick column that carries the whole crown.","whyCN":"这是核心实体义：一根粗柱承载整个树冠。"},{"no":"02","title":"Elephant's long nose","titleCN":"象鼻","definition":"the long flexible nose of an elephant, used for breathing, smelling and grasping","definitionCN":"大象长而灵活、用于呼吸、嗅闻与抓取的鼻子","example":"The elephant curled its trunk around a branch and stripped the leaves.","exampleCN":"大象用鼻子卷住一根枝条，把叶子捋下来。","why":"The word is borrowed for a long flexible tube, by resemblance to a thick stem.","whyCN":"这个词因形似粗茎而被借用来指长而灵活的管子。"},{"no":"03","title":"Human torso","titleCN":"人的躯干","definition":"the main part of the human body, excluding the head, arms and legs","definitionCN":"人体除去头、臂与腿的主要部分","example":"The swimmer rotated his trunk to breathe to the side.","exampleCN":"游泳者转动躯干，向侧面换气。","why":"The trunk is the body's central column, the same image as the tree's main stem.","whyCN":"躯干是人体的中央柱，与树的主干是同一意象。"},{"no":"04","title":"Large chest or luggage","titleCN":"大箱子；旅行箱","definition":"a large box with a lid, used for storing or carrying clothes and possessions","definitionCN":"带盖的大箱，用来存放或搬运衣物与物品","example":"The attic held a carved wooden trunk full of old letters.","exampleCN":"阁楼里有一只雕花木箱，装满旧信件。","why":"A chest is a box whose body is a solid column; the shape link is the bulky closed body.","whyCN":"箱子是一个箱体为实心柱状的结构；形状联系在于厚实封闭的箱体。"},{"no":"05","title":"Car boot (American)","titleCN":"汽车后备箱","definition":"the enclosed storage space at the back of a car","definitionCN":"汽车后部的封闭储物空间","example":"She packed the tent and boots into the trunk of the car.","exampleCN":"她把帐篷和靴子塞进汽车后备箱。","why":"The luggage sense was transferred to the car's storage compartment, which is literally a built-in trunk.","whyCN":"行李箱义被转移到汽车的储物厢，后者字面上就是一个内置箱体。"},{"no":"06","title":"Anatomical trunk","titleCN":"解剖学的大血管或神经干","definition":"the main body of a blood vessel or nerve, before it divides into branches","definitionCN":"血管或神经在分支之前的主干部分","example":"The surgeon clamped the pulmonary trunk above its split.","exampleCN":"外科医生在肺动脉干分叉处上方夹住了它。","why":"Anatomy uses the tree image directly: a vessel has a trunk and then branches.","whyCN":"解剖学直接使用树的意象：血管有主干，然后分枝。"},{"no":"07","title":"Trunk line","titleCN":"铁路或电信干线","definition":"a main route or main cable from which smaller lines branch off","definitionCN":"主线路或主缆，较小的线路由它分出","example":"The new trunk line carries traffic from the port to the interior.","exampleCN":"新的干线把港口的运输引向内地。","why":"A network is drawn as a tree; the main route is its trunk and local routes are branches.","whyCN":"网络被画成一棵树；主线路是树干，地方线路是枝条。"},{"no":"08","title":"Swimming trunks","titleCN":"游泳裤","definition":"short trousers worn by men for swimming, usually in the plural","definitionCN":"男子游泳时穿的短裤，通常用复数","example":"He packed a towel and a pair of trunks for the beach.","exampleCN":"他带了一条毛巾和一条游泳裤去海滩。","why":"The plural word names a garment as a compact body covering, echoing the 'box' sense rather than the tree sense.","whyCN":"这个复数词把衣物看作紧凑的身体覆盖物，呼应的是「箱体」义而不是树木义。"}],"etymology":{"intro":{"en":"The Latin noun is clear, but its deeper origin is disputed; the many English senses are later extensions, some by shape and some by function.","cn":"拉丁名词本身清楚，但其更深来源有争议；各英语义项为后世扩展，有的按形状，有的按功能。"},"items":[{"era":"LATIN","en":"Truncus meant 'trunk of a tree, stem; torso; a maimed body'. It is the direct source of the English word through French.","cn":"truncus 意为「树干、茎；躯干；被截断的身体」，经法语成为英语词的直接来源。"},{"era":"LATIN DERIVATION","en":"Truncus is generally linked to truncare 'to cut off, maim', but whether the noun or the verb came first is uncertain; the original image may be a body cut short.","cn":"truncus 一般认为与 truncare「截断、使残废」有关，但名词与动词孰先孰后不确定；原始意象可能是被截短的身体。"},{"era":"OLD FRENCH (13th c.)","en":"Old French tronc meant the stem of a tree and also the body. English borrowed it in the thirteenth century.","cn":"古法语 tronc 指树干，也指身体。英语在十三世纪借入。"},{"era":"ENGLISH (16th-18th c.)","en":"The elephant's trunk is recorded in the sixteenth century, the luggage chest in the seventeenth, and the anatomical trunk in learned usage.","cn":"象鼻义记录于十六世纪，行李箱义在十七世纪，解剖学上的「干」见于学术用法。"},{"era":"ENGLISH (19th-20th c.)","en":"Railway and telephone trunk lines appear in the nineteenth century, swimming trunks in the nineteenth, and the American car trunk in the twentieth.","cn":"铁路与电话干线出现在十九世纪，游泳裤也在十九世纪，美式汽车后备箱义则在二十世纪。"},{"era":"MODERN ENGLISH","en":"The senses now form a family of thick central bodies: tree, elephant, human, vessel, route and box.","cn":"这些义项现在构成一族「粗大的中央体」：树、象、人、血管、路线与箱体。"}]},"similar":{"note":{"en":"The first group is close in sound or shape; the second group shares the idea of a central body but differs in scope or register.","cn":"第一组在读音或形状上接近；第二组共享「中央主体」的意思，但范围或语体不同。"},"groups":[{"heading":"SOUND-ALIKE","entries":[{"word":"truck","ipa":"/trʌk/","tag":"near sound, different word","definition":"a large road vehicle, from Latin trochus or French troque, not from truncus.","definitionCN":"卡车；货车。来自拉丁语 trochus 或法语 troque，并非 truncus。"},{"word":"chunk","ipa":"/tʃʌŋk/","tag":"near sound, different word","definition":"a thick piece of something, probably a variant of chuck; the initial consonant differs.","definitionCN":"大块；厚块。可能是 chuck 的变体；开头辅音不同。"},{"word":"truncheon","ipa":"/ˈtrʌntʃən/","tag":"same Latin family","definition":"a short thick club carried by police; it is built on the same truncus family and means a cut-off piece.","definitionCN":"警棍。与 truncus 同族，字面是「被截下的一段」。"}]},{"heading":"NEAR-MEANING","entries":[{"word":"bole","ipa":"/bəʊl/","tag":"tree trunk term","definition":"the trunk of a tree, especially a tall forest tree; it is a narrower technical word for the same tree sense.","definitionCN":"树干。尤指高大林木的主干，是树木义中范围更窄的技术词。"},{"word":"log","ipa":"/lɒɡ/","tag":"cut wood","definition":"a section of a felled tree trunk; it is the trunk after cutting, not the standing stem.","definitionCN":"原木。伐倒树干的一段，是砍下之后的树干，不是立着的茎。"},{"word":"torso","ipa":"/ˈtɔːsəʊ/","tag":"body term","definition":"the human trunk considered as a body part, especially in anatomy and art; it lacks the tree and luggage senses.","definitionCN":"躯干。作为身体部位的人体干，尤用于解剖与艺术；没有树木与箱子的义项。"},{"word":"chest","ipa":"/tʃest/","tag":"container sense","definition":"a large strong box, usually with a hinged lid; it overlaps with trunk only in the luggage sense.","definitionCN":"大箱子。通常带铰链盖的坚固大箱，只在行李箱义上与 trunk 重叠。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Latin truncus supplies the word through French tronc, and truncare is its probable verb relative.","cn":"拉丁语 truncus 经法语 tronc 提供这个词，truncare 是它可能相关的动词。"},{"en":"The family keeps the idea of a central body: trunk, trunked, trunking, trunk line.","cn":"词族保留「中央主体」的意思：trunk、trunked、trunking、trunk line。"},{"en":"Tree collocations: tree trunk, hollow trunk, trunk diameter.","cn":"树木搭配：树干、中空树干、树干直径。"},{"en":"Transport collocations: trunk road, trunk line, car trunk.","cn":"交通搭配：干线公路、干线、汽车后备箱。"},{"en":"American English uses trunk for the car boot; British English uses boot.","cn":"美式英语用 trunk 指汽车后备箱；英式英语用 boot。"}],"abstract":[{"en":"Picture a stone column that turns into a tree crown at the top.","cn":"想象一根石柱在顶部变成树冠。"},{"en":"Picture an elephant's nose as a living hose hanging from a thick body.","cn":"想象象鼻像一根活软管，从粗壮的身体上垂下来。"},{"en":"Picture a wooden chest standing on end like a short, solid column.","cn":"想象一只木箱竖立着，像一根短而实心的柱子。"}]},"examples":[{"en":"A fungus entered through a wound in the trunk and hollowed it out.","cn":"真菌从树干上的伤口侵入，把树干蛀空。"},{"en":"The elephant used its trunk to reach fruit high in the canopy.","cn":"大象用鼻子够到树冠高处的果子。"},{"en":"The old railway trunk line was replaced by a new high-speed route.","cn":"旧铁路干线被一条新的高速线路取代。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「撞壳」——粗壮、结实、像外壳一样的中央主体 → 树干 → 箱体","word":"trunk"},"root":"拉丁语 truncus「树干、茎；躯干；被截断的身体」，经法语 tronc 于十三世纪进入英语。truncus 一般认为与 truncare「截断」有关，但名动先后与原始义存疑。","sensesIntro":{"en":"Eight senses are all thick central bodies. The tree, the elephant, the human, the vessel and the route are columns; the chest and the car compartment are boxes; swimming trunks are a compact body covering. Shape and function split the family into two halves.","cn":"八个义项都是粗大的中央主体。树、象、人体、血管与路线是柱状；箱与车厢是箱体；游泳裤是紧凑的身体覆盖物。形状与功能把这个词族分成两半。"},"semanticMap":{"core":{"en":"CORE IMAGE: a thick column from which everything else either branches or is contained.","cn":"核心意象：一根粗柱，其他部分或从它分枝，或被它容纳。"},"chain":["THICK CENTRAL COLUMN","CARRIES THE CROWN","LONG FLEXIBLE TUBE","BODY WITHOUT LIMBS","SOLID BOX","MAIN ROUTE"],"branches":[{"senses":"01 · 06 · 07","en":"CENTRAL COLUMN: tree, vessel and route all have a main body that divides.","cn":"中央柱：树、血管与路线都有一个先分叉的主体。"},{"senses":"02","en":"SHAPE TRANSFER: a long flexible nose is named after a thick stem.","cn":"形状转移：长而灵活的鼻子按粗茎命名。"},{"senses":"03","en":"HUMAN COLUMN: the torso is the body's central trunk.","cn":"人体柱：躯干是人体的中央主干。"},{"senses":"04 · 05","en":"BOX BODY: chest and car compartment are solid or built-in boxes.","cn":"箱体：箱子与车厢是实体或内置的箱。"},{"senses":"08","en":"COMPACT COVERING: swimming trunks cover the body like a small box.","cn":"紧凑覆盖：游泳裤像小箱体一样覆盖身体。"}]},"affixes":{"intro":{"en":"Trunk has a clear Latin source and a compact family; the affix section separates the Latin verb truncare from later English compounds.","cn":"trunk 有清楚的拉丁来源和紧凑词族；词缀部分把拉丁动词 truncare 与后世英语复合词分开。"},"latinIntro":{"en":"Latin truncus gives trunk, and truncare gives truncate; the English compounds trunk line and swimming trunks are later formations, not Latin words.","cn":"拉丁 truncus 给出 trunk，truncare 给出 truncate；英语复合词 trunk line 与 swimming trunks 是后起构造，不是拉丁词。"},"latinEntries":[{"word":"truncus","structure":"truncus, trunci (m., second declension)","meaning":"trunk of a tree; torso","meaningCN":"树干；躯干"},{"word":"truncare","structure":"truncare, truncavi, truncatum (verb, first conjugation)","meaning":"to cut off, maim","meaningCN":"截断；使残缺"},{"word":"truncus (adjective)","structure":"truncus, trunca, truncum (adjective)","meaning":"cut off, mutilated","meaningCN":"被截断的；残缺的"}],"items":[{"word":"truncus","structure":"truncus (Latin noun, 'trunk, torso')","meaning":"the main body of a tree or person","meaningCN":"树干；躯干","example":"Truncus is the direct source of the English noun.","exampleCN":"这个拉丁词是英语名词的直接来源。"},{"word":"trunk","structure":"truncus via Old French tronc","meaning":"the main stem; a box; a torso","meaningCN":"树干；箱体；躯干","example":"The trunk supports the whole crown.","exampleCN":"树干支撑整个树冠。"},{"word":"truncate","structure":"truncare + -ate (verb ending)","meaning":"to shorten by cutting off","meaningCN":"截短；截断","example":"The editor truncated the quotation.","exampleCN":"编辑截短了引文。"},{"word":"truncation","structure":"truncate + -ion (action or result)","meaning":"the act or result of cutting short","meaningCN":"截断；截短","example":"Truncation removed the final clause.","exampleCN":"截断删去了最后一个从句。"},{"word":"trunked","structure":"trunk + -ed (having)","meaning":"having a trunk; connected by a trunk line","meaningCN":"有树干的；干线的","example":"The trunked radio system covers the valley.","exampleCN":"干线无线电系统覆盖整个山谷。"},{"word":"trunking","structure":"trunk + -ing (system or material)","meaning":"a system of trunk lines or a cable duct","meaningCN":"干线系统；线槽","example":"Trunking carries many calls over one link.","exampleCN":"中继把许多通话汇到一条链路上。"},{"word":"trunk line","structure":"trunk + line","meaning":"a main route or cable","meaningCN":"干线；中继线","example":"The trunk line links the port to the capital.","exampleCN":"干线把港口与首都连接起来。"},{"word":"trunk road","structure":"trunk + road","meaning":"a main road between large towns","meaningCN":"干线公路","example":"The trunk road was closed by snow.","exampleCN":"干线公路因积雪封闭。"},{"word":"swimming trunks","structure":"swimming + trunks","meaning":"short trousers for swimming","meaningCN":"游泳裤","example":"He forgot his swimming trunks.","exampleCN":"他忘了带游泳裤。"}]}},{"word":"branch","ipa_uk":"/brɑːntʃ/","ipa_us":"/bræntʃ/","definition_zh":"树枝；分支；分部；支流；分叉","definition_en":"a limb growing from the trunk or main stem of a tree; a division of an organization, subject or system; to divide into parts","core_image":"一条主干在某个节点分成两条方向不同的侧枝，各自继续向外延伸","scene":"春天修剪时，园丁把最粗的枝条留下，只去掉那些交叉摩擦的小枝。 In spring pruning, the gardener keeps the thickest branch and removes only the small ones that rub against each other.","sceneCN":"这里该词指「树上长出的枝条」（第 1 个义项：从主干分出的木质侧枝）；句意为春季修剪时，园丁保留最粗的枝条，只去掉交叉摩擦的小枝。","pos":[{"tag":"n.","zh":"树枝；枝条"},{"tag":"n.","zh":"（组织、机构的）分支；分部"},{"tag":"n.","zh":"（学科的）分支；领域"},{"tag":"n.","zh":"（银行、商店的）分行；分店"},{"tag":"n.","zh":"（计算机）分支；分支版本"},{"tag":"n.","zh":"（语言学）语系分支"},{"tag":"n.","zh":"（政府）部门；分支"},{"tag":"n.","zh":"（河流的）支流；分汊"},{"tag":"v.","zh":"分叉；分支；分成两部分"}],"collocations":[{"phrase":"branch off","zh":"分岔；岔开"},{"phrase":"branch out","zh":"扩展业务；开辟新领域"},{"phrase":"branch office","zh":"分公司；分支机构"},{"phrase":"executive branch","zh":"行政部门"},{"phrase":"branch line","zh":"支线"},{"phrase":"olive branch","zh":"橄榄枝；和解的表示"}],"forms":[{"label":"复数（枝条；分支）","form":"branches"},{"label":"三单（分叉）","form":"branches"},{"label":"过去式","form":"branched"},{"label":"过去分词","form":"branched"},{"label":"现在分词","form":"branching"},{"label":"形容词（有分枝的）","form":"branched"}],"derivatives":[{"word":"branching","pos":"n./adj.","zh":"分枝；分叉的"},{"word":"branched","pos":"adj.","zh":"有分枝的"},{"word":"branchlet","pos":"n.","zh":"小枝"},{"word":"branchy","pos":"adj.","zh":"多枝的"},{"word":"disbranch","pos":"v.","zh":"剪除枝条（少用）"}],"senses":[{"no":"01","title":"Tree limb","titleCN":"树枝","definition":"a woody limb growing from the trunk or from another branch of a tree","definitionCN":"从树干或另一枝条长出的木质侧枝","example":"A heavy branch broke under the weight of the snow.","exampleCN":"一根粗枝在积雪的重压下断裂。","why":"This is the concrete plant sense: a side limb that divides from the main axis.","whyCN":"这是具体的植物义：从主轴分出的侧枝。"},{"no":"02","title":"Organizational division","titleCN":"组织分支","definition":"a division of a company, government or other organization, often at a lower level","definitionCN":"公司、政府或其他组织中较低层级的分支","example":"The bank opened a new branch in the northern district.","exampleCN":"这家银行在北部城区开了一家新分行。","why":"An organization is drawn as a tree: the head office is the trunk, local units are branches.","whyCN":"组织被画成一棵树：总部是主干，地方单位是枝条。"},{"no":"03","title":"Field of knowledge","titleCN":"学科分支","definition":"a subdivision of a subject or area of study","definitionCN":"学科或研究领域中的细分部分","example":"Computational linguistics is a fast-growing branch of the field.","exampleCN":"计算语言学是该领域发展迅速的一个分支。","why":"A subject is treated as a limb of a larger tree of learning, so a subdivision becomes a branch.","whyCN":"学科被看作知识大树上的一根枝条，因此细分领域就成了分支。"},{"no":"04","title":"Local office","titleCN":"地方分支机构","definition":"a local office or shop belonging to a larger organization","definitionCN":"属于较大组织的地方办事处或店铺","example":"She paid the bill at the nearest branch.","exampleCN":"她在最近的分行付了账。","why":"The organizational sense is localized: one branch is one physical site of the larger tree.","whyCN":"组织义被具体化：一个分支就是整棵大树上的一处实体节点。"},{"no":"05","title":"Computing branch","titleCN":"计算机分支","definition":"a separate line of development in a version-control system, or a path in a program's control flow","definitionCN":"版本控制系统中独立的发展线，或程序控制流中的一条路径","example":"The team kept the fix on a separate branch until testing finished.","exampleCN":"团队把修复放在单独的分支上，直到测试完成。","why":"Version history is visualized as a tree, so a divergent line of commits is naturally a branch.","whyCN":"版本历史被可视化为树，因此分出去的一条提交线自然叫分支。"},{"no":"06","title":"Language-family branch","titleCN":"语系分支","definition":"a subgroup of related languages within a larger family","definitionCN":"较大语系内部的一组相关语言","example":"The Romance branch includes French, Spanish and Italian.","exampleCN":"罗曼语支包括法语、西班牙语和意大利语。","why":"Historical linguistics uses the family-tree model, where languages split into branches.","whyCN":"历史语言学采用家族树模型，语言在其中分成各支。"},{"no":"07","title":"Government branch","titleCN":"政府分支","definition":"one of the separate powers or divisions of a government","definitionCN":"政府中相互分离的权力或部门之一","example":"The judicial branch reviews whether the law is constitutional.","exampleCN":"司法分支审查该法律是否符合宪法。","why":"The state is imagined as a body with separate limbs, each with its own function.","whyCN":"国家被想象成一个有分离肢体的身体，每一支各有功能。"},{"no":"08","title":"River branch","titleCN":"河流支流","definition":"a smaller channel that leaves a main river or a channel in a delta","definitionCN":"离开主河道的小水道，或三角洲中的分汊","example":"The river branch carries silt into the marsh.","exampleCN":"这条支流把泥沙带进沼泽。","why":"A channel that leaves the main stream repeats the tree split on a landscape scale.","whyCN":"离开主河道的水道在地貌尺度上重复了树的分叉。"},{"no":"09","title":"Divide into parts","titleCN":"分叉；分成几部分","definition":"to divide into two or more parts, or to follow a side path","definitionCN":"分成两部分或更多部分；走向侧路","example":"The road branches just beyond the bridge.","exampleCN":"这条路在桥过去一点的地方分岔。","why":"The verb turns the noun into an event: the single line becomes two or more lines.","whyCN":"动词把名词变成事件：一条线变成两条或多条线。"}],"etymology":{"intro":{"en":"The word entered English through French, and the ultimate origin of the Latin noun is disputed. Its many senses all rest on one image, a side limb.","cn":"该词经法语进入英语，拉丁名词的最终来源存疑，高卢语说法常见但未被确证。"},"items":[{"era":"LATE LATIN","en":"Late Latin branca meant 'paw, claw'. The botanical sense 'branch' is a later development, probably by the image of a limb extending from a body.","cn":"晚期拉丁语 branca 意为「爪子、脚掌」。植物义「枝条」是后来发展出来的，可能来自从身体伸出的肢体这一意象。"},{"era":"OLD FRENCH (12th c.)","en":"Old French branche meant a branch of a tree and also a branch of a family. English borrowed it in the thirteenth century.","cn":"古法语 branche 指树枝，也指家族分支。英语在十三世纪借入。"},{"era":"ORIGIN","en":"The ultimate origin of branca is uncertain. A Gaulish source is often suggested, but no secure etymology has been established.","cn":"branca 的最终来源不确定。常有人提出高卢语来源，但没有公认可靠的词源。"},{"era":"MIDDLE AND EARLY MODERN ENGLISH","en":"The word extended from trees to family lines, fields of knowledge, organizations and rivers. The organizational tree made branch a natural term for an office.","cn":"该词从树木扩展到家族血脉、知识领域、组织与河流。组织树的模型使 branch 自然成为分支机构的说法。"},{"era":"ENGLISH (19th-20th c.)","en":"Railway branch lines appear in the nineteenth century. Computing added version-control branches in the late twentieth.","cn":"铁路支线出现在十九世纪。计算机在二十世纪后期增加了版本控制分支义。"},{"era":"MODERN ENGLISH","en":"The verb branch off and branch out are now more common than the literal verb branch.","cn":"动词短语 branch off 与 branch out 现在比字面的 branch 更常用。"}]},"similar":{"note":{"en":"The first group is close in sound or spelling; the second group shares the plant or division image but differs in size or scope.","cn":"第一组在读音或拼写上接近；第二组共享植物或分割意象，但大小或范围不同。"},"groups":[{"heading":"SOUND-ALIKE","entries":[{"word":"brunch","ipa":"/brʌntʃ/","tag":"near sound, different word","definition":"a late morning meal combining breakfast and lunch; the vowel and the meaning are both different.","definitionCN":"早午餐。元音与意思都不同。"},{"word":"bench","ipa":"/bentʃ/","tag":"near sound, different word","definition":"a long seat, from Old English benc; it has no relation to trees.","definitionCN":"长凳。来自古英语 benc，与树木无关。"},{"word":"brand","ipa":"/brænd/","tag":"near spelling, different word","definition":"a mark burned or printed on goods, from Old English brand 'firebrand'.","definitionCN":"品牌；烙印。来自古英语 brand「火把」，与枝条无关。"}]},{"heading":"NEAR-MEANING","entries":[{"word":"bough","ipa":"/baʊ/","tag":"large main branch","definition":"a large main branch growing directly from the trunk; every bough is a branch, but a small twig is not a bough.","definitionCN":"大树枝。直接从树干长出的大枝；所有大枝都是枝条，但小细枝不算。"},{"word":"limb","ipa":"/lɪm/","tag":"general arm-like part","definition":"a large arm-like part of a tree or body; it stresses the projecting shape rather than the division.","definitionCN":"肢；大枝。树或身体上伸出的粗大部位，强调外伸形状而非分叉关系。"},{"word":"twig","ipa":"/twɪɡ/","tag":"smallest shoot","definition":"the smallest woody shoot at the end of a branch; it is the tip, not the supporting limb.","definitionCN":"细枝；小枝。枝条末端最细的木质枝，是末梢而不是承重枝。"},{"word":"division","ipa":"/dɪˈvɪʒn/","tag":"organizational sense","definition":"a large unit within an organization; it overlaps with branch in business but carries no plant image.","definitionCN":"部门；分部。组织内的大单位，在商业语境与 branch 重叠，但不带植物意象。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The word came through Old French branche from Late Latin branca 'paw, claw'.","cn":"这个词经古法语 branche 来自晚期拉丁语 branca「爪子、脚掌」。"},{"en":"The family runs branched, branching, branchlet and branchy.","cn":"同族词包括 branched、branching、branchlet 与 branchy。"},{"en":"Phrasal verbs mark the two directions: branch off and branch out.","cn":"短语动词标出两个方向：分岔与扩展。"},{"en":"Organizational collocations: branch office, branch manager, executive branch.","cn":"组织搭配：分公司、分公司经理、行政部门。"},{"en":"The computing sense is tied to version control and control flow.","cn":"计算机义与版本控制、控制流绑定。"}],"abstract":[{"en":"Picture a road that splits at a stone marker, each half going its own way.","cn":"想象一条路在石标处分成两半，各自走向不同方向。"},{"en":"Picture a family tree drawn with names at the tips of the limbs.","cn":"想象一棵家族树，名字写在枝条末端。"},{"en":"Picture a river delta where one channel becomes five.","cn":"想象一片河流三角洲，一条水道分成五条。"}]},"examples":[{"en":"The wind snapped a branch from the old apple tree.","cn":"风从老苹果树上折断了一根枝条。"},{"en":"The company opened its first overseas branch last year.","cn":"公司去年开设了第一家海外分公司。"},{"en":"The trail branches at the ridge and rejoins the road below.","cn":"小径在山脊处分岔，然后在下方与公路汇合。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「不让吃」——树上分出去的枝子，果子长在枝上 → 枝条；组织分出去 → 分支","word":"branch"},"root":"晚期拉丁语 branca「爪子、脚掌」，经古法语 branche 于十三世纪进入英语。branca 的最终来源不确定，高卢语说法常见但未确证。","sensesIntro":{"en":"Nine senses all rest on one geometry: a line leaves a main axis and continues on its own. Trees, families, subjects, organizations, governments, rivers and software histories are all drawn as such trees, and the verb makes the split itself an event.","cn":"九个义项都建立在同一个几何关系上：一条线离开主轴，自己继续延伸。树木、家族、学科、组织、政府、河流与软件历史都被画成这样的树，动词则把分叉本身变成事件。"},"semanticMap":{"core":{"en":"CORE IMAGE: a main axis splitting into side paths that keep growing outward.","cn":"核心意象：一条主轴分成若干继续向外生长的侧路。"},"chain":["SIDE LIMB","SMALLER UNIT","SUBJECT AREA","LOCAL SITE","SEPARATE CODE LINE","SPLIT INTO PARTS"],"branches":[{"senses":"01 · 09","en":"LIMB AND SPLIT: the noun names the result, the verb names the event.","cn":"枝与分：名词命名结果，动词命名事件。"},{"senses":"02 · 04 · 07","en":"ORGANIZATION: company, local office and government are levels of one tree.","cn":"组织：公司、地方办事处与政府是一棵树上的不同层级。"},{"senses":"03 · 06","en":"KNOWLEDGE AND LANGUAGE: subjects and language families both branch by descent.","cn":"知识与语言：学科与语系都按谱系分枝。"},{"senses":"05","en":"SOFTWARE HISTORY: a divergent line of commits is drawn as a branch.","cn":"软件历史：分出去的提交线被画成分支。"},{"senses":"08","en":"RIVER: a channel leaving the main stream repeats the same split.","cn":"河流：离开主河道的水道重复同一分叉。"}]},"affixes":{"intro":{"en":"Branch is a French-derived word whose family is mostly English; the Latin base branca is short and semantically distant, so the affix section marks that gap.","cn":"branch 是法语来源词，其词族主要是英语构造；拉丁基础词 branca 简短且语义距离远，因此词缀部分特别标明这一落差。"},"latinIntro":{"en":"Late Latin branca 'paw' is the base, Old French branche is the transmitting form, and English built branched, branching, branchlet and branchy on the borrowed noun.","cn":"晚期拉丁语 branca「爪子」是基础，古法语 branche 是传递形式，英语在借入的名词上构造了 branched、branching、branchlet 与 branchy。"},"latinEntries":[{"word":"branca","structure":"branca, brancae (f., first declension, Late Latin)","meaning":"paw, claw","meaningCN":"爪子；脚掌"},{"word":"branche","structure":"branche (Old French noun)","meaning":"branch of a tree; family line","meaningCN":"树枝；家族分支"},{"word":"ramus","structure":"ramus, rami (m., second declension)","meaning":"branch of a tree","meaningCN":"树枝（拉丁对应词，非来源）"}],"items":[{"word":"branch","structure":"branca via Old French branche","meaning":"a side limb; a division","meaningCN":"枝条；分支","example":"The branch bends under the fruit.","exampleCN":"枝条因果实而弯下。"},{"word":"branches","structure":"branch + -es (plural)","meaning":"more than one branch","meaningCN":"多个枝条或分支","example":"The tree has three main branches.","exampleCN":"这棵树有三条主枝。"},{"word":"branched","structure":"branch + -ed (having)","meaning":"having branches","meaningCN":"有分枝的","example":"The coral has a branched shape.","exampleCN":"这块珊瑚呈分枝状。"},{"word":"branching","structure":"branch + -ing (action or state)","meaning":"the process of dividing into branches","meaningCN":"分枝；分叉","example":"Branching begins at the second node.","exampleCN":"分枝从第二个节点开始。"},{"word":"branchlet","structure":"branch + -let (small)","meaning":"a small branch","meaningCN":"小枝","example":"A branchlet bears the newest leaves.","exampleCN":"小枝长着最新的叶片。"},{"word":"branchy","structure":"branch + -y (full of)","meaning":"having many branches","meaningCN":"多枝的","example":"The branchy shrub blocks the path.","exampleCN":"这丛多枝灌木挡住了小路。"},{"word":"branch office","structure":"branch + office","meaning":"a local office of a larger organization","meaningCN":"分公司；分支机构","example":"The branch office handles local accounts.","exampleCN":"分公司处理本地客户。"},{"word":"branch line","structure":"branch + line","meaning":"a secondary railway or cable line","meaningCN":"支线","example":"A branch line serves the village.","exampleCN":"一条支线服务这个村庄。"},{"word":"branch out","structure":"branch + out","meaning":"to extend into new activities","meaningCN":"扩展；开辟新领域","example":"The firm branched out into software.","exampleCN":"这家公司扩展到软件领域。"}]}},{"word":"branching","ipa_uk":"/ˈbrɑːntʃɪŋ/","ipa_us":"/ˈbræntʃɪŋ/","definition_zh":"分枝；分叉；分支结构；分流的","definition_en":"the process or pattern of dividing into branches; also used for a structure or decision that splits into alternative paths","core_image":"一条水流在平缓的三角洲上反复分成两条，再分成更多条","scene":"水道在三角洲上不断分叉，最后散成许多细流汇入海。 The river keeps branching across the delta until it frays into many small channels that reach the sea.","sceneCN":"这里该词指「河道不断分叉的过程」（第 7 个义项：河流分成多条水道）；句意为这条河在三角洲上持续分叉，最后散成许多细流汇入大海。","pos":[{"tag":"n.","zh":"分枝；分叉（过程）"},{"tag":"n.","zh":"分枝结构；分枝格局"},{"tag":"n.","zh":"（计算机）分支（控制流）"},{"tag":"n.","zh":"（语言学）分支结构"},{"tag":"n.","zh":"（生物学）分枝生长；分枝演化"},{"tag":"n.","zh":"（决策）分支；分支选择"},{"tag":"adj.","zh":"有分枝的；分叉的"}],"collocations":[{"phrase":"branching pattern","zh":"分枝格局"},{"phrase":"branching structure","zh":"分枝结构"},{"phrase":"branching process","zh":"分枝过程"},{"phrase":"branching factor","zh":"分支因子"},{"phrase":"branching decision","zh":"分支决策"},{"phrase":"branching river","zh":"分汊河流"}],"forms":[{"label":"复数（多种分枝过程）","form":"branchings"},{"label":"动词（分叉）","form":"branch"},{"label":"过去式","form":"branched"},{"label":"形容词（有分枝的）","form":"branched"},{"label":"名词（小枝）","form":"branchlet"}],"derivatives":[{"word":"branch","pos":"n./v.","zh":"枝条；分支；分叉"},{"word":"branched","pos":"adj.","zh":"有分枝的"},{"word":"branchlet","pos":"n.","zh":"小枝"},{"word":"branchy","pos":"adj.","zh":"多枝的"},{"word":"bifurcation","pos":"n.","zh":"二分叉；分叉点"}],"senses":[{"no":"01","title":"Process of dividing","titleCN":"分枝过程","definition":"the process by which a single axis divides into two or more branches","definitionCN":"单一轴分成两条或多条枝的过程","example":"Branching begins at the node where the first lateral shoot appears.","exampleCN":"分枝从第一个侧芽出现的节开始。","why":"This is the core event sense: a line becomes more than one line.","whyCN":"这是核心事件义：一条线变成不止一条线。"},{"no":"02","title":"Branching pattern","titleCN":"分枝格局","definition":"the spatial arrangement produced by repeated division, especially in plants or corals","definitionCN":"反复分叉所形成的空间格局，尤见于植物或珊瑚","example":"The coral's branching pattern follows the direction of the current.","exampleCN":"这块珊瑚的分枝格局顺着水流方向展开。","why":"The noun shifts from the event to the resulting shape, which can be measured and compared.","whyCN":"名词从事件转到结果形状，而形状可以被测量与比较。"},{"no":"03","title":"Computing control flow","titleCN":"计算机控制流分支","definition":"the selection of different paths through a program depending on a condition","definitionCN":"程序依据条件选择不同执行路径","example":"Too much branching makes the code hard to test.","exampleCN":"分支过多会让代码难以测试。","why":"A program is drawn as a flow chart whose paths split at decisions, so the split is called branching.","whyCN":"程序被画成流程图，路径在判断处分开，因此这种分开叫分支。"},{"no":"04","title":"Linguistic branching","titleCN":"语言学分支结构","definition":"a tree structure in which one node dominates two or more subordinate nodes","definitionCN":"一个节点统辖两个或更多从属节点的树形结构","example":"The parser draws a branching structure for the coordinated phrase.","exampleCN":"解析器为这个并列短语画出分支结构。","why":"Syntax borrows the tree image: a node with more than one child is branching.","whyCN":"句法借用树的意象：拥有不止一个子节点的节点就是分支的。"},{"no":"05","title":"Biological branching","titleCN":"生物学的分枝生长","definition":"the growth or evolutionary division of structures into branches, as in lungs, blood vessels or lineages","definitionCN":"结构长成枝状，或在演化上分成支系，如肺、血管或谱系","example":"Branching morphogenesis builds the tree of ducts in the lung.","exampleCN":"分枝形态发生在肺里构建出管道树。","why":"Developmental biology uses the same geometry for organs that repeatedly split.","whyCN":"发育生物学对反复分叉的器官使用同一几何描述。"},{"no":"06","title":"Decision branching","titleCN":"决策分支","definition":"a point in a plan or decision tree where alternative choices lead to different outcomes","definitionCN":"计划或决策树中不同选择通向不同结果的分点","example":"Each branching in the plan adds a possible failure path.","exampleCN":"计划中的每个分支都增加一条可能的失败路径。","why":"Management borrows the tree: a decision is a node, and its options are branches.","whyCN":"管理学借用树的模型：一个决策是节点，各选项是枝条。"},{"no":"07","title":"River branching","titleCN":"河流分汊","definition":"the division of a river into multiple channels, especially across a delta","definitionCN":"河流分成多条水道，尤指在三角洲上","example":"River branching creates the maze of channels in the delta.","exampleCN":"河流分汊造出三角洲上迷宫般的水道。","why":"Water finding several routes repeats the same split, now on a landscape scale.","whyCN":"水寻找多条路线，重复了同一种分裂，只是尺度变成地貌。"},{"no":"08","title":"Having branches","titleCN":"有分枝的","definition":"used as an adjective to describe something that divides into branches","definitionCN":"作形容词，描述分成枝条的事物","example":"The branching fern fills the shaded corner of the garden.","exampleCN":"这株分枝蕨占满花园的阴凉角落。","why":"The participle form describes the result rather than the process.","whyCN":"分词形式描述结果，而不是过程。"}],"etymology":{"intro":{"en":"Branching is an English derivative of branch; its technical senses arose in the nineteenth and twentieth centuries, and their dates are approximate.","cn":"该词为 branch 的英语派生，技术义在十九至二十世纪出现，具体年代为大致估计。"},"items":[{"era":"OLD FRENCH AND MIDDLE ENGLISH","en":"The base branch came through Old French branche from Late Latin branca 'paw, claw'. The English suffix -ing forms nouns of action or result.","cn":"基础词 branch 经古法语 branche 来自晚期拉丁语 branca「爪子、脚掌」。英语后缀 -ing 构成动作或结果名词。"},{"era":"ENGLISH (14th-16th c.)","en":"Early branching named the act of putting out branches. The noun and the participial adjective developed side by side.","cn":"早期的 branching 指长出枝条的动作。名词与分词形容词并行发展。"},{"era":"BIOLOGY (19th c.)","en":"Botany and anatomy adopted branching for repeated division of stems, vessels and ducts, and the term became a standard descriptive label.","cn":"植物学与解剖学采用 branching 描述茎、血管与导管的反复分叉，该词成为标准描述标签。"},{"era":"LINGUISTICS AND COMPUTING (20th c.)","en":"Generative grammar and computer science both use tree diagrams, so branching acquired precise structural senses in both fields.","cn":"生成语法与计算机科学都使用树形图，因此 branching 在这两个领域获得精确的结构义。"},{"era":"MODERN ENGLISH","en":"The word now appears mostly in technical writing; everyday speech prefers forking, splitting or dividing.","cn":"这个词现在多出现在技术写作中；日常口语更常说 forking、splitting 或 dividing。"}]},"similar":{"note":{"en":"The first group looks or sounds like branching without sharing its plant source; the second group describes the same split from different angles.","cn":"第一组在形音上像 branching，但不共享植物来源；第二组从不同角度描述同一种分裂。"},"groups":[{"heading":"SOUND-ALIKE","entries":[{"word":"branding","ipa":"/ˈbrændɪŋ/","tag":"near sound, different root","definition":"the act of marking goods with a brand, from Old English brand 'firebrand'; it has no plant sense.","definitionCN":"品牌塑造；打烙印。来自古英语 brand「火把」，没有植物义。"},{"word":"blanching","ipa":"/ˈblɑːntʃɪŋ/","tag":"near sound, different root","definition":"briefly boiling food or whitening a plant, from French blanchir 'to whiten'.","definitionCN":"焯水；使变白。来自法语 blanchir「使变白」。"},{"word":"bunching","ipa":"/ˈbʌntʃɪŋ/","tag":"near sound, different root","definition":"gathering things into a cluster, from bunch; the image is collecting, not dividing.","definitionCN":"成束；聚拢。来自 bunch，意象是收集，不是分裂。"}]},{"heading":"NEAR-MEANING","entries":[{"word":"forking","ipa":"/ˈfɔːkɪŋ/","tag":"everyday split word","definition":"dividing into two or more paths; it is the everyday verb for what branching describes technically.","definitionCN":"分叉。分成两条或多条路径，是 branching 技术描述对应的日常动词。"},{"word":"bifurcation","ipa":"/ˌbaɪfəˈkeɪʃn/","tag":"two-way split","definition":"a division into exactly two branches, especially in science; branching allows any number of branches.","definitionCN":"二分叉。尤在科学语境指恰好分成两支；branching 可分任意多条。"},{"word":"ramification","ipa":"/ˌræmɪfɪˈkeɪʃn/","tag":"branching consequence","definition":"a branching structure or its consequences; the word often stresses the resulting complications rather than the shape.","definitionCN":"分支；衍生后果。常强调由此产生的复杂结果，而非形状本身。"},{"word":"division","ipa":"/dɪˈvɪʒn/","tag":"general split","definition":"the general act of dividing; it carries no tree image and no technical restriction.","definitionCN":"分割；划分。一般的分开动作，不带树的意象，也没有技术限制。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The base branch came from French, and the English suffix -ing makes an action or result noun.","cn":"基础词 branch 来自法语，英语后缀 -ing 构成动作或结果名词。"},{"en":"The family runs branch, branched, branching, branchlet and branchy.","cn":"同族词包括 branch、branched、branching、branchlet 与 branchy。"},{"en":"Technical collocations: branching pattern, branching factor, branching process.","cn":"技术搭配：分枝格局、分支因子、分枝过程。"},{"en":"Computing and grammar both draw trees, so both use branching for a node with several children.","cn":"计算机与语法都画树，因此都用 branching 指拥有多个子节点的节点。"},{"en":"Rivers, corals, lungs and family trees all provide real examples of the same shape.","cn":"河流、珊瑚、肺与家族树都提供同一形状的真实例子。"}],"abstract":[{"en":"Picture a path that splits at every stone it meets, doubling each time.","cn":"想象一条路每遇到一块石头就分一次，每次翻倍。"},{"en":"Picture a bare tree seen from above, every fork visible as a Y.","cn":"想象从上方看一棵光秃的树，每个分叉都呈 Y 形。"},{"en":"Picture a conversation in which every answer opens two new questions.","cn":"想象一场对话，每个回答都打开两个新问题。"}]},"examples":[{"en":"The branching of the river is what creates the islands in the delta.","cn":"河流的分汊正是三角洲中岛屿形成的原因。"},{"en":"A branching process can model how one rumor becomes many.","cn":"分枝过程可以模拟一个传闻如何变成许多个。"},{"en":"The fern's branching fronds fill the whole shaded bed.","cn":"这株蕨的分枝叶片占满整片阴凉花坛。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「不让吃 → 分枝」——一条线不断分成几条 → 分叉、分支结构","word":"branching"},"root":"由 branch 加英语后缀 -ing 构成；branch 经古法语 branche 来自晚期拉丁语 branca「爪子、脚掌」，该拉丁词最终来源不确定。技术义出现于十九至二十世纪。","sensesIntro":{"en":"Eight senses share one geometry but differ in what is being split: a plant axis, a measured pattern, a program path, a syntactic node, a developing organ, a decision, a river and finally a descriptive adjective. The event and the resulting shape alternate throughout.","cn":"八个义项共享同一几何关系，只是被分裂的对象不同：植物轴、可测格局、程序路径、句法节点、发育器官、决策、河流，最后是描述性形容词。事件与结果形状在全程交替出现。"},"semanticMap":{"core":{"en":"CORE IMAGE: one line becoming two, then two becoming four.","cn":"核心意象：一条线变成两条，两条再变成四条。"},"chain":["ONE AXIS","FIRST SPLIT","REPEATED SPLIT","MEASURABLE PATTERN","PROGRAM PATH","RIVER CHANNEL"],"branches":[{"senses":"01 · 02","en":"EVENT AND SHAPE: the split itself and the pattern it leaves.","cn":"事件与形状：分裂本身，以及它留下的格局。"},{"senses":"03 · 06","en":"CONTROLLED SPLITS: programs and plans branch at conditions.","cn":"受控分裂：程序与计划在条件处分叉。"},{"senses":"04 · 05","en":"STRUCTURAL BIOLOGY AND LANGUAGE: nodes and organs both form trees.","cn":"结构与语言：节点与器官都形成树。"},{"senses":"07","en":"LANDSCAPE: a river repeats the split at geographic scale.","cn":"地貌：河流在地理尺度上重复同一种分裂。"},{"senses":"08","en":"ADJECTIVAL RESULT: the participle describes the finished shape.","cn":"形容词结果：分词描述已完成的形状。"}]},"affixes":{"intro":{"en":"Branching is a transparent English derivative, so the affix section reads the borrowed base and the native suffix separately.","cn":"branching 是透明的英语派生词，因此词缀部分把借入的基础词与本土后缀分开来读。"},"latinIntro":{"en":"Late Latin branca and Old French branche supply the base; the suffix -ing is English and marks an action, result or description.","cn":"晚期拉丁语 branca 与古法语 branche 提供基础；后缀 -ing 是英语成分，标记动作、结果或描述。"},"latinEntries":[{"word":"branca","structure":"branca, brancae (f., first declension, Late Latin)","meaning":"paw, claw","meaningCN":"爪子；脚掌"},{"word":"branche","structure":"branche (Old French noun)","meaning":"branch; family line","meaningCN":"树枝；家族分支"},{"word":"ramus","structure":"ramus, rami (m., second declension)","meaning":"branch of a tree","meaningCN":"树枝（拉丁对应词，非来源）"}],"items":[{"word":"branch","structure":"branca via Old French branche","meaning":"a side limb; a division","meaningCN":"枝条；分支","example":"The branch bends under the fruit.","exampleCN":"枝条因果实而弯。"},{"word":"branching","structure":"branch + -ing (action or result)","meaning":"the act or pattern of dividing into branches","meaningCN":"分叉；分枝格局","example":"Branching starts at the second node.","exampleCN":"分枝从第二个节点开始。"},{"word":"branched","structure":"branch + -ed (having)","meaning":"having branches","meaningCN":"有分枝的","example":"The coral has a branched skeleton.","exampleCN":"珊瑚有分枝的骨架。"},{"word":"branchlet","structure":"branch + -let (small)","meaning":"a small branch","meaningCN":"小枝","example":"A branchlet holds the newest leaves.","exampleCN":"小枝托着最新的叶片。"},{"word":"branchy","structure":"branch + -y (full of)","meaning":"having many branches","meaningCN":"多枝的","example":"The branchy hedge blocks the view.","exampleCN":"多枝的树篱挡住视线。"},{"word":"bifurcation","structure":"bi- + furca + -ation (Latin-derived)","meaning":"a split into two","meaningCN":"二分叉","example":"Bifurcation occurs where the pipe divides.","exampleCN":"管道分开处出现二分叉。"},{"word":"ramification","structure":"ramus + -ficare + -ation (Latin-derived)","meaning":"a branching; a consequence","meaningCN":"分支；衍生后果","example":"The ramification of the rule surprised planners.","exampleCN":"这条规则的衍生后果让规划者意外。"},{"word":"forking","structure":"fork + -ing (English)","meaning":"the everyday act of splitting","meaningCN":"日常的分叉动作","example":"Forking is the plain word for the same shape.","exampleCN":"分叉是同一形状的日常说法。"},{"word":"division","structure":"dividere + -ion (Latin-derived)","meaning":"the general act of dividing","meaningCN":"分割；划分","example":"Cell division is not the same as branching.","exampleCN":"细胞分裂与分枝不是一回事。"}]}},{"word":"bark","ipa_uk":"/bɑːk/","ipa_us":"/bɑːrk/","definition_zh":"树皮；狗吠；厉声说；擦破（皮肤）；三桅帆船","definition_en":"the outer protective layer of a tree; the sharp cry of a dog; to speak or shout sharply; to scrape skin; also a sailing ship","core_image":"老树表面一层粗糙、开裂、可以整片剥下的外壳","scene":"老松树的树皮裂成一块块不规则的鳞片，缝隙里渗出了树脂。 The old pine's bark breaks into irregular scaly plates, with resin seeping from the cracks.","sceneCN":"这里该词指「树木最外层的树皮」（第 1 个义项：树干外面的保护层）；句意为老松树的树皮裂成不规则鳞片，缝隙里有树脂渗出。","pos":[{"tag":"n.","zh":"树皮"},{"tag":"n.","zh":"树皮材料（用于鞣革、覆盖物等）"},{"tag":"n.","zh":"狗吠声；吠叫"},{"tag":"v.","zh":"（狗）吠叫"},{"tag":"v.","zh":"厉声说；吼叫"},{"tag":"v.","zh":"擦破（皮肤）"},{"tag":"n.","zh":"（咳嗽）像狗吠的声音"},{"tag":"n.","zh":"三桅帆船（旧式帆船）"},{"tag":"v.","zh":"剥去树皮"}],"collocations":[{"phrase":"tree bark","zh":"树皮"},{"phrase":"bark at","zh":"对着……吠叫"},{"phrase":"bark out an order","zh":"厉声下达命令"},{"phrase":"bark one's shin","zh":"擦破小腿"},{"phrase":"bark chips","zh":"树皮碎片；树皮覆盖物"},{"phrase":"cork bark","zh":"软木树皮"}],"forms":[{"label":"复数（树皮种类；吠声）","form":"barks"},{"label":"三单（吠叫；厉声说）","form":"barks"},{"label":"过去式","form":"barked"},{"label":"过去分词","form":"barked"},{"label":"现在分词","form":"barking"},{"label":"形容词（有树皮的）","form":"barked"}],"derivatives":[{"word":"barking","pos":"n./adj.","zh":"吠叫；吠叫的"},{"word":"barker","pos":"n.","zh":"吠叫的动物；招揽顾客的人"},{"word":"barked","pos":"adj.","zh":"剥去树皮的"},{"word":"de-bark","pos":"v.","zh":"剥皮；去树皮"},{"word":"barque","pos":"n.","zh":"三桅帆船（同源异体）"}],"senses":[{"no":"01","title":"Tree's outer layer","titleCN":"树皮","definition":"the outer protective layer of a tree trunk or branch","definitionCN":"树干或枝条外面的保护层","example":"The bark of the cork oak is harvested every nine years.","exampleCN":"软木橡树的树皮每九年采剥一次。","why":"This is the core material sense: a protective skin around the woody body.","whyCN":"这是核心材料义：包住木质主体的一层保护皮。"},{"no":"02","title":"Bark as a material","titleCN":"树皮材料","definition":"the bark of certain trees used for tanning, mulching, medicine or craft","definitionCN":"某些树的树皮，用于鞣革、覆盖、药用或手工艺","example":"Gardeners use bark chips to suppress weeds.","exampleCN":"园丁用树皮碎片抑制杂草。","why":"Once stripped, the protective layer becomes a raw material with its own uses.","whyCN":"剥下之后，这层保护物变成有独立用途的原料。"},{"no":"03","title":"Dog's sharp cry","titleCN":"狗吠","definition":"the short, sharp cry of a dog or similar animal","definitionCN":"狗或类似动物短促尖锐的叫声","example":"The dog barked at the postman and then wagged its tail.","exampleCN":"狗对着邮差吠叫，随后又摇起了尾巴。","why":"This is a separate imitative word, not a development of the tree sense.","whyCN":"这是一个独立的拟声词，并非树皮义的发展。"},{"no":"04","title":"A person's sharp shout","titleCN":"人的厉声喊叫","definition":"a loud, abrupt shout, especially an order","definitionCN":"响亮而突然的喊叫，尤指命令","example":"The sergeant barked an order across the yard.","exampleCN":"中士隔着院子厉声下达命令。","why":"Human speech is compared to a dog's cry: short, loud and without softening.","whyCN":"人的说话被比作狗吠：短促、响亮、毫不缓和。"},{"no":"05","title":"Speak sharply","titleCN":"厉声说话","definition":"to say something in a sharp, angry or commanding way","definitionCN":"以尖锐、生气或命令的方式说话","example":"She barked at him to shut the door.","exampleCN":"她厉声叫他关门。","why":"The verb keeps the animal image but applies it to human tone.","whyCN":"动词保留动物意象，却用于人的语气。"},{"no":"06","title":"Scrape the skin","titleCN":"擦破皮肤","definition":"to scrape or bruise the skin by hitting a hard edge","definitionCN":"撞到硬边而擦伤或碰伤皮肤","example":"He barked his shin on the edge of the low wall.","exampleCN":"他的小腿在矮墙边缘擦破了。","why":"The image is a layer of skin stripped off, like bark peeled from a tree.","whyCN":"意象是一层皮被蹭掉，像树皮从树上被剥下。"},{"no":"07","title":"Cough like a bark","titleCN":"像狗吠的咳嗽声","definition":"a harsh, loud cough that sounds like a dog barking, especially in croup","definitionCN":"刺耳响亮、像狗吠一样的咳嗽声，尤见于哮吼","example":"The child's bark-like cough worried the doctor.","exampleCN":"孩子那种像狗吠的咳嗽让医生担心。","why":"The sound is again matched to the animal cry, now as a medical description.","whyCN":"声音再次被比作动物叫声，这次用作医学描述。"},{"no":"08","title":"Sailing ship","titleCN":"三桅帆船","definition":"a sailing ship with three masts, especially one with the foremast and mainmast square-rigged","definitionCN":"有三根桅杆的帆船，尤指前桅与主桅为横帆的船","example":"The old bark carried timber along the coast.","exampleCN":"那艘旧三桅帆船沿着海岸运送木材。","why":"This sense comes from a different word, French barque, and only shares the English spelling.","whyCN":"这一义来自另一个法语词，只是与树皮、吠叫共享英语拼写。"},{"no":"09","title":"Strip bark","titleCN":"剥去树皮","definition":"to remove the bark from a tree or a log","definitionCN":"把树或原木的皮剥掉","example":"Workers bark the logs before the timber is shipped.","exampleCN":"工人先把原木剥皮，再装运木材。","why":"The verb turns the material noun into an action performed on the trunk.","whyCN":"动词把材料名词变成施加在树干上的动作。"}],"etymology":{"intro":{"en":"Bark is three different words that share one spelling: a tree word from Old Norse, an imitative animal word from Old English, and a ship word from French. Their origins must be kept apart.","cn":"树皮词来自古诺斯语，动物词来自古英语拟声动词，帆船词来自法语；三者只是拼写相同，词源必须分开。"},"items":[{"era":"OLD NORSE (14th c.)","en":"The tree word bark is recorded in late fourteenth-century English from Old Norse bǫrkr 'tree bark', replacing the native rind in general use.","cn":"树皮义的 bark 记录于十四世纪晚期英语，来自古诺斯语 bǫrkr「树皮」，在日常用法中取代了本土词 rind。"},{"era":"OLD ENGLISH","en":"The animal word is Old English beorcan 'to bark', a verb of imitative origin. The noun bark for the cry developed from it.","cn":"动物义的词是古英语 beorcan「吠叫」，动词来源为拟声。表示叫声的名词 bark 由它发展而来。"},{"era":"PROTO-GERMANIC","en":"The tree noun is reconstructed as *barkuz; the animal verb as *berkan. The two reconstructions are separate and do not share a root.","cn":"树皮名词重构为 *barkuz；动物动词重构为 *berkan。两个重构形式彼此独立，不共享词根。"},{"era":"FRENCH AND LATIN (15th c.)","en":"The ship sense comes from French barque, probably through Italian barca, from Latin barca 'boat'. It is unrelated to the tree and animal words.","cn":"帆船义来自法语 barque，可能经意大利语 barca 上溯拉丁语 barca「小船」。它与树皮、吠叫两词无关。"},{"era":"ENGLISH (16th-19th c.)","en":"The senses 'speak sharply', 'scrape the skin' and 'bark-like cough' are later figurative extensions of the animal cry or the peeling image.","cn":"「厉声说话」「擦破皮肤」与「像狗吠的咳嗽」是后来从动物叫声或剥皮意象延伸出的比喻义。"},{"era":"MODERN ENGLISH","en":"Modern dictionaries still treat the tree word, the animal word and the ship word as separate homonyms with separate histories.","cn":"现代词典仍把树皮词、动物词与帆船词视为来源不同的同形异义词。"}]},"similar":{"note":{"en":"The first group is close in sound but belongs to other words; the second group shares either the covering image or the sharp-sound image.","cn":"第一组读音接近但属于其他词；第二组或共享覆盖意象，或共享尖锐声音意象。"},"groups":[{"heading":"SOUND-ALIKE","entries":[{"word":"bank","ipa":"/bæŋk/","tag":"near sound, different word","definition":"the side of a river or a financial institution, from Italian banca 'bench'; it has no relation to bark.","definitionCN":"河岸；银行。来自意大利语 banca「长凳」，与 bark 无关。"},{"word":"park","ipa":"/pɑːk/","tag":"near sound, different word","definition":"a public green space or to leave a vehicle, from French parc.","definitionCN":"公园；停车。来自法语 parc。"},{"word":"dark","ipa":"/dɑːk/","tag":"near sound, different word","definition":"without light, from Old English deorc; the vowel and the meaning are both different.","definitionCN":"黑暗的。来自古英语 deorc，元音与意思都不同。"}]},{"heading":"NEAR-MEANING","entries":[{"word":"rind","ipa":"/raɪnd/","tag":"tree covering","definition":"the thick outer covering of fruit or, in older use, of bacon or cheese; for trees it is now rarer than bark.","definitionCN":"外皮；果皮。旧时也指树皮，但现在用于树时比 bark 少见。"},{"word":"cortex","ipa":"/ˈkɔːteks/","tag":"technical layer","definition":"the outer layer of a plant stem in botanical anatomy; it is a technical term for a tissue layer, not the everyday covering.","definitionCN":"皮层。植物解剖中指茎的外层组织，是技术术语，不是日常说的整层树皮。"},{"word":"yelp","ipa":"/jelp/","tag":"sharp animal cry","definition":"a short high cry, especially of a dog in pain; it is sharper and higher than a normal bark.","definitionCN":"尖叫声。狗等动物短促高亢的叫声，尤因疼痛；比普通吠叫更尖更高。"},{"word":"howl","ipa":"/haʊl/","tag":"long animal cry","definition":"a long, drawn-out cry of a dog or wolf; it is sustained rather than short and sharp.","definitionCN":"长嚎。狗或狼拉长的叫声，是持续的，不是短促尖锐的。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Tree bark came from Old Norse; the dog verb came from Old English and is imitative.","cn":"树皮词来自古诺斯语；狗吠动词来自古英语，属于拟声。"},{"en":"The ship sense came through French barque from Latin barca 'boat'.","cn":"帆船义经法语 barque 上溯拉丁语 barca「小船」。"},{"en":"Fixed phrases: tree bark, bark chips, bark at, bark out an order.","cn":"固定搭配：树皮、树皮覆盖物、对……吠叫、厉声下令。"},{"en":"The idiom bark up the wrong tree means to pursue the wrong explanation.","cn":"习语 bark up the wrong tree 意为找错方向、怪错对象。"},{"en":"The three homonyms are usually listed separately in dictionaries.","cn":"这三个同形异义词在词典里通常分开列出。"}],"abstract":[{"en":"Picture a tree wearing a rough coat that can be peeled off in plates.","cn":"想象一棵树穿着一件粗糙的外套，可以整片剥下。"},{"en":"Picture one short sound crossing a quiet yard and ending at once.","cn":"想象一声短促的响动穿过安静的院子，随即结束。"},{"en":"Picture a small ship with three masts cutting through grey water.","cn":"想象一艘三桅小船划过灰色的水面。"}]},"examples":[{"en":"The bark of the yew is used in some traditional medicines.","cn":"紫杉的树皮用于某些传统药物。"},{"en":"The dog barked once and then fell silent.","cn":"狗叫了一声，随后安静下来。"},{"en":"He barked his knee on the rock while climbing down.","cn":"他下山时膝盖在岩石上擦破了。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「扒壳」——把树外面那层壳扒下来 → 树皮；狗短促一叫 → 吠","word":"bark"},"root":"三个同形异义词：树皮义来自古诺斯语 bǫrkr，重构为原始日耳曼语 *barkuz；狗吠义来自古英语拟声动词 beorcan，重构为 *berkan；帆船义经法语 barque 上溯拉丁语 barca「小船」。","sensesIntro":{"en":"Nine senses divide into three unrelated words that happen to share a spelling. The tree word gives covering, material and stripping; the animal word gives the cry, the sharp human tone, the bark-like cough; the ship word stands alone; and the scraped skin sense borrows the peeling image.","cn":"九个义项分属三个只是拼写相同的无关词。树皮词给出覆盖层、材料与剥皮；动物词给出吠叫、人的厉声与类吠咳嗽；帆船词独立；擦破皮肤义借用了剥皮的意象。"},"semanticMap":{"core":{"en":"CORE IMAGE: a rough coat around a body, and a short sharp sound leaving a mouth.","cn":"核心意象：身体外一层粗糙的外壳，以及从嘴里发出的一声短促尖锐的响动。"},"chain":["PROTECTIVE COAT","PEELED LAYER","USEFUL MATERIAL","SHORT ANIMAL CRY","SHARP HUMAN TONE","THREE-MASTED SHIP"],"branches":[{"senses":"01","en":"THE COAT: the tree's outer layer is a living cover.","cn":"这层外衣：树木最外面的一层，是活着的保护层。"},{"senses":"03 · 04 · 05","en":"ANIMAL WORD: the dog's cry becomes a human command.","cn":"动物词：狗的叫声转成人的命令。"},{"senses":"06 · 07","en":"PEELING IMAGE: scraped skin and croup cough both borrow the coat or the cry.","cn":"剥皮意象：擦伤皮肤与哮吼咳嗽分别借用外壳或叫声。"},{"senses":"08","en":"SHIP WORD: a separate borrowing that only shares spelling.","cn":"帆船词：只是拼写相同的独立借词。"},{"senses":"02 · 09","en":"MATERIAL CYCLE: once peeled, the coat becomes a product.","cn":"材料循环：剥下之后，这层外壳变成产品。"}]},"affixes":{"intro":{"en":"Bark has almost no productive affix family of its own; most related forms are English derivations or separate homonyms, which the affix section keeps distinct.","cn":"bark 本身几乎没有能产的词缀族；多数相关形式是英语派生或独立的同形异义词，词缀部分把这些分开。"},"latinIntro":{"en":"Latin cortex 'bark, outer layer' is a translation equivalent, not a source. The ship word goes back to Latin barca; the tree and animal words are Germanic.","cn":"拉丁语 cortex「树皮、外层」只是对应译词，不是来源。帆船词上溯拉丁语 barca；树皮词与动物词则是日耳曼来源。"},"latinEntries":[{"word":"barca","structure":"barca, barcae (f., first declension, Late Latin)","meaning":"small boat","meaningCN":"小船（帆船义的来源）"},{"word":"cortex","structure":"cortex, corticis (m., third declension)","meaning":"bark, outer layer","meaningCN":"树皮；外层（拉丁对应词，非来源）"},{"word":"barkuz","structure":"*barkuz (reconstructed Proto-Germanic noun)","meaning":"tree bark","meaningCN":"树皮（重构形式）"},{"word":"berkan","structure":"*berkan (reconstructed Proto-Germanic verb)","meaning":"to bark","meaningCN":"吠叫（重构形式）"}],"items":[{"word":"bark","structure":"bark (Old Norse bǫrkr for the tree; Old English beorcan for the cry)","meaning":"tree covering; a sharp cry","meaningCN":"树皮；吠叫","example":"The bark protects the living wood.","exampleCN":"树皮保护活木质。"},{"word":"barks","structure":"bark + -s (plural or third person)","meaning":"more than one bark; he or she barks","meaningCN":"多种树皮；他或它吠叫","example":"The dog barks at strangers.","exampleCN":"狗对陌生人吠叫。"},{"word":"barked","structure":"bark + -ed (past or participle)","meaning":"cried out; stripped of bark","meaningCN":"吠叫过；剥去树皮的","example":"The guard barked a warning.","exampleCN":"守卫厉声发出警告。"},{"word":"barking","structure":"bark + -ing (action)","meaning":"the act of crying out","meaningCN":"吠叫；厉声说话","example":"The barking kept the whole street awake.","exampleCN":"吠叫声让整条街都睡不着。"},{"word":"barker","structure":"bark + -er (one who)","meaning":"an animal that barks; a person who calls customers","meaningCN":"吠叫的动物；招揽顾客的人","example":"The barker stood at the fairground entrance.","exampleCN":"招揽者在游乐场入口站着。"},{"word":"barky","structure":"bark + -y (like)","meaning":"resembling bark in texture or sound","meaningCN":"像树皮的；像吠声的（少用）","example":"The barky surface of the old log was hard to grip.","exampleCN":"旧原木粗糙的表面很难抓握。"},{"word":"debark","structure":"de- + bark (remove)","meaning":"to remove bark from timber","meaningCN":"剥去树皮","example":"Machines debark the logs at the mill.","exampleCN":"机器在木材厂给原木剥皮。"},{"word":"barque","structure":"barque (French, via Italian and Latin barca)","meaning":"a three-masted sailing ship","meaningCN":"三桅帆船","example":"The barque anchored outside the harbour.","exampleCN":"那艘三桅帆船停在港外。"},{"word":"embark","structure":"em- + barca (go into a boat)","meaning":"to board a ship; to begin something","meaningCN":"上船；开始","example":"The team embarked on a long survey.","exampleCN":"团队开始了一项长期调查。"}]}},{"word":"canopy","ipa_uk":"/ˈkænəpi/","ipa_us":"/ˈkænəpi/","definition_zh":"树冠层；顶篷；带顶罩的床；降落伞伞衣","definition_en":"the upper layer of trees in a forest; a roof-like covering, as over a bed, a procession, an aircraft cockpit or a parachute","core_image":"一片森林顶部连成一张起伏的绿顶，把下面的地面遮成半阴","scene":"雨林里抬头几乎看不见天空，层层树冠把阳光筛成细碎的光斑。 In the rainforest you can barely see the sky, because the layered canopy filters the sunlight into small bright patches.","sceneCN":"这里该词指「森林上层的树冠层」（第 1 个义项：林木顶部连成的覆盖层）；句意为在雨林里几乎看不见天空，因为层层树冠把阳光筛成小块光斑。","pos":[{"tag":"n.","zh":"树冠层；林冠"},{"tag":"n.","zh":"顶篷；遮阳篷"},{"tag":"n.","zh":"（床的）顶罩；华盖"},{"tag":"n.","zh":"降落伞伞衣"},{"tag":"n.","zh":"（飞机）座舱盖"},{"tag":"n.","zh":"（仪式用的）华盖"},{"tag":"n.","zh":"比喻义：覆盖在头顶的一层（如星空）"},{"tag":"n.","zh":"（林业）林冠覆盖度"}],"collocations":[{"phrase":"forest canopy","zh":"森林林冠"},{"phrase":"canopy cover","zh":"林冠覆盖"},{"phrase":"canopy bed","zh":"带顶罩的床"},{"phrase":"parachute canopy","zh":"降落伞伞衣"},{"phrase":"cockpit canopy","zh":"座舱盖"},{"phrase":"under the canopy","zh":"在树冠下"},{"phrase":"canopy layer","zh":"林冠层"}],"forms":[{"label":"复数（多片林冠；多个顶篷）","form":"canopies"},{"label":"形容词（有顶篷的）","form":"canopied"},{"label":"相关名词（林冠覆盖）","form":"canopy cover"},{"label":"相关名词（林冠层）","form":"canopy layer"},{"label":"相关名词（树冠）","form":"crown"}],"derivatives":[{"word":"canopied","pos":"adj.","zh":"有顶篷的；被树冠覆盖的"},{"word":"canopying","pos":"n.","zh":"加顶篷；形成覆盖（少用）"},{"word":"canopyless","pos":"adj.","zh":"无顶篷的（少用）"},{"word":"crown","pos":"n.","zh":"树冠（单株树的枝叶整体）"},{"word":"awning","pos":"n.","zh":"遮阳篷"}],"senses":[{"no":"01","title":"Upper forest layer","titleCN":"森林上层的林冠","definition":"the upper layer of a forest formed by the crowns of the tallest trees","definitionCN":"由最高树木的树冠形成的森林上层","example":"The canopy closes over the trail in summer.","exampleCN":"夏天，林冠在小径上方合拢。","why":"This is the ecological sense: many crowns together form one continuous roof.","whyCN":"这是生态义：许多树冠共同形成一整片连续的顶。"},{"no":"02","title":"Roof-like covering","titleCN":"顶篷；遮阳篷","definition":"a roof-like structure that provides shade or shelter","definitionCN":"提供遮阴或遮蔽的顶状结构","example":"A striped canopy shaded the café tables.","exampleCN":"一条条纹顶篷为咖啡座的桌子遮阴。","why":"The word generalizes from trees to any man-made roof that spreads overhead.","whyCN":"这个词从树木扩展到任何在头顶铺开的人造顶。"},{"no":"03","title":"Canopy bed","titleCN":"带顶罩的床","definition":"a bed with a frame and a hanging cover over it","definitionCN":"上方有框架和悬挂顶罩的床","example":"The guest room has an old wooden canopy bed.","exampleCN":"客房有一张旧木制顶罩床。","why":"The bed keeps the old sense of a hanging cloth spread over a resting place.","whyCN":"这种床保留了旧义：一块悬挂的布铺在休息处上方。"},{"no":"04","title":"Parachute canopy","titleCN":"降落伞伞衣","definition":"the fabric part of a parachute that fills with air and slows the fall","definitionCN":"降落伞中充气并减速的织物部分","example":"The parachute canopy opened only seconds before landing.","exampleCN":"降落伞伞衣在落地前几秒才打开。","why":"The fabric is a dome held overhead, so the tree-roof image fits exactly.","whyCN":"织物是头顶撑起的穹顶，因此树冠顶篷的意象正好吻合。"},{"no":"05","title":"Aircraft canopy","titleCN":"飞机座舱盖","definition":"the transparent cover over an aircraft cockpit","definitionCN":"飞机座舱上方的透明罩","example":"The pilot released the canopy before ejecting.","exampleCN":"飞行员在弹射前抛掉了座舱盖。","why":"A transparent shell over the pilot repeats the overhead-cover shape in hard material.","whyCN":"飞行员上方的透明壳体，用硬质材料重复了头顶覆盖的形状。"},{"no":"06","title":"Ceremonial canopy","titleCN":"仪式华盖","definition":"a decorated cloth carried over important people in a procession","definitionCN":"仪式中在要人头顶撑起的装饰布篷","example":"Four attendants held the canopy above the bride.","exampleCN":"四名侍从在新娘上方撑着华盖。","why":"A cloth held over a person marks rank, the same gesture as a roof held above.","whyCN":"在人的上方撑布标记身份，与在头顶撑起顶盖是同一动作。"},{"no":"07","title":"Figurative overhead layer","titleCN":"比喻义：头顶覆盖的一层","definition":"a layer that seems to spread overhead, such as the sky or a mass of stars","definitionCN":"像在头顶铺开的一层，如天空或繁星","example":"A canopy of stars hung over the desert camp.","exampleCN":"一片星空像华盖一样悬在沙漠营地之上。","why":"The physical roof becomes a visual metaphor for anything that covers the sky.","whyCN":"实体的顶变成视觉比喻，指任何覆盖天空之物。"},{"no":"08","title":"Forestry canopy cover","titleCN":"林业的郁闭度","definition":"the proportion of ground shaded by tree crowns, used as a measure of forest density","definitionCN":"树冠遮蔽地面的比例，用作森林密度的量度","example":"Canopy cover reached eighty percent in the old-growth stand.","exampleCN":"这片原始林的林冠覆盖度达到八成。","why":"The roof is now measured as a percentage, turning the image into a forestry variable.","whyCN":"顶篷此时被量成百分比，意象变成林业变量。"}],"etymology":{"intro":{"en":"The word travelled from a mosquito net to a bed cover, then to any roof-like cover, and finally to forest layers. The Greek base is clear but its deeper origin is disputed.","cn":"希腊语基础词清楚，但其更深来源不确定；中世纪拉丁语与法语的传递环节较清楚，各专业义出现年代为大致估计。"},"items":[{"era":"GREEK","en":"The source is kōnōpeion 'mosquito net', built from kōnōps 'gnat, mosquito'. The further origin of kōnōps is uncertain; a link to kōnos 'cone' has been suggested but not established.","cn":"来源是希腊语 kōnōpeion「蚊帐」，由 kōnōps「蚊、蚋」构成。kōnōps 的更深来源不确定；有人提出与 kōnos「圆锥」有关，但未获确证。"},{"era":"LATIN","en":"Latin conopeum kept the meaning 'mosquito net, bed curtain'. The medial -p- and the later spelling with -a- reflect transmission through Medieval Latin.","cn":"拉丁语 conopeum 保留「蚊帐、床帘」的意思。中间的 -p- 与后来带 -a- 的拼写反映了中世纪拉丁语的传递。"},{"era":"MEDIEVAL LATIN AND FRENCH","en":"Medieval Latin canopeum, perhaps influenced by canopeum 'canopy', passed into Old French as conopé and then into English.","cn":"中世纪拉丁语 canopeum（可能受 canopeum「华盖」影响）传入古法语作 conopé，再进入英语。"},{"era":"ENGLISH (14th-16th c.)","en":"Early English canopy meant a hanging cloth over a bed or a throne. The covering sense then extended to processions and doorways.","cn":"早期英语 canopy 指床或宝座上方的悬挂布。覆盖义随后扩展到游行与门廊。"},{"era":"ENGLISH (17th-19th c.)","en":"The word was applied to any roof-like shelter, and in the nineteenth century to the fabric dome of a parachute.","cn":"这个词被用于任何顶状遮蔽物，十九世纪又用于降落伞的织物穹顶。"},{"era":"MODERN ENGLISH","en":"Ecology adopted canopy for the upper forest layer, aviation for the cockpit cover, and forestry for a measurable canopy cover.","cn":"生态学采用 canopy 指森林上层，航空用指座舱盖，林业则用指可测量的林冠覆盖度。"}]},"similar":{"note":{"en":"The first group is close in sound or spelling but unrelated; the second group shares the idea of an overhead cover or a tree top.","cn":"第一组在读音或拼写上接近但无关；第二组共享「头顶覆盖物」或「树顶」的意思。"},"groups":[{"heading":"SOUND-ALIKE","entries":[{"word":"canapé","ipa":"/ˈkænəpeɪ/","tag":"near sound, different word","definition":"a small piece of food served on bread or a cracker, from French canapé 'sofa'; it is unrelated to canopy.","definitionCN":"夹心小点。来自法语 canapé「沙发」，与 canopy 无关。"},{"word":"cannery","ipa":"/ˈkænəri/","tag":"near sound, different word","definition":"a factory where food is canned; it comes from can, not from canopy.","definitionCN":"罐头厂。来自 can「罐头」，不是 canopy。"},{"word":"calamity","ipa":"/kəˈlæməti/","tag":"near rhythm, different word","definition":"a disaster, from Latin calamitas; the similarity is only in the ending.","definitionCN":"灾难。来自拉丁语 calamitas，相似只在线性结尾。"}]},{"heading":"NEAR-MEANING","entries":[{"word":"crown","ipa":"/kraʊn/","tag":"single tree top","definition":"the branches and leaves of one tree; many crowns together make a canopy, but one crown is not the whole layer.","definitionCN":"树冠。单株树的枝叶；许多树冠合成林冠，但单株树冠不等于整层。"},{"word":"awning","ipa":"/ˈɔːnɪŋ/","tag":"shade cover","definition":"a sheet of canvas fixed over a door or window to give shade; it is a smaller, fixed cover, not a spreading roof.","definitionCN":"遮阳篷。固定在门窗上方遮阴的帆布，是较小固定的覆盖，不是铺开的顶。"},{"word":"ceiling","ipa":"/ˈsiːlɪŋ/","tag":"interior top","definition":"the upper surface of a room; it is an interior boundary, while a canopy is an overhead cover in open air.","definitionCN":"天花板。房间的上表面，是室内边界；canopy 是露天头顶的覆盖。"},{"word":"shade","ipa":"/ʃeɪd/","tag":"result of cover","definition":"the shadow or coolness produced by a cover; it names the effect, not the structure.","definitionCN":"阴凉；遮蔽。指覆盖产生的效果，而不是结构本身。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The Greek source meant 'mosquito net', which is already a covering held overhead.","cn":"希腊来源词意为「蚊帐」，本身就是头顶的覆盖物。"},{"en":"The word passed through Latin and French before entering English.","cn":"这个词经拉丁语与法语进入英语。"},{"en":"Ecology collocations: forest canopy, canopy cover, canopy layer.","cn":"生态搭配：森林林冠、林冠覆盖、林冠层。"},{"en":"Aviation and sport collocations: cockpit canopy, parachute canopy.","cn":"航空与运动搭配：座舱盖、降落伞伞衣。"},{"en":"A canopy is many crowns together; a crown is one tree's top.","cn":"canopy 是许多树冠合成的一层；crown 是单株树的顶部。"}],"abstract":[{"en":"Picture a green ceiling made of leaves, with small holes for sunlight.","cn":"想象一片叶子做成的绿色天花板，上面有小孔漏下阳光。"},{"en":"Picture a cloth held over a bride by four attendants walking in step.","cn":"想象四名侍从同步行走，把一块布撑在新娘头顶。"},{"en":"Picture a parachute as a soft roof that catches the air.","cn":"想象降落伞是一顶接住空气的软屋顶。"}]},"examples":[{"en":"Logging opened the canopy and let dry wind reach the forest floor.","cn":"采伐打开了林冠，让干燥的风吹到林地表面。"},{"en":"The market stalls were covered by a blue canvas canopy.","cn":"市场摊位上方盖着蓝色帆布顶篷。"},{"en":"Canopy cover is used as an index of how dense the forest is.","cn":"林冠覆盖度被用作衡量森林密度的指标。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「盖你披」——盖在头顶、披在上方的一层 → 顶篷、林冠","word":"canopy"},"root":"希腊语 kōnōpeion「蚊帐」，由 kōnōps「蚊、蚋」构成；经拉丁语 conopeum 与中世纪拉丁语、法语进入英语。kōnōps 的更深来源不确定，与 kōnos「圆锥」的联系仅为假说。","sensesIntro":{"en":"Eight senses all describe something spread overhead. The ecological layer is made of crowns; the bed, café, procession, aircraft and parachute covers are fabrics or shells; the starry canopy is a visual metaphor; canopy cover turns the roof into a number.","cn":"八个义项都描述在头顶铺开的东西。生态层由树冠组成；床、咖啡座、游行、飞机与降落伞的覆盖是织物或壳体；星空华盖是视觉比喻；林冠覆盖度则把顶篷变成数字。"},"semanticMap":{"core":{"en":"CORE IMAGE: a spread layer held above what it protects.","cn":"核心意象：一层在上方铺开、遮蔽其下之物的覆盖。"},"chain":["NET OVERHEAD","BED CURTAIN","ROOF OVER TABLES","FABRIC DOME","LAYER OF CROWNS","MEASURED COVER"],"branches":[{"senses":"01 · 08","en":"FOREST ROOF: many crowns form a layer, and that layer can be measured.","cn":"森林顶：许多树冠形成一层，这一层还能被测量。"},{"senses":"02 · 03","en":"DOMESTIC COVER: café awning and bed canopy are cloth roofs.","cn":"生活覆盖：咖啡座遮阳篷与床顶罩都是布制顶。"},{"senses":"04 · 05","en":"SHELLS: parachute and cockpit canopy are hard or inflated domes.","cn":"壳体：降落伞与座舱盖是硬质或充气穹顶。"},{"senses":"06","en":"RITUAL COVER: a carried cloth marks honour.","cn":"仪式覆盖：被撑起的布标记尊荣。"},{"senses":"07","en":"METAPHOR: the sky becomes a canopy of stars.","cn":"比喻：天空变成繁星华盖。"}]},"affixes":{"intro":{"en":"Canopy is a borrowed word with a small English family; the affix section separates the Greek and Latin layers from later English compounds.","cn":"canopy 是借入词，英语词族较小；词缀部分把希腊、拉丁层次与后世英语复合词分开。"},"latinIntro":{"en":"Greek kōnōpeion and Latin conopeum supply the base; Medieval Latin canopeum and French transmit it. English then built canopied and the compound canopy cover.","cn":"希腊 kōnōpeion 与拉丁 conopeum 提供基础；中世纪拉丁语 canopeum 与法语传递；英语随后构造 canopied 与复合词 canopy cover。"},"latinEntries":[{"word":"konopeion","structure":"kōnōpeion (Greek noun, 'mosquito net')","meaning":"mosquito net","meaningCN":"蚊帐"},{"word":"konops","structure":"kōnōps (Greek noun, 'gnat, mosquito')","meaning":"gnat, mosquito","meaningCN":"蚊；蚋"},{"word":"conopeum","structure":"conopeum, conopei (n., second declension, Latin from Greek)","meaning":"mosquito net, bed curtain","meaningCN":"蚊帐；床帘"}],"items":[{"word":"canopy","structure":"kōnōpeion via Latin conopeum","meaning":"an overhead cover; forest layer","meaningCN":"顶篷；林冠","example":"The canopy shades the path below.","exampleCN":"林冠给下方小径遮阴。"},{"word":"canopies","structure":"canopy + -es (plural)","meaning":"more than one canopy","meaningCN":"多片林冠或顶篷","example":"The two canopies meet above the street.","exampleCN":"两片顶篷在街道上方相接。"},{"word":"canopied","structure":"canopy + -ed (having)","meaning":"covered by a canopy","meaningCN":"有顶篷的；被林冠覆盖的","example":"They walked along a canopied lane.","exampleCN":"他们走在有树冠覆盖的小路上。"},{"word":"canopy cover","structure":"canopy + cover","meaning":"the proportion of ground shaded by crowns","meaningCN":"林冠覆盖度","example":"Canopy cover is measured from above.","exampleCN":"林冠覆盖度从上方测量。"},{"word":"canopy layer","structure":"canopy + layer","meaning":"the upper forest stratum","meaningCN":"林冠层","example":"Birds feed in the canopy layer.","exampleCN":"鸟类在林冠层取食。"},{"word":"canopy bed","structure":"canopy + bed","meaning":"a bed with an overhead frame and cover","meaningCN":"顶罩床","example":"The canopy bed has four carved posts.","exampleCN":"这张顶罩床有四根雕花柱。"},{"word":"parachute canopy","structure":"parachute + canopy","meaning":"the fabric dome of a parachute","meaningCN":"降落伞伞衣","example":"The canopy caught the air at once.","exampleCN":"伞衣立刻兜住了空气。"},{"word":"cockpit canopy","structure":"cockpit + canopy","meaning":"the transparent cover of a cockpit","meaningCN":"座舱盖","example":"The cockpit canopy reflects the sun.","exampleCN":"座舱盖反射阳光。"},{"word":"crown","structure":"crown (separate word, same tree image)","meaning":"the branches and leaves of one tree","meaningCN":"树冠（单株）","example":"The crown of the oak is wider than its root spread.","exampleCN":"这棵橡树的树冠比根系展幅更宽。"}]}},{"word":"forest","ipa_uk":"/ˈfɒrɪst/","ipa_us":"/ˈfɔːrɪst/","definition_zh":"森林；林地；大量直立物形成的密集层","definition_en":"a large area thickly covered with trees; the ecosystem formed by such an area; a dense mass of upright things","core_image":"一大片树冠彼此相接、从山脚一直铺到山脊的连续绿色","scene":"这片山地的森林从谷底一直铺到山脊，秋天一到，整面坡都变成金红色。 The forest on this mountainside runs from the valley floor up to the ridge, and in autumn the whole slope turns gold and red.","sceneCN":"这里该词指「覆盖山坡的大片森林」（第 1 个义项：大片树木覆盖的区域）；句意为这片山坡的森林从谷底延伸到山脊，秋天整面坡变成金红色。","pos":[{"tag":"n.","zh":"森林；大片树林"},{"tag":"n.","zh":"森林生态系统；森林生物群系"},{"tag":"n.","zh":"大量直立物形成的密集层"},{"tag":"n.","zh":"（历史）王室猎场；王室林地"},{"tag":"n.","zh":"比喻义：只见细节不见整体（用于习语）"},{"tag":"n.","zh":"受管理的林地资源"},{"tag":"n.","zh":"（图论）森林（无环图）"},{"tag":"v.","zh":"植树造林（古旧或少用）"}],"collocations":[{"phrase":"tropical forest","zh":"热带森林"},{"phrase":"temperate forest","zh":"温带森林"},{"phrase":"rain forest","zh":"雨林"},{"phrase":"forest floor","zh":"林地地表"},{"phrase":"forest canopy","zh":"森林林冠"},{"phrase":"forest management","zh":"森林经营"},{"phrase":"not see the forest for the trees","zh":"只见树木不见森林"}],"forms":[{"label":"复数（多片森林）","form":"forests"},{"label":"三单（植树，古旧）","form":"forests"},{"label":"过去式","form":"forested"},{"label":"过去分词","form":"forested"},{"label":"现在分词","form":"foresting"},{"label":"形容词（有森林的）","form":"forested"}],"derivatives":[{"word":"forested","pos":"adj.","zh":"有森林覆盖的"},{"word":"foresting","pos":"n.","zh":"造林（少用）"},{"word":"forestry","pos":"n.","zh":"林业；林地"},{"word":"forester","pos":"n.","zh":"林务员；森林居民"},{"word":"afforest","pos":"v.","zh":"造林；使成为森林"}],"senses":[{"no":"01","title":"Large tree-covered area","titleCN":"大片森林","definition":"a large area of land thickly covered with trees","definitionCN":"大片被树木密集覆盖的土地","example":"The forest begins where the farmland ends.","exampleCN":"森林从农田结束的地方开始。","why":"This is the everyday concrete sense: many trees over a large area.","whyCN":"这是日常具体义：大片土地上的许多树。"},{"no":"02","title":"Forest ecosystem","titleCN":"森林生态系统","definition":"the community of trees, plants, animals and soil processes that forms in such an area","definitionCN":"在这样的区域形成的树木、植物、动物与土壤过程的整体","example":"The forest recycles most of its nutrients through leaf litter.","exampleCN":"这片森林通过落叶回收大部分养分。","why":"Ecology treats the forest as a functioning system, not just a collection of trees.","whyCN":"生态学把森林当作运作系统，而不只是树的集合。"},{"no":"03","title":"Dense upright mass","titleCN":"密集的直立物","definition":"a large number of tall upright objects standing close together","definitionCN":"大量高耸而直立的东西密集排列","example":"A forest of masts filled the harbour.","exampleCN":"港口里挤满了密集的桅杆。","why":"The tree image is transferred to any crowd of vertical objects.","whyCN":"树的意象被转移到任何密集的直立物群。"},{"no":"04","title":"Royal hunting ground","titleCN":"王室猎场","definition":"a tract of land, often wooded, set aside by a king for hunting","definitionCN":"国王划出用于狩猎的一片土地，常为林地","example":"The old forest law protected deer rather than farmers.","exampleCN":"旧的王室林地法保护鹿，而不是农民。","why":"This is a legal and historical sense in which forest meant jurisdiction, not simply trees.","whyCN":"这是法律与历史义：该词指管辖区域，而不只是树木。"},{"no":"05","title":"Whole versus detail","titleCN":"整体与细节","definition":"used in the idiom about failing to see the whole because of attention to small details","definitionCN":"用于习语，指因专注细节而看不到整体","example":"The report missed the forest for the trees.","exampleCN":"这份报告只见树木不见森林。","why":"The word stands for the large pattern that detail can hide.","whyCN":"这个词代表被细节遮住的大格局。"},{"no":"06","title":"Managed woodland","titleCN":"受管理的林地","definition":"woodland managed as a resource for timber, fuel or conservation","definitionCN":"作为木材、燃料或保护资源而经营的林地","example":"The forest is thinned every twenty years.","exampleCN":"这片林地每二十年疏伐一次。","why":"The tree-covered area is treated as a crop with a rotation, so the forest becomes a managed resource.","whyCN":"树木覆盖区被当作有轮伐期的作物，于是森林成为受管理的资源。"},{"no":"07","title":"Graph-theory forest","titleCN":"图论中的森林","definition":"a graph with no cycles, equivalent to a set of disjoint trees","definitionCN":"不含环的图，等价于一组互不相连的树","example":"A graph with no cycles is called a forest.","exampleCN":"不含环的图被称为森林。","why":"Graph theory extends the tree image to a collection of trees.","whyCN":"图论把树的意象扩展到一组树。"},{"no":"08","title":"Plant with trees (archaic)","titleCN":"植树造林（古旧用法）","definition":"to cover land with trees","definitionCN":"在土地上种植树木","example":"Early settlers forested the valley slopes.","exampleCN":"早期定居者在谷坡上植树成林。","why":"The verb is now rare and has been replaced by afforest and reforest.","whyCN":"这个动词现在少见，已被「造林」与「重新造林」两个词取代。"}],"etymology":{"intro":{"en":"The legal and ecological senses both grow from a Medieval Latin term whose literal meaning is disputed but usually explained as 'outside wood'.","cn":"中世纪拉丁语 forestis 的字面义有争议，通常解释为「耕地之外的林地」；foris「外面」是较通行的来源，另一说未被普遍接受。"},"items":[{"era":"MEDIEVAL LATIN (8th-9th c.)","en":"Medieval Latin forestis (silva) is first recorded in royal and legal documents. It probably meant woodland outside the cultivated area, though the exact sense is debated.","cn":"中世纪拉丁语 forestis（silva）最早见于王室与法律文书。它可能指耕地之外的林地，但确切含义有争议。"},{"era":"LATIN","en":"The element is usually derived from foris 'outside, out of doors', related to forum. An alternative link to forestis 'of the forum' is disputed and not generally accepted.","cn":"该成分通常追溯到 foris「在外面、户外」，与 forum 有关。另一种把它联系到 forestis「广场的」的说法有争议，未被普遍接受。"},{"era":"OLD FRENCH (12th c.)","en":"Old French forest meant a large wood and also a royal hunting preserve. English borrowed it after the Norman Conquest.","cn":"古法语 forest 指大片树林，也指王室猎场。英语在诺曼征服后借入。"},{"era":"ENGLISH (13th-17th c.)","en":"In English law a forest was a royal area with special hunting rights, which could include open land as well as trees.","cn":"在英国法律中，forest 是拥有特殊狩猎权的王室区域，可以包括树木，也可以包括开阔地。"},{"era":"ENGLISH (18th-19th c.)","en":"With the rise of scientific forestry, forest shifted back toward its ecological meaning: a large tree-dominated community.","cn":"随着科学林业兴起，forest 又转向生态义：以树木为主的大片群落。"},{"era":"MODERN ENGLISH","en":"Twentieth-century ecology and mathematics added the ecosystem and graph-theory senses. The verb is now rare.","cn":"二十世纪的生态学与数学增加了生态系统义与图论义。动词用法现已少见。"}]},"similar":{"note":{"en":"The first group is close in sound or spelling but unrelated; the second group shares the tree-covered-area meaning at different scales.","cn":"第一组在读音或拼写上接近但无关；第二组在不同尺度上共享「树木覆盖区域」的意思。"},"groups":[{"heading":"SOUND-ALIKE","entries":[{"word":"forecast","ipa":"/ˈfɔːkɑːst/","tag":"near sound, different word","definition":"a prediction, from fore- 'before' plus cast; it has no connection to forest.","definitionCN":"预报。由 fore-「预先」加 cast 构成，与 forest 无关。"},{"word":"foremost","ipa":"/ˈfɔːməʊst/","tag":"near sound, different word","definition":"leading in position, from fore- plus most.","definitionCN":"最前面的；首要的。由 fore- 加 most 构成。"},{"word":"forrest","ipa":"/ˈfɒrɪst/","tag":"same sound, proper name","definition":"a surname and given name meaning 'forest', spelled with a double r; it is a name, not the common noun.","definitionCN":"福雷斯特。姓氏或名字，拼写为双 r，意为「森林」；是专名，不是普通名词。"}]},{"heading":"NEAR-MEANING","entries":[{"word":"wood","ipa":"/wʊd/","tag":"smaller tree area","definition":"a smaller area of trees than a forest; British usage often keeps wood for a modest patch.","definitionCN":"树林。通常比 forest 小；英式用法常以 wood 指不大的一片。"},{"word":"woodland","ipa":"/ˈwʊdlənd/","tag":"tree-covered land","definition":"land covered with trees, often used in ecology and land-use descriptions; it is less formal than forest and can be smaller.","definitionCN":"林地。被树木覆盖的土地，常用于生态与土地利用描述；比 forest 少些正式感，面积也可更小。"},{"word":"grove","ipa":"/ɡrəʊv/","tag":"small cluster","definition":"a small group of trees, often of one kind or planted in a pattern.","definitionCN":"小树林。一小群树，常为同一树种或有规则栽植。"},{"word":"jungle","ipa":"/ˈdʒʌŋɡl/","tag":"dense tropical vegetation","definition":"dense tangled tropical vegetation; it stresses impenetrability, while forest is a neutral ecological term.","definitionCN":"丛林。茂密纠缠的热带植被，强调难以穿行；forest 是中性生态术语。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The legal sense came first in English: a royal area with hunting rights, not necessarily all trees.","cn":"英语中法律义先出现：拥有狩猎权的王室区域，不一定全是树。"},{"en":"The ecological sense returned with scientific forestry in the eighteenth and nineteenth centuries.","cn":"生态义随着十八、十九世纪的科学林业回归。"},{"en":"Collocations: tropical forest, rain forest, forest floor, forest canopy.","cn":"搭配：热带森林、雨林、林地地表、森林林冠。"},{"en":"The idiom not see the forest for the trees means to miss the whole.","cn":"习语 not see the forest for the trees 意为看不到整体。"},{"en":"Forestry, forester and afforest are the productive relatives.","cn":"forestry、forester 与 afforest 是能产的亲属词。"}],"abstract":[{"en":"Picture a green sea that covers a whole valley and hides the ground.","cn":"想象一片绿色的海覆盖整个山谷，把地面遮住。"},{"en":"Picture a harbour so full of masts that it looks like a vertical wood.","cn":"想象港口挤满桅杆，看上去像一片竖立的树林。"},{"en":"Picture a map where one large green patch is surrounded by small grey fields.","cn":"想象地图上一大块绿色被小块灰色农田包围。"}]},"examples":[{"en":"The forest on the ridge survived because the slope was too steep to log.","cn":"山脊上的森林因为坡太陡无法采伐而保留下来。"},{"en":"A forest of television towers rose above the stadium.","cn":"一片电视塔像森林一样立在体育场上方。"},{"en":"The old forest law allowed the king to hunt across private land.","cn":"旧的王室林地法允许国王在私人土地上狩猎。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「佛瑞斯特」——一大片树连成绿色海洋 → 森林","word":"forest"},"root":"中世纪拉丁语 forestis（silva）最早见于王室法律文书，通常解释为「耕地之外的林地」，来源为拉丁语 foris「在外面」；另一说与 forestis「广场的」相关，未被普遍接受。后经古法语 forest 进入英语。","sensesIntro":{"en":"Eight senses move from a large tree-covered area to the ecosystem it forms, then to any dense upright mass, a legal hunting jurisdiction, a whole-versus-detail idiom, a managed resource, a graph without cycles and finally an archaic planting verb.","cn":"八个义项从大片树木覆盖区，到它形成的生态系统，再到任何密集直立物、法律狩猎辖区、整体与细节的习语、受管理资源、无环图，最后是古旧的植树动词。"},"semanticMap":{"core":{"en":"CORE IMAGE: a continuous green cover large enough to hide the ground beneath it.","cn":"核心意象：一片足够大、能把地面遮住的连续绿色覆盖。"},"chain":["TREES TOGETHER","LARGE AREA","FUNCTIONING ECOSYSTEM","VERTICAL MASS","LEGAL PRESERVE","ACYCLIC GRAPH"],"branches":[{"senses":"01 · 02","en":"AREA AND SYSTEM: the visible cover and the processes inside it.","cn":"区域与系统：可见的覆盖与其内部的运作。"},{"senses":"03","en":"VERTICAL TRANSFER: any dense upright mass becomes a forest.","cn":"垂直转移：任何密集直立物都可成为森林。"},{"senses":"04 · 06","en":"LAW AND MANAGEMENT: jurisdiction and resource are two ways of owning the cover.","cn":"法律与经营：辖区与资源是拥有这片覆盖的两种方式。"},{"senses":"05","en":"IDIOM: the large pattern that detail hides.","cn":"习语：细节所遮蔽的大格局。"},{"senses":"07 · 08","en":"ABSTRACT EXTENSIONS: graph theory and the archaic planting verb.","cn":"抽象延伸：图论与古旧植树动词。"}]},"affixes":{"intro":{"en":"Forest has a compact family built on a Medieval Latin base, with the legal and ecological senses layering over the same word.","cn":"forest 有一个建立在中世纪拉丁语基础上的紧凑词族，法律义与生态义层层叠在同一个词上。"},"latinIntro":{"en":"Medieval Latin forestis and Latin foris supply the base, Old French forest transmits it, and English built forestry, forester and afforest.","cn":"中世纪拉丁语 forestis 与拉丁语 foris 提供基础，古法语 forest 传递，英语构造了 forestry、forester 与 afforest。"},"latinEntries":[{"word":"forestis","structure":"forestis (silva) (Medieval Latin phrase)","meaning":"woodland outside the cultivated area","meaningCN":"耕地之外的林地"},{"word":"foris","structure":"foris (Latin adverb and noun)","meaning":"outside, out of doors","meaningCN":"在外面；户外"},{"word":"foresta","structure":"foresta, forestae (f., first declension, Medieval Latin)","meaning":"woodland, hunting preserve","meaningCN":"林地；猎场"}],"items":[{"word":"forest","structure":"forestis via Old French forest","meaning":"a large tree-covered area","meaningCN":"大片森林","example":"The forest covers the whole valley.","exampleCN":"森林覆盖整个山谷。"},{"word":"forests","structure":"forest + -s (plural)","meaning":"more than one forest","meaningCN":"多片森林","example":"Two forests meet at the river.","exampleCN":"两片森林在河边相接。"},{"word":"forested","structure":"forest + -ed (having)","meaning":"covered with forest","meaningCN":"有森林覆盖的","example":"The upper slopes are heavily forested.","exampleCN":"上坡覆盖着茂密森林。"},{"word":"foresting","structure":"forest + -ing (action)","meaning":"the act of planting with trees","meaningCN":"造林（少用）","example":"Foresting the bare slope took decades.","exampleCN":"在裸坡上造林花了几十年。"},{"word":"forestry","structure":"forest + -ry (practice or place)","meaning":"the science or practice of managing forests","meaningCN":"林业","example":"Forestry regulates how much timber is cut.","exampleCN":"林业管理木材采伐量。"},{"word":"forester","structure":"forest + -er (person)","meaning":"a person who manages or works in a forest","meaningCN":"林务员；森林工作者","example":"The forester marked the trees to be felled.","exampleCN":"林务员标记了要砍的树。"},{"word":"afforest","structure":"ad- + forest (to make)","meaning":"to plant land with forest","meaningCN":"造林；使成为森林","example":"The scheme will afforest the eroded hillside.","exampleCN":"该计划将在受侵蚀的山坡造林。"},{"word":"deforestation","structure":"de- + forest + -ation","meaning":"the removal of forest","meaningCN":"毁林；森林砍伐","example":"Deforestation reduced the catchment's cover.","exampleCN":"毁林减少了集水区的覆盖。"},{"word":"rain forest","structure":"rain + forest","meaning":"a dense tropical forest with heavy rainfall","meaningCN":"雨林","example":"Rain forest canopy stays humid all year.","exampleCN":"雨林林冠全年潮湿。"}]}},{"word":"forestry","ipa_uk":"/ˈfɒrɪstri/","ipa_us":"/ˈfɔːrɪstri/","definition_zh":"林业；森林学；林地","definition_en":"the science and practice of planting, managing and caring for forests; also forest land","core_image":"一张林地图上标着采伐区、育苗区和保留带，所有活动被排进同一份年度计划","scene":"这个地区把林业当作主要产业，伐木、育苗和护林都由同一套规划管理。 This region treats forestry as its main industry, with logging, nurseries and forest protection all managed under one plan.","sceneCN":"这里该词指「林业这一产业与实践」（第 2 个义项：以森林为对象的经营活动）；句意为这个地区把林业当作主要产业，伐木、育苗与护林都纳入同一份规划。","pos":[{"tag":"n.","zh":"林业；森林经营"},{"tag":"n.","zh":"森林学；林学"},{"tag":"n.","zh":"林地；森林地带（英式，常作不可数）"},{"tag":"n.","zh":"造林与护林实践"}],"collocations":[{"phrase":"sustainable forestry","zh":"可持续林业"},{"phrase":"community forestry","zh":"社区林业"},{"phrase":"urban forestry","zh":"城市林业"},{"phrase":"forestry commission","zh":"林业委员会"},{"phrase":"forestry practice","zh":"林业实践"},{"phrase":"forestry land","zh":"林地"}],"forms":[{"label":"（不可数，通常无复数）","form":"forestry"},{"label":"复数（罕见，指多种林业体系）","form":"forestries"},{"label":"相关名词（林务员）","form":"forester"},{"label":"相关名词（造林）","form":"afforestation"},{"label":"相关名词（森林学）","form":"silviculture"}],"derivatives":[{"word":"forester","pos":"n.","zh":"林务员；森林工作者"},{"word":"forest","pos":"n.","zh":"森林"},{"word":"forestation","pos":"n.","zh":"造林；植树"},{"word":"afforest","pos":"v.","zh":"造林"},{"word":"silviculture","pos":"n.","zh":"造林学；育林"},{"word":"agroforestry","pos":"n.","zh":"农林复合经营"}],"senses":[{"no":"01","title":"Science of managing forests","titleCN":"森林经营的科学","definition":"the science of establishing, tending and harvesting forests on a sustainable basis","definitionCN":"以可持续方式建立、培育与采伐森林的科学","example":"Modern forestry balances timber yield against soil and water protection.","exampleCN":"现代林业在木材产量与水土保护之间寻求平衡。","why":"This is the disciplinary sense: a body of knowledge with methods and principles.","whyCN":"这是学科义：一套有方法与原则的知识体系。"},{"no":"02","title":"Industry and practice","titleCN":"林业产业与实践","definition":"the practical work and business of growing, harvesting and processing timber","definitionCN":"培育、采伐与加工木材的实际工作与产业","example":"Forestry employs more people here than fishing does.","exampleCN":"在这里，林业雇用的劳动力比渔业更多。","why":"The same knowledge becomes an economic sector when it is organized at scale.","whyCN":"同样的知识一旦规模化组织起来，就成为经济部门。"},{"no":"03","title":"Forested land (British)","titleCN":"林地（英式）","definition":"land covered with trees, especially when considered as a land-use category","definitionCN":"被树木覆盖的土地，尤作为土地利用类别","example":"The estate includes several thousand acres of forestry.","exampleCN":"这片地产包括数千英亩林地。","why":"This is a land-cover sense rather than a profession sense, and it is more common in British usage.","whyCN":"这是土地覆盖义而非职业义，在英式用法中更常见。"},{"no":"04","title":"Academic discipline","titleCN":"林学学科","definition":"the university subject that trains students in forest ecology, measurement, policy and management","definitionCN":"在大学中教授森林生态、测量、政策与管理的学科","example":"She studied forestry and later worked on watershed policy.","exampleCN":"她学的是林学，后来从事流域政策。","why":"A field of study is a branch of knowledge, and forestry became one such branch.","whyCN":"研究领域是知识树上的分支，林业成为其中一支。"},{"no":"05","title":"Silviculture","titleCN":"育林；造林学","definition":"the part of forestry concerned with the establishment and care of individual stands of trees","definitionCN":"林业中负责林木群落的建立与养护的部分","example":"Silviculture decides which species to favour at each stage.","exampleCN":"育林决定每个阶段优先保留哪些树种。","why":"The word names the stand-level part of forestry, where species and spacing are decided.","whyCN":"这个词命名林业中林分层面的部分，树种与间距都在这里决定。"},{"no":"06","title":"Forest protection and management","titleCN":"森林保护与经营","definition":"the planning and control of cutting, regeneration, fire risk and pest outbreaks","definitionCN":"对采伐、更新、火灾风险与虫害的规划与控制","example":"Forestry reduced the fuel load before the dry season.","exampleCN":"林业部门在旱季前减少了可燃物载量。","why":"Protection is the operational side: the plan must control fire, pests and cutting.","whyCN":"保护是运营层面：计划必须控制火灾、虫害与采伐。"},{"no":"07","title":"Urban forestry","titleCN":"城市林业","definition":"the management of trees in towns and cities for shade, air quality and recreation","definitionCN":"为遮阴、空气质量与休闲而管理城镇树木","example":"Urban forestry now counts street trees as infrastructure.","exampleCN":"城市林业现在把行道树算作基础设施。","why":"The forest image moves to the city, where trees are managed as public infrastructure.","whyCN":"森林意象移到城市，树木被当作公共基础设施管理。"},{"no":"08","title":"Community forestry","titleCN":"社区林业","definition":"forest management in which local communities hold rights and share benefits","definitionCN":"由当地社区持有权利并分享收益的森林经营","example":"Community forestry gave the village a stake in protecting the watershed.","exampleCN":"社区林业让村庄在保护流域中获得切身利益。","why":"Rights and benefits are shared, so the forest is managed by those who live beside it.","whyCN":"权利与收益共享，因此森林由住在旁边的人管理。"}],"etymology":{"intro":{"en":"Forestry is an English derivative of forest. Its professional and scientific senses were shaped in the eighteenth and nineteenth centuries, partly under German influence, and the dates are approximate.","cn":"该词为 forest 的英语派生；职业与科学义在十八、十九世纪成形，部分受德国森林经营影响，具体年代为大致估计。"},"items":[{"era":"OLD FRENCH AND MIDDLE ENGLISH","en":"The base forest came through Old French forest from Medieval Latin forestis. The suffix -ry (from French -erie) marks a practice, a place or a body of activity.","cn":"基础词 forest 经古法语 forest 来自中世纪拉丁语 forestis。后缀 -ry（源自法语 -erie）标记实践、场所或活动体系。"},{"era":"ENGLISH (17th c.)","en":"Early forestry meant forest land or the status of being forested. The professional sense of managing woods developed later.","cn":"早期的 forestry 指林地或成为林地的状态。管理森林的职业义后来才发展出来。"},{"era":"ENGLISH (18th-19th c.)","en":"Scientific forestry grew with naval timber demand and with German forest management, which supplied models for measuring and regenerating stands.","cn":"科学林业随海军木材需求与德国森林经营而发展，后者提供了测量与更新林分的模式。"},{"era":"ENGLISH (19th-20th c.)","en":"Forestry became a university discipline and a government service. Colonial administrations set up forest departments across Asia and Africa.","cn":"林业成为大学学科与政府职能部门。殖民政府在亚洲与非洲各地设立森林部门。"},{"era":"MODERN ENGLISH","en":"Urban forestry and community forestry are late twentieth-century branches that widened the field from timber to public benefits.","cn":"城市林业与社区林业是二十世纪后期的分支，把领域从木材扩展到公共收益。"}]},"similar":{"note":{"en":"The first group is close in sound or spelling but unrelated; the second group shares forest work or tree growing.","cn":"第一组在读音或拼写上接近但无关；第二组共享森林工作或树木培育的意思。"},"groups":[{"heading":"SOUND-ALIKE","entries":[{"word":"forest","ipa":"/ˈfɒrɪst/","tag":"base noun","definition":"the tree-covered area itself; forestry is the practice or science built on it.","definitionCN":"森林。树木覆盖的区域本身；forestry 是建立在它之上的实践或科学。"},{"word":"forgery","ipa":"/ˈfɔːdʒəri/","tag":"near sound, different root","definition":"a fake document or object, from forge 'to make falsely'; it has no tree sense.","definitionCN":"伪造品。来自 forge「伪造」，没有树木义。"},{"word":"forcibly","ipa":"/ˈfɔːsəbli/","tag":"near rhythm, different root","definition":"in a strong or violent way, from force; the similarity is only in the opening.","definitionCN":"强行地。来自 force，相似只出现在开头。"}]},{"heading":"NEAR-MEANING","entries":[{"word":"silviculture","ipa":"/ˈsɪlvɪkʌltʃə(r)/","tag":"stand-level care","definition":"the cultivation of individual forest stands; it is a part of forestry, not the whole field.","definitionCN":"育林；造林学。对单个林分的培育，是林业的一部分，不是整个领域。"},{"word":"arboriculture","ipa":"/ˌɑːbərɪˈkʌltʃə(r)/","tag":"tree cultivation","definition":"the cultivation of individual trees, often for amenity or orchards; it works tree by tree rather than stand by stand.","definitionCN":"树木栽培。对单株树的培育，常用于景观或果园；按株而非按林分操作。"},{"word":"forest management","ipa":"/ˈfɒrɪst mænɪdʒmənt/","tag":"practice phrase","definition":"the operational planning of a forest; it is the activity, while forestry is the field that contains it.","definitionCN":"森林经营。对一片森林的运营规划，是具体活动，而 forestry 是包含它的领域。"},{"word":"agroforestry","ipa":"/ˌæɡrəʊˈfɒrɪstri/","tag":"mixed land use","definition":"the deliberate combination of trees with crops or livestock; forestry alone does not include the crop component.","definitionCN":"农林复合经营。树木与作物或牲畜的有意结合；单说林业不含作物部分。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The base is forest, and the suffix -ry marks a practice, place or field, as in husbandry and fishery.","cn":"基础词是 forest，后缀 -ry 标记实践、场所或领域，如 husbandry 与 fishery。"},{"en":"German forest management supplied much of the early scientific model.","cn":"德国森林经营提供了早期科学模式的大部分内容。"},{"en":"Collocations: sustainable forestry, community forestry, urban forestry.","cn":"搭配：可持续林业、社区林业、城市林业。"},{"en":"Forestry is the field; silviculture is the stand-level part of it.","cn":"forestry 是领域；silviculture（育林学）是其中林分层面的部分。"},{"en":"Forester is the person; forestry is the work and the discipline.","cn":"forester 是人；forestry 是工作与学科。"}],"abstract":[{"en":"Picture a map divided into cutting blocks, each dated years in advance.","cn":"想象一张地图被划成采伐区块，每一块的年份都提前排好。"},{"en":"Picture a nursery where thousands of seedlings wait in rows for the hillside.","cn":"想象苗圃里成千上万的苗木成排等待上山。"},{"en":"Picture a city street where each tree has its own inspection record.","cn":"想象一条城市街道，每棵树都有自己的检查记录。"}]},"examples":[{"en":"Forestry students spend a full term measuring stands in the field.","cn":"林学学生要用整整一个学期在野外测量林分。"},{"en":"Community forestry returned control of the watershed to the villages.","cn":"社区林业把流域的控制权交回村庄。"},{"en":"The country earns more from forestry than from its mines.","cn":"这个国家的林业收入超过矿业收入。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「森林 + 业」——以森林为对象的一门产业与学问 → 林业","word":"forestry"},"root":"由 forest 加后缀 -ry 构成；forest 经古法语 forest 来自中世纪拉丁语 forestis，通常解释为「耕地之外的林地」。职业与科学义在十八、十九世纪成形，受德国森林经营影响。","sensesIntro":{"en":"Eight senses move from knowledge to industry, land, university subject, stand-level care, operational protection, and then to two modern branches that shift the purpose from timber to urban and community benefits.","cn":"八个义项从知识到产业、土地、大学学科、林分养护、经营保护，再到两个现代分支，把目的从木材转向城市与社区收益。"},"semanticMap":{"core":{"en":"CORE IMAGE: one forest entered by a written plan that assigns every block a year and a purpose.","cn":"核心意象：一片森林被一份书面计划接管，每块地都有年份与用途。"},"chain":["TREES AS A CROP","MEASURE THE STAND","PLAN THE CUT","PROTECT THE SOIL","MANAGE CITY TREES","SHARE WITH COMMUNITY"],"branches":[{"senses":"01 · 04","en":"KNOWLEDGE: the science and the university subject are the same body of method.","cn":"知识：科学与大学学科是同一套方法体系。"},{"senses":"02 · 05 · 06","en":"PRACTICE: industry, stand care and protection are three scales of work.","cn":"实践：产业、林分养护与保护是三个尺度的作业。"},{"senses":"03","en":"LAND: forestry can mean the wooded land itself, especially in British usage.","cn":"土地：该词可指林地本身，尤见于英式用法。"},{"senses":"07","en":"URBAN: the field moves from timber to shade, air and recreation.","cn":"城市：领域从木材转向遮阴、空气与休闲。"},{"senses":"08","en":"COMMUNITY: rights and benefits are shared with local people.","cn":"社区：权利与收益与当地人共享。"}]},"affixes":{"intro":{"en":"Forestry joins a Medieval Latin base to a French-derived suffix, so the word reads as one borrowed stem plus one borrowed ending, with English compounds added later.","cn":"forestry 把中世纪拉丁语基础词与法语来源后缀接在一起，读起来就是一个借入词干加一个借入词尾，后世又加入英语复合词。"},"latinIntro":{"en":"Medieval Latin forestis and Latin foris supply the base; Old French -erie supplies the suffix; silviculture and agroforestry are later learned compounds.","cn":"中世纪拉丁语 forestis 与拉丁语 foris 提供基础；古法语 -erie 提供后缀；silviculture（育林学）与 agroforestry（农林复合经营）是后世学术复合词。"},"latinEntries":[{"word":"forestis","structure":"forestis (silva) (Medieval Latin phrase)","meaning":"woodland outside the cultivated area","meaningCN":"耕地之外的林地"},{"word":"foris","structure":"foris (Latin adverb)","meaning":"outside, out of doors","meaningCN":"在外面；户外"},{"word":"silva","structure":"silva, silvae (f., first declension)","meaning":"wood, forest","meaningCN":"树林；森林"}],"items":[{"word":"forest","structure":"forestis via Old French forest","meaning":"a large tree-covered area","meaningCN":"森林","example":"The forest supplies both timber and water.","exampleCN":"森林既提供木材也提供水源。"},{"word":"forestry","structure":"forest + -ry (practice or field)","meaning":"the science and practice of managing forests","meaningCN":"林业；林学","example":"Forestry sets the annual cut.","exampleCN":"林业部门定下年度采伐量。"},{"word":"forester","structure":"forest + -er (person)","meaning":"a person who manages forests","meaningCN":"林务员","example":"The forester marked the boundary.","exampleCN":"林务员标出了边界。"},{"word":"forested","structure":"forest + -ed (having)","meaning":"covered with forest","meaningCN":"有森林覆盖的","example":"The catchment is heavily forested.","exampleCN":"这个集水区森林茂密。"},{"word":"afforestation","structure":"ad- + forest + -ation","meaning":"planting a new forest on land without one","meaningCN":"造林；新造林","example":"Afforestation stabilised the sand dunes.","exampleCN":"新造林稳住了沙丘。"},{"word":"reforestation","structure":"re- + forest + -ation","meaning":"replanting a forest after loss","meaningCN":"重新造林","example":"Reforestation followed the fire.","exampleCN":"火灾之后进行了重新造林。"},{"word":"silviculture","structure":"silva + cultura","meaning":"the cultivation of forest stands","meaningCN":"育林；造林学","example":"Silviculture chooses the next crop.","exampleCN":"育林决定下一轮林木。"},{"word":"agroforestry","structure":"agro- + forestry","meaning":"trees combined with crops or livestock","meaningCN":"农林复合经营","example":"Agroforestry shades the coffee plants.","exampleCN":"农林复合经营为咖啡树遮阴。"},{"word":"urban forestry","structure":"urban + forestry","meaning":"management of city trees","meaningCN":"城市林业","example":"Urban forestry plans street planting.","exampleCN":"城市林业规划街道绿化。"}]}},{"word":"forestation","ipa_uk":"/ˌfɒrɪˈsteɪʃn/","ipa_us":"/ˌfɔːrɪˈsteɪʃn/","definition_zh":"造林；植树成林；森林覆盖的建立","definition_en":"the act or process of establishing forest cover by planting or sowing trees on land","core_image":"一片荒坡先被挖出整齐的树穴，随后苗木成片栽下，几年后连成绿色覆盖","scene":"荒坡上先挖出一排排树穴，随后苗木被成片栽下，几年后这里重新有了连续的林冠。 Rows of planting pits were dug on the bare slope, seedlings were set out in blocks, and within a few years continuous forest cover had returned: that whole effort is forestation.","sceneCN":"这里该词指「建立森林覆盖的整个努力」（第 1 个义项：通过栽植建立森林）；句意为荒坡先挖穴、再成片栽苗，几年后恢复连续林冠，这一整套工作就是造林。","pos":[{"tag":"n.","zh":"造林；植树成林"},{"tag":"n.","zh":"森林覆盖的建立过程"},{"tag":"n.","zh":"新造林（在原本无林的土地上）"},{"tag":"n.","zh":"重新造林（在曾经有林的土地上）"},{"tag":"n.","zh":"大规模植树计划"},{"tag":"n.","zh":"造林结果；已建立的林地"},{"tag":"n.","zh":"为碳汇或气候目的进行的造林"},{"tag":"n.","zh":"土地用途转为林地"}],"collocations":[{"phrase":"large-scale forestation","zh":"大规模造林"},{"phrase":"forestation program","zh":"造林计划"},{"phrase":"forestation project","zh":"造林项目"},{"phrase":"forestation of degraded land","zh":"退化地造林"},{"phrase":"forestation rate","zh":"造林速度"},{"phrase":"carbon forestation","zh":"碳汇造林"}],"forms":[{"label":"复数（多次或多种造林）","form":"forestations"},{"label":"相关动词（造林）","form":"afforest"},{"label":"相关名词（新造林）","form":"afforestation"},{"label":"相关名词（重新造林）","form":"reforestation"},{"label":"反义名词（毁林）","form":"deforestation"}],"derivatives":[{"word":"afforestation","pos":"n.","zh":"新造林（无林地上）"},{"word":"reforestation","pos":"n.","zh":"重新造林"},{"word":"deforestation","pos":"n.","zh":"毁林；森林砍伐"},{"word":"forest","pos":"n.","zh":"森林"},{"word":"forested","pos":"adj.","zh":"有森林覆盖的"}],"senses":[{"no":"01","title":"Establishing forest cover","titleCN":"建立森林覆盖","definition":"the act or process of establishing a forest on land by planting or sowing trees","definitionCN":"通过栽植或播种在土地上建立森林的行为或过程","example":"Forestation began with a survey of the eroded slopes.","exampleCN":"造林从对侵蚀坡地的调查开始。","why":"This is the umbrella sense: any deliberate creation of forest cover.","whyCN":"这是总称义：任何有意建立森林覆盖的行为。"},{"no":"02","title":"Process over time","titleCN":"随时间推进的造林过程","definition":"the multi-year process by which planted land develops into functioning forest","definitionCN":"栽植土地在多年中发育为功能森林的过程","example":"Forestation is measured in decades, not seasons.","exampleCN":"造林以十年计，而不是以季节计。","why":"The word can name the slow process rather than the single planting event.","whyCN":"这个词可以命名缓慢过程，而不是一次栽植事件。"},{"no":"03","title":"Afforestation on bare land","titleCN":"在无林地上新造林","definition":"the creation of forest on land that has not recently carried forest","definitionCN":"在近期没有森林的土地上建立森林","example":"Afforestation converted the old pasture into a new wood.","exampleCN":"新造林把旧牧场变成一片新林地。","why":"Technical usage separates new forest on bare land from replanting after loss.","whyCN":"技术用法把裸地上的新林与损失后的补植区分开。"},{"no":"04","title":"Reforestation after loss","titleCN":"森林损失后的重新造林","definition":"the replanting of land that was formerly forested but has lost its tree cover","definitionCN":"在曾经有林、后来失去树冠的土地上重新栽植","example":"Reforestation followed the fire that burned the ridge.","exampleCN":"山脊被火烧过之后进行了重新造林。","why":"The same act is named by its history: the land remembers a previous forest.","whyCN":"同一动作按土地历史命名：这块地记得从前的森林。"},{"no":"05","title":"Large-scale planting program","titleCN":"大规模植树计划","definition":"an organized program that plants many hectares or millions of seedlings","definitionCN":"有组织地栽植许多公顷或数百万株苗木的计划","example":"The national forestation program planted a billion trees.","exampleCN":"国家造林计划栽下了十亿棵树。","why":"Scale turns a practice into a policy instrument with targets and budgets.","whyCN":"规模把实践变成有目标与预算的政策工具。"},{"no":"06","title":"Resulting forest area","titleCN":"造林形成的林地","definition":"the forest area that results from planting, considered as an outcome","definitionCN":"栽植所产生的森林面积，作为结果来看","example":"The forestation now covers the whole western slope.","exampleCN":"新造的林地现在覆盖整个西坡。","why":"The action noun also names its product: the area that now carries forest.","whyCN":"动作名词也命名产物：现在长着森林的那片面积。"},{"no":"07","title":"Carbon or climate forestation","titleCN":"碳汇或气候造林","definition":"forestation undertaken to absorb carbon or meet climate targets","definitionCN":"为吸收碳或达成气候目标而进行的造林","example":"Carbon forestation is counted in tonnes of carbon dioxide stored.","exampleCN":"碳汇造林以储存的二氧化碳吨数计量。","why":"The purpose changes the name: the forest is valued for stored carbon rather than timber.","whyCN":"目的改变名称：这片森林的价值在储存的碳，而不在木材。"},{"no":"08","title":"Land-use conversion","titleCN":"土地用途转为林地","definition":"the change of land use from agriculture or bare ground to forest","definitionCN":"把农业用地或裸地改为林地","example":"Forestation changed the hydrology of the catchment within a decade.","exampleCN":"造林在十年内改变了这个集水区的水文状况。","why":"Seen from land-use planning, planting trees is a change of category, not only an act on a slope.","whyCN":"从土地利用规划看，种树是类别改变，而不只是坡上的一项动作。"}],"etymology":{"intro":{"en":"Forestation is an English formation on forest plus the Latin-derived suffix -ation. Its technical branches, especially afforestation and reforestation, are nineteenth- and twentieth-century developments.","cn":"该词由 forest 与拉丁来源后缀 -ation 构成；技术分支 afforestation、reforestation 在十九至二十世纪定型，具体年代为大致估计。"},"items":[{"era":"MEDIEVAL LATIN AND FRENCH","en":"The base forest comes from Medieval Latin forestis through Old French. The suffix -ation comes from Latin -atio, which names an action or its result.","cn":"基础词 forest 经古法语来自中世纪拉丁语 forestis。后缀 -ation 来自拉丁语 -atio，命名动作或结果。"},{"era":"ENGLISH (19th c.)","en":"Forestation is recorded in nineteenth-century writing on land improvement. It was used alongside afforestation and reforestation, which became the more technical terms.","cn":"forestation 见于十九世纪有关土地改良的写作。它与 afforestation、reforestation 并用，后两者后来成为更技术的术语。"},{"era":"FORESTRY (19th-20th c.)","en":"Forestry separated afforestation, planting on land without recent forest, from reforestation, replanting after loss. Forestation remained the general cover term.","cn":"林业把 afforestation（在近期无林地上栽植）与 reforestation（损失后补植）分开；forestation 则保留为总称。"},{"era":"ENGLISH (20th c.)","en":"State tree-planting programs and soil-conservation schemes made forestation a policy word with targets, budgets and measured areas.","cn":"国家植树计划与水土保持方案使 forestation 成为带有目标、预算与测量面积的政策词。"},{"era":"MODERN ENGLISH","en":"Climate policy added carbon forestation, where the purpose is storage of carbon rather than timber or soil protection.","cn":"气候政策增加了碳汇造林，其目的不是木材或水土保护，而是碳储存。"}]},"similar":{"note":{"en":"The first group is close in sound or shares the base; the second group names the same act at different scales or from the opposite direction.","cn":"第一组读音接近或共享基础词；第二组在不同尺度或相反方向上命名同一行为。"},"groups":[{"heading":"SOUND-ALIKE","entries":[{"word":"deforestation","ipa":"/ˌdiːˌfɒrɪˈsteɪʃn/","tag":"same base, opposite act","definition":"the removal of forest cover; it is the reverse process, not a variant spelling.","definitionCN":"毁林。除去森林覆盖，是相反过程，不是拼写变体。"},{"word":"afforestation","ipa":"/ˌæfɒrɪˈsteɪʃn/","tag":"near sound, specific type","definition":"planting a forest on land that has not recently been forested; it is a technical subtype of forestation.","definitionCN":"新造林。在近期无林的土地上造林，是 forestation 的技术子类。"},{"word":"reforestation","ipa":"/ˌriːfɒrɪˈsteɪʃn/","tag":"near sound, specific type","definition":"replanting land that was previously forested; it is another technical subtype.","definitionCN":"重新造林。在曾经有林的土地上补植，是另一个技术子类。"}]},{"heading":"NEAR-MEANING","entries":[{"word":"tree planting","ipa":"/triː ˈplɑːntɪŋ/","tag":"everyday activity","definition":"the everyday act of planting trees; it does not require the result to become a forest.","definitionCN":"植树。日常说法，不要求最终形成森林。"},{"word":"revegetation","ipa":"/ˌriːvedʒəˈteɪʃn/","tag":"broader restoration","definition":"the restoration of plant cover of any kind, not necessarily trees.","definitionCN":"植被恢复。恢复任何植物覆盖，不一定是树木。"},{"word":"afforestation","ipa":"/ˌæfɒrɪˈsteɪʃn/","tag":"specific subtype","definition":"the creation of new forest on bare or non-forest land; it is narrower than forestation.","definitionCN":"新造林。在裸地或非林地上建立新林，比 forestation 窄。"},{"word":"forest restoration","ipa":"/ˈfɒrɪst rɪstəˈreɪʃn/","tag":"ecological repair","definition":"the repair of a degraded forest's structure and function; it may involve natural regeneration, not only planting.","definitionCN":"森林恢复。修复退化森林的结构与功能，可能依靠自然更新，而不只是栽植。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The base is forest and the suffix -ation marks an action or its result.","cn":"基础词是 forest，后缀 -ation 标记动作或结果。"},{"en":"The technical pair is afforestation for new forest and reforestation for replanting.","cn":"技术上的配对是：afforestation 指新造林，reforestation 指重新造林。"},{"en":"Collocations: forestation program, forestation project, forestation rate.","cn":"搭配：造林计划、造林项目、造林速度。"},{"en":"Soil conservation and carbon policy are the two common policy frames.","cn":"水土保持与碳政策是两种常见的政策框架。"},{"en":"Forestation is the general word; tree planting is the everyday activity.","cn":"forestation 是总称；tree planting（植树）是日常活动。"}],"abstract":[{"en":"Picture a bare slope marked out in rows before a single seedling goes in.","cn":"想象一片裸坡在栽下第一株苗之前就被划成一排排。"},{"en":"Picture a hillside turning from brown to green over ten annual photographs.","cn":"想象同一片山坡在十张年度照片里从褐色变成绿色。"},{"en":"Picture a ledger where every hectare planted is entered as carbon stored.","cn":"想象一本账，每栽一公顷就记下一笔碳储存。"}]},"examples":[{"en":"The forestation project aimed to stabilise sand dunes along the coast.","cn":"这个造林项目旨在稳住沿海沙丘。"},{"en":"Forestation of the catchment reduced erosion within five years.","cn":"集水区造林在五年内减少了侵蚀。"},{"en":"Carbon forestation is only credited if the new forest survives.","cn":"只有新林存活，碳汇造林才被计入。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「森林 + 行动」——把一片地变成森林的整套动作 → 造林","word":"forestation"},"root":"由 forest 加拉丁来源后缀 -ation 构成；forest 经古法语来自中世纪拉丁语 forestis。afforestation 与 reforestation 在十九至二十世纪成为更细的技术术语；具体年代为大致估计。","sensesIntro":{"en":"Eight senses follow one act at different stages and scales: the umbrella act, the slow process, the two technical subtypes, the program, the resulting area, the climate purpose and the land-use change.","cn":"八个义项沿同一行为的不同阶段与尺度展开：总称行为、缓慢过程、两个技术子类、计划、结果面积、气候目的与土地用途改变。"},"semanticMap":{"core":{"en":"CORE IMAGE: a bare slope being turned into continuous green cover by deliberate planting.","cn":"核心意象：一片裸坡通过有意栽植变成连续的绿色覆盖。"},"chain":["BARE LAND","SURVEY AND PLAN","PLANT SEEDLINGS","FORM A CANOPY","MEASURE THE AREA","CHANGE LAND USE"],"branches":[{"senses":"01 · 02","en":"ACT AND PROCESS: one deliberate act seen as an event and as a decade-long process.","cn":"行为与过程：同一有意行为，既作事件看，也作十年过程看。"},{"senses":"03 · 04","en":"TWO HISTORIES: new forest on bare land and replanting after loss.","cn":"两种历史：裸地上的新林，与损失后的补植。"},{"senses":"05 · 06","en":"SCALE AND RESULT: a program and the area it produces.","cn":"规模与结果：计划以及它产生的面积。"},{"senses":"07","en":"CLIMATE PURPOSE: the forest is planted to store carbon.","cn":"气候目的：种林是为了储存碳。"},{"senses":"08","en":"LAND-USE CHANGE: forest replaces another use and alters water and soil.","cn":"土地用途改变：森林取代其他用途，并改变水土。"}]},"affixes":{"intro":{"en":"Forestation is a transparent English formation: a borrowed base plus a Latin-derived action suffix, with technical subtypes added by prefixes.","cn":"forestation 是透明的英语构造：借入基础词加拉丁来源动作后缀，技术子类由前缀补充。"},"latinIntro":{"en":"Medieval Latin forestis supplies forest; Latin -atio supplies -ation. The prefixes af- and re- create the two technical subtypes.","cn":"中世纪拉丁语 forestis 提供 forest；拉丁语 -atio 提供 -ation。前缀 af- 与 re- 造出两个技术子类。"},"latinEntries":[{"word":"forestis","structure":"forestis (silva) (Medieval Latin phrase)","meaning":"woodland outside the cultivated area","meaningCN":"耕地之外的林地"},{"word":"foris","structure":"foris (Latin adverb)","meaning":"outside, out of doors","meaningCN":"在外面；户外"},{"word":"atio","structure":"-atio, -ationis (Latin suffix)","meaning":"action or result","meaningCN":"动作或结果（后缀）"}],"items":[{"word":"forest","structure":"forestis via Old French forest","meaning":"a tree-covered area","meaningCN":"森林","example":"The forest gives shade and timber.","exampleCN":"森林提供阴凉与木材。"},{"word":"forestation","structure":"forest + -ation (action or result)","meaning":"the act or result of establishing forest","meaningCN":"造林；造林结果","example":"Forestation restored the bare slope.","exampleCN":"造林恢复了裸坡。"},{"word":"forestation program","structure":"forestation + program","meaning":"an organized planting scheme","meaningCN":"造林计划","example":"The program targets degraded land.","exampleCN":"该计划针对退化土地。"},{"word":"forestation rate","structure":"forestation + rate","meaning":"the speed of establishing forest","meaningCN":"造林速度","example":"The forestation rate doubled in five years.","exampleCN":"造林速度五年内翻了一倍。"},{"word":"afforestation","structure":"af- (to) + forest + -ation","meaning":"new forest on land without recent forest","meaningCN":"新造林","example":"Afforestation changed the pasture to wood.","exampleCN":"新造林把牧场变成林地。"},{"word":"reforestation","structure":"re- (again) + forest + -ation","meaning":"replanting after forest loss","meaningCN":"重新造林","example":"Reforestation followed the storm.","exampleCN":"风暴之后重新造林。"},{"word":"deforestation","structure":"de- (away) + forest + -ation","meaning":"removal of forest cover","meaningCN":"毁林","example":"Deforestation exposed the soil.","exampleCN":"毁林使土壤裸露。"},{"word":"forested","structure":"forest + -ed (having)","meaning":"covered with forest","meaningCN":"有森林覆盖的","example":"The upper valley is forested.","exampleCN":"上游谷地有森林覆盖。"},{"word":"forest restoration","structure":"forest + restoration","meaning":"repair of a degraded forest","meaningCN":"森林恢复","example":"Restoration may rely on natural regeneration.","exampleCN":"森林恢复可能依靠自然更新。"}]}},{"word":"deforestation","ipa_uk":"/ˌdiːˌfɒrɪˈsteɪʃn/","ipa_us":"/ˌdiːˌfɔːrɪˈsteɪʃn/","definition_zh":"毁林；森林砍伐；森林覆盖的丧失","definition_en":"the removal or clearing of forest cover, usually to convert the land to another use","core_image":"推土机沿山坡推进，成片的树倒下后被烧掉，裸露的红土被雨水冲成沟壑","scene":"推土机沿山坡推进，成片的树倒下后被烧掉，裸露的红土在雨季被冲成沟壑。 Bulldozers moved along the slope, felled trees were burned in heaps, and the bare red soil was cut into gullies by the rains: this is deforestation.","sceneCN":"这里该词指「把森林清除掉的过程」（第 1 个义项：森林被砍伐清除）；句意为推土机沿坡推进，伐倒的树被烧掉，裸露红土被雨水冲出沟壑，这就是毁林。","pos":[{"tag":"n.","zh":"毁林；森林砍伐"},{"tag":"n.","zh":"森林覆盖的丧失过程"},{"tag":"n.","zh":"把林地转为其他用途"},{"tag":"n.","zh":"大规模商业采伐"},{"tag":"n.","zh":"被清除后的状态或结果"},{"tag":"n.","zh":"热带雨林砍伐"},{"tag":"n.","zh":"作为环境驱动因素的毁林"},{"tag":"n.","zh":"历史上为农业而进行的林地清除"}],"collocations":[{"phrase":"tropical deforestation","zh":"热带毁林"},{"phrase":"deforestation rate","zh":"毁林速度"},{"phrase":"deforestation driver","zh":"毁林驱动因素"},{"phrase":"combat deforestation","zh":"遏制毁林"},{"phrase":"deforestation-free supply chain","zh":"零毁林供应链"},{"phrase":"illegal deforestation","zh":"非法毁林"}],"forms":[{"label":"复数（多起毁林事件）","form":"deforestations"},{"label":"相关动词（清除森林）","form":"deforest"},{"label":"相关名词（造林）","form":"forestation"},{"label":"相关名词（重新造林）","form":"reforestation"},{"label":"形容词（被毁林的）","form":"deforested"}],"derivatives":[{"word":"deforest","pos":"v.","zh":"清除森林；砍伐林地"},{"word":"deforested","pos":"adj.","zh":"森林被清除的"},{"word":"deforestation-free","pos":"adj.","zh":"不涉及毁林的"},{"word":"forestation","pos":"n.","zh":"造林"},{"word":"reforestation","pos":"n.","zh":"重新造林"}],"senses":[{"no":"01","title":"Clearing forest","titleCN":"清除森林","definition":"the act of cutting or burning forest to remove tree cover","definitionCN":"通过砍伐或焚烧除去森林覆盖的行为","example":"Deforestation begins with roads cut into the forest edge.","exampleCN":"毁林从在森林边缘开出道路开始。","why":"This is the core act sense: the trees are deliberately removed.","whyCN":"这是核心行为义：树木被有意清除。"},{"no":"02","title":"Loss of forest cover","titleCN":"森林覆盖的丧失","definition":"the process by which a forested area loses its tree cover over time","definitionCN":"林地在时间中失去树木覆盖的过程","example":"Satellite images showed deforestation spreading along the river.","exampleCN":"卫星图像显示毁林沿河流蔓延。","why":"The act is now viewed as a process measured in area and time.","whyCN":"行为此时被看作以面积和时间衡量的过程。"},{"no":"03","title":"Conversion to other land use","titleCN":"林地转为其他用途","definition":"the change of forest land into farmland, pasture, settlement or infrastructure","definitionCN":"把林地改为农田、牧场、居民点或基础设施","example":"Much deforestation here is conversion to cattle pasture.","exampleCN":"这里的毁林大多是改为养牛牧场。","why":"The word names the loss from the forest's side, while land-use writing names the gain from the new use's side.","whyCN":"这个词从森林一侧命名损失，而土地利用写作从新用途一侧命名获得。"},{"no":"04","title":"Large-scale logging","titleCN":"大规模商业采伐","definition":"the removal of timber over large areas, often for export or industry","definitionCN":"在大面积上采伐木材，常为出口或工业原料","example":"Selective logging is not the same as deforestation.","exampleCN":"选择性采伐与毁林不是一回事。","why":"Logging removes trees; deforestation means the forest cover does not return.","whyCN":"采伐移走树木；毁林意味着森林覆盖不再恢复。"},{"no":"05","title":"Cleared state","titleCN":"被清除后的状态","definition":"the condition of land after its forest has been removed","definitionCN":"森林被除去后土地所处的状态","example":"The deforested slope lost its soil within two seasons.","exampleCN":"被毁林的山坡在两个季节内就失去了土壤。","why":"The action noun also names the resulting landscape, which is what later restoration must address.","whyCN":"动作名词也命名结果景观，而这正是后来恢复要面对的对象。"},{"no":"06","title":"Tropical deforestation","titleCN":"热带毁林","definition":"the clearing of tropical forests, especially for agriculture and ranching","definitionCN":"热带森林的清除，尤因农业与牧业","example":"Tropical deforestation accounts for a large share of emissions.","exampleCN":"热带毁林占排放的很大一部分。","why":"The general word is attached to its most politically visible setting.","whyCN":"这个总称词被固定在其最受关注的具体场景上。"},{"no":"07","title":"Environmental driver","titleCN":"环境驱动因素","definition":"deforestation considered as a cause of biodiversity loss, erosion and carbon emissions","definitionCN":"把毁林看作生物多样性丧失、侵蚀与碳排放的原因","example":"The report links deforestation to both flooding and species decline.","exampleCN":"报告把毁林与洪水及物种减少都联系起来。","why":"The word shifts from an event to a causal factor in environmental systems.","whyCN":"这个词从事件转成环境系统中的因果因素。"},{"no":"08","title":"Historical clearance","titleCN":"历史上的林地清除","definition":"the clearing of forest in earlier periods, often for farming or fuel","definitionCN":"较早时期为农业或燃料而清除森林","example":"Medieval deforestation left only small woods on the ridge.","exampleCN":"中世纪的毁林只在山脊上留下小片树林。","why":"The modern word is applied retrospectively to older land-use change.","whyCN":"现代词被追溯用于更早的土地用途改变。"}],"etymology":{"intro":{"en":"Deforestation is a nineteenth-century formation on de- plus forestation. Its rise as a global environmental term belongs to the twentieth century, and the first date is approximate.","cn":"该词为十九世纪由 de- 加 forestation 构成；成为全球环境术语主要在二十世纪，确切首见年代为大致估计。"},"items":[{"era":"LATIN AND FRENCH ELEMENTS","en":"The prefix de- means 'away, down, reversing'. Forest comes from Medieval Latin forestis through Old French, and -ation from Latin -atio marks an action or result.","cn":"前缀 de- 意为「离开、向下、反转」。forest 经古法语来自中世纪拉丁语 forestis，-ation 来自拉丁语 -atio，标记动作或结果。"},{"era":"ENGLISH (19th c.)","en":"Deforestation is recorded in nineteenth-century writing on land use, often in descriptions of clearing for farms or fuel. French déforestation may have reinforced the form.","cn":"deforestation 见于十九世纪有关土地利用的写作，常描述为农田或燃料而进行的清除。法语 déforestation 可能强化了这一形式。"},{"era":"ENGLISH (20th c.)","en":"The term became global with tropical forest loss after the mid-twentieth century, when satellites made the loss visible as area and rate.","cn":"二十世纪中期以后，随着热带森林丧失，这个词走向全球；卫星让损失以面积与速度变得可见。"},{"era":"ENVIRONMENTAL POLICY (late 20th c.)","en":"Climate and biodiversity policy made deforestation a driver to be measured, reported and regulated, including through zero-deforestation supply chains.","cn":"气候与生物多样性政策把毁林变成需要测量、报告与监管的驱动因素，包括零毁林供应链。"},{"era":"MODERN ENGLISH","en":"The word now covers deliberate clearing, agricultural conversion and the resulting loss of cover, and is often used retrospectively for earlier centuries.","cn":"这个词现在涵盖有意清除、农业转换以及由此造成的覆盖丧失，也常被追溯用于更早的世纪。"}]},"similar":{"note":{"en":"The first group is close in form but names a different act or a different scale; the second group shares the removal or loss meaning without being interchangeable.","cn":"第一组在形式上接近，但命名不同行为或不同尺度；第二组共享清除或丧失的意思，但不能互换。"},"groups":[{"heading":"FORM-ALIKE","entries":[{"word":"forestation","ipa":"/ˌfɒrɪˈsteɪʃn/","tag":"opposite act","definition":"the establishment of forest cover; it is the reverse of deforestation, not a synonym.","definitionCN":"造林。建立森林覆盖，是毁林的相反过程，不是同义词。"},{"word":"afforestation","ipa":"/ˌæfɒrɪˈsteɪʃn/","tag":"new forest subtype","definition":"planting forest on land without recent forest; it is a kind of forestation, not a kind of deforestation.","definitionCN":"新造林。在近期无林地上造林，是造林的一种，不是毁林的一种。"},{"word":"deformation","ipa":"/ˌdiːfɔːˈmeɪʃn/","tag":"near sound, different root","definition":"a change of shape, from forma 'form'; it has no forest element.","definitionCN":"变形。来自 forma「形状」，不含森林成分。"}]},{"heading":"NEAR-MEANING","entries":[{"word":"clearance","ipa":"/ˈklɪərəns/","tag":"general removal","definition":"the general removal of trees or obstacles from land; it can be small-scale and need not mean permanent forest loss.","definitionCN":"清除；清理。从土地上移除树木或障碍，可小规模，也不必然意味着永久失去森林。"},{"word":"logging","ipa":"/ˈlɒɡɪŋ/","tag":"timber activity","definition":"the cutting and transporting of timber; it may leave the forest able to regenerate, unlike deforestation.","definitionCN":"伐木。砍伐与运输木材，森林可能仍能更新，不像毁林那样。"},{"word":"land clearing","ipa":"/lænd ˈklɪərɪŋ/","tag":"land-use phrase","definition":"the removal of vegetation to prepare land for another use; it is the purpose-neutral description of the same act.","definitionCN":"土地清理。为准备其他用途而清除植被，是对同一行为的用途中立描述。"},{"word":"forest loss","ipa":"/ˈfɒrɪst lɒs/","tag":"outcome phrase","definition":"the net loss of forest area or quality; it includes degradation as well as complete clearing.","definitionCN":"森林丧失。森林面积或质量的净损失，包括退化与完全清除。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The word is de- 'away' plus forestation, so it literally means the undoing of forest creation.","cn":"这个词是 de-「去除」加 forestation，字面就是「取消造林的结果」。"},{"en":"The family runs deforest, deforested, deforestation-free and reforestation.","cn":"同族词包括 deforest、deforested、deforestation-free 与 reforestation。"},{"en":"Collocations: tropical deforestation, deforestation rate, deforestation driver.","cn":"搭配：热带毁林、毁林速度、毁林驱动因素。"},{"en":"Logging removes trees, but deforestation means the cover does not return.","cn":"伐木移走树木，但毁林意味着覆盖不再恢复。"},{"en":"Zero-deforestation supply chains are a policy instrument of the 2010s.","cn":"零毁林供应链是二十一世纪一十年代的政策工具。"}],"abstract":[{"en":"Picture a road pushed into intact forest, with bare ground widening behind it.","cn":"想象一条路推进完整森林，后面裸地不断变宽。"},{"en":"Picture a satellite image where a green block turns brown year by year.","cn":"想象卫星图上一块绿色逐年变褐。"},{"en":"Picture smoke from burned felled trees rising over a hillside of stumps.","cn":"想象被烧的伐倒木冒烟，下方是布满树桩的山坡。"}]},"examples":[{"en":"Deforestation in the basin reduced dry-season water storage.","cn":"流域内的毁林减少了旱季的蓄水量。"},{"en":"The company pledged to remove deforestation from its supply chain.","cn":"该公司承诺从供应链中消除毁林。"},{"en":"Historical deforestation left the ridge with thin, eroded soils.","cn":"历史上的林地清除让山脊只剩薄而受侵蚀的土壤。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「去掉 + 森林」——把森林覆盖从土地上拿掉 → 毁林","word":"deforestation"},"root":"由 de-「去除」加 forestation 构成，十九世纪见于土地利用写作；forest 经古法语来自中世纪拉丁语 forestis。作为全球环境术语主要在二十世纪流行，确切首见年代为大致估计。","sensesIntro":{"en":"Eight senses move from the act of clearing to the process of loss, the land-use conversion, the logging that may or may not cause it, the resulting landscape, the tropical setting, the environmental causal role and retrospective historical clearance.","cn":"八个义项从清除行为，到丧失过程、土地用途转换、可能造成也可能不造成毁林的采伐、结果景观、热带场景、环境因果角色，再到追溯性的历史林地清除。"},"semanticMap":{"core":{"en":"CORE IMAGE: a green block being cut back to bare soil, year after year.","cn":"核心意象：一块绿色被逐年削回裸土。"},"chain":["TREES CUT","COVER REMOVED","LAND CONVERTED","SOIL EXPOSED","SPECIES LOST","HISTORY REPEATED"],"branches":[{"senses":"01 · 02","en":"ACT AND PROCESS: deliberate clearing and the measured loss it produces.","cn":"行为与过程：有意清除，以及它造成的可测丧失。"},{"senses":"03 · 04","en":"CONVERSION AND LOGGING: one changes the use, the other removes timber; only the first is necessarily deforestation.","cn":"转换与采伐：前者改变用途，后者移走木材；只有前者必然是毁林。"},{"senses":"05","en":"THE BARE RESULT: land left without its cover.","cn":"裸露的结果：失去覆盖后的土地。"},{"senses":"06 · 07","en":"TROPICS AND DRIVERS: the most visible setting and the causal role in climate and biodiversity.","cn":"热带与驱动：最显眼的场景，以及在气候与生物多样性中的因果角色。"},{"senses":"08","en":"RETROSPECT: the modern word applied to old land-use change.","cn":"回溯：现代词用于旧的土地用途改变。"}]},"affixes":{"intro":{"en":"Deforestation is a transparent English formation whose parts come from Latin and French; the affix section separates the reversing prefix from the forest base and the action suffix.","cn":"deforestation 是透明的英语构造，各成分来自拉丁语与法语；词缀部分把反转前缀与森林基础词、动作后缀分开。"},"latinIntro":{"en":"Latin de- supplies the reversing prefix, Medieval Latin forestis supplies the base, and Latin -atio supplies the action suffix. The French form may have reinforced the English one.","cn":"拉丁语 de- 提供反转前缀，中世纪拉丁语 forestis 提供基础，拉丁语 -atio 提供动作后缀。法语形式可能强化了英语形式。"},"latinEntries":[{"word":"de-","structure":"de- (Latin prefix)","meaning":"away, down, reversing","meaningCN":"离开；向下；反转"},{"word":"forestis","structure":"forestis (silva) (Medieval Latin phrase)","meaning":"woodland outside the cultivated area","meaningCN":"耕地之外的林地"},{"word":"foris","structure":"foris (Latin adverb)","meaning":"outside, out of doors","meaningCN":"在外面；户外"},{"word":"atio","structure":"-atio, -ationis (Latin suffix)","meaning":"action or result","meaningCN":"动作或结果（后缀）"}],"items":[{"word":"deforestation","structure":"de- + forest + -ation","meaning":"the removal of forest cover","meaningCN":"毁林","example":"Deforestation exposed the hillside.","exampleCN":"毁林使山坡裸露。"},{"word":"deforest","structure":"de- + forest (verb)","meaning":"to clear forest from land","meaningCN":"清除森林","example":"The company was fined for deforesting the reserve.","exampleCN":"该公司因清除保护区森林被罚款。"},{"word":"deforested","structure":"deforest + -ed (past participle)","meaning":"having lost its forest","meaningCN":"森林被清除的","example":"The deforested slope eroded quickly.","exampleCN":"被毁林的山坡迅速侵蚀。"},{"word":"deforestation-free","structure":"deforestation + free (without)","meaning":"not involving deforestation","meaningCN":"不涉及毁林的","example":"The label marks a deforestation-free product.","exampleCN":"这个标签标记零毁林产品。"},{"word":"forestation","structure":"forest + -ation","meaning":"the establishment of forest","meaningCN":"造林","example":"Forestation followed the cleared strip.","exampleCN":"被清除的地带随后进行了造林。"},{"word":"reforestation","structure":"re- + forest + -ation","meaning":"replanting after loss","meaningCN":"重新造林","example":"Reforestation slowed the erosion.","exampleCN":"重新造林减缓了侵蚀。"},{"word":"forest","structure":"forestis via Old French","meaning":"a tree-covered area","meaningCN":"森林","example":"The forest once covered the whole basin.","exampleCN":"森林曾覆盖整个流域。"},{"word":"forest loss","structure":"forest + loss","meaning":"net loss of forest area or quality","meaningCN":"森林丧失","example":"Forest loss includes degradation.","exampleCN":"森林丧失也包括退化。"},{"word":"land clearing","structure":"land + clearing","meaning":"removal of vegetation for another use","meaningCN":"土地清理","example":"Land clearing is the purpose-neutral description.","exampleCN":"土地清理是用途中立的描述。"}]}}]);
